export default [{"id":29,"question":"ذهبنا مع بعض الأصدقاء إلى رحلة خارج الرياض، وبالضبط في الثمامة، فخرجنا يوم الأربعاء في الليل، فحينما جاء وقت النوم نمنا، فلما أصبحنا على يوم الخميس، وجدتُ نفسي قد احتلمتُ، وأصبحت علي جنابة، ونحن عددنا أربعة، ولا يوجد معنا غير جالون ماء للشرب والأكل، فأخبرتُ أحد الأصدقاء بما حدث لي، فقال لي: تعفَّر، وصلِّ معنا الفجر، يجوز لك ذلك، فعملتُ ما أمرني به، ولما جاء، وقت صلاة الظهر شككتُ في الأمر، ولم أصلِّ معهم جميع الأوقات من فجر يوم الخميس إلى عشاء ليلة السبت في نهار الجمعة، فلما ذهبنا إلى الرياض صليتها بعد أن اغتسلتُ، وبدون أن أقْصُر في جميع الأوقات فيما فاتني، فماذا عليَّ في ذلك؟","title":"حكم من احتلم في صحراء ولم يجد ماءً للغسل","answer":"الجواب: الواجب عليك إذا وقع مثل هذا أن تنظر، إن وجدتَ ماءً قريبًا منك تستطيع الغسل به فعلتَ، ووجب عليك ذلك، فإن لم تجد تيممت كما قال لك صاحبك، تعفَّرت بالتراب وكفى؛ لأن الله  يقول: فَلَمْ تَجِدُوا مَاءً فَتَيَمَّمُوا صَعِيدًا طَيِّبًا [النساء:43]، ويقول النبي ﷺ: وجُعِلَت لي الأرض مسجدًا وطهورًا فأيما رجل من أمتي أدركته الصلاة فعنده مسجده وطهوره، ويقول ﷺ: وجُعِلَ التراب لي طهورًا إذا لم نجد الماء، فمن لم يجد الماء فالصعيد، وضوءه.\nفعليك إذا فقدتَ الماء في أي مكان أن تتيمم، وتضرب التراب بيديك، وتمسح به وجهك، وكفيك كما أمر الله  وتصلي، وليس عليك إعادة، تجزئ، وإذا كنتَ في محل فيه ماء وجب عليك الغسل، وإذا كان الوقت باردًا سخَّنته بالنار، وإذا لم تجد نارًا وخشيت على نفسك بسبب شدة البرد؛ تيممتَ وصليت، وأجزأك، والحمد لله.\nوأما تركك لصلاة معهم المدة الطويلة يوم الخميس والجمعة، فهذا غلط وخطأ منك، فعليك التوبة إلى الله من ذلك، والندم على ما مضى منك، وعدم العودة إلى ذلك، وقد أحسنتَ في قضاء الصلاة لَمَّا تمكنت من الماء؛ ولكنك أخطأت في تركها، وفي التأخير.\nفالواجب التوبة من ذلك، وألا تؤخرها عن وقتها، إن وجدتَ ماءً فاغتسل، وإلا فتيمم وصلِّ، ولا تؤخرها عن وقتها أبدًا.","link":"https://binbaz.org.sa/fatwas/2809/حكم-من-احتلم-في-صحراء-ولم-يجد-ماء-للغسل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0002.mp3","categories":["الغسل","التيمم","وقت الصلاة"]},{"id":44,"question":"أنا أعمل موظفًا في الهاتف السعودي، والمراقب المسئول يمنعني من تأدية الصلاة في وقت العمل، مع العلم أن المسجد مقابل مبنى الهاتف، فما هو رأي سماحتكم في ذلك؟","title":"حكم تأخير الصلاة للموكّل بأمانة أو حراسة","answer":"الجواب: الواجب عليك أن تصلي في محلك؛ لأنك تشبه الحارس، الحارس إذا كان حارسًا على مال، أو على مزرعة، أو غيرها، يصلي في محله، ولا يلزمه جماعة، إذا كان ذهابه إلى الجماعة يفوِّت الحراسة، وربما جاء في الهاتف ما يدعو إلى الحذر، والحاصل أن من وُكل إليه الهاتف المهم للمسلمين يكون بمثابة الحارس الذي يصلي عند محل الحراسة.\nأما أن يضيع الوقت، لا، يجب أن يصلي في الوقت، ولو قدِّر أن الهاتف تكلم؛ فإن مدة الصلاة مدة قليلة، خمس دقائق أو أقل من ذلك.\nفالواجب أن تصلي الصلاة في الوقت، ولا يجوز أن تُهمل من أجل الحراسة، ولا من أجل الهاتف.\nفإذا كان هناك ضرورة وجب التناوب، فيُجعل هذا الحارس ينوب بعض الوقت، ثم يذهب ويصلي، ويأتي الحارس الآخر وقد صلى، فينوب عنه.\nأما أن يوكَل إليه حراسة تمنعه من الصلاة؛ فهذا ظلم، ولا يجوز.","link":"https://binbaz.org.sa/fatwas/2824/حكم-تاخير-الصلاة-للموكل-بامانة-او-حراسة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0017.mp3","categories":["الغسل","التيمم","وقت الصلاة"]},{"id":357,"question":"هل للذي تفوته صلاةُ الفجر أو صلاةُ العصر أو بوجهٍ عامٍّ أي فرضٍ من الفروض الخمسة دون قصدٍ منه: هل يُحتسب له الأجر مثل الصلاة على وقتها إذا فعل ذلك بدون قصدٍ؟","title":"حكم من فاته وقت الصلاة سهواً دون تفريط","answer":"الجواب: مَن فاتته الصلاةُ من دون تفريطٍ منه فإنه يُرجى له أجر مَن صلَّاها في الوقت مع الجماعة، يقول النبي عليه الصلاة والسلام: إذا سافر العبدُ أو مرض كتب الله له ما كان يعمل وهو صحيحٌ مقيمٌ،  من أجل العذر، إذا سافر أو مرض كتب الله له ما كان يعمل وهو صحيحٌ.\nوقال في يوم تبوك: إنَّ في المدينة أقوامًا ما سرتم مسيرًا ولا قطعتُم واديًا إلا وهم معكم، حبسهم العذر، وفي اللفظ الآخر: إلا شركوكم في الأجر.\nفدلَّ ذلك على أنَّ الذي يفوته الواجبُ وهو معذورٌ شرعًا فإنه يكون له أجر مَن حضر، إذا كان تخلّفه من أجل العذر، مثلًا: قام للصلاة لما سمع الأذان، فهجمت عليه حاجةٌ من بولٍ أو غائطٍ، فذهب ليقضي حاجته، فلم يتمكّن من إدراك الصلاة، فإنه يكون حكمه حكم مَن أدركها؛ لأنه معذورٌ بعذرٍ شرعيٍّ، وهكذا مَن عادته أنه يُصلي الرواتب مع الفرائض، فاشتدَّ به المرض فلم يستطع إلا أداء الفريضة، فإنه يُكتب له ما كان يعمل في حال الصحة من تعاطي النوافل.","link":"https://binbaz.org.sa/fatwas/4551/حكم-من-فاته-وقت-الصلاة-سهوا-دون-تفريط","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0410.mp3","categories":["وقت الصلاة"]},{"id":474,"question":"الآية: فَامْسَحُواْ بِوُجُوهِكُمْ وَأَيْدِيكُم مِّنْهُ [المائدة:6] أي من الغبار؟","title":"ما معنى {فَامْسَحُواْ بِوُجُوهِكُمْ وَأَيْدِيكُم مِّنْهُ}؟","answer":"الجواب: من التراب الصعيد يعني فَتَيَمَّمُواْ صَعِيداً طَيِّباً[المائدة:6]، إذا تيسر فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ[التغابن:16]","link":"https://binbaz.org.sa/fatwas/6199/ما-معنى-فامسحوا-بوجوهكم-وايديكم-منه","audio":"https://files.zadapps.info/binbaz.org.sa/AYA034.mp3","categories":["الغسل","التيمم","وقت الصلاة"]},{"id":475,"question":"الغسل ورد عن رسول الله ﷺ صفتين في صفة الغُسْل، أحسن الله إليك؟","title":"ما صفة الغُسْل الوادرة عن النبي ﷺ؟","answer":"الجواب: المعروف عن عائشة وعن ميمونة هو الوضوء ثم إفاضة الماء، وجاء عن  ميمونة: أنه يغسل قدميه في مكان آخر.\n(دروس شرح بلوغ المرام، كتاب الطهارة)","link":"https://binbaz.org.sa/fatwas/6200/ما-صفة-الغسل-الوادرة-عن-النبي-ﷺ","audio":"https://files.zadapps.info/binbaz.org.sa/3osl035.mp3","categories":["الغسل","التيمم","وقت الصلاة"]},{"id":756,"question":"ما حكم مَن أخَّر الصلاة عن وقتها لعذرٍ؟ وهل يجوز أن يُصليها بعد الصلاة التي تليها أو أنه يُؤخِّرها إلى اليوم القادم ليُصليها مع أختها المُماثلة لها؟ أفيدونا.","title":"ما حكم من أخّر الصلاة عن وقتها لعذر؟","answer":"الجواب: الواجب ألا تُؤخّر الصلاة عن وقتها، بل يجب أن تُصلى في وقتها ولو جمعًا مع مَن تُجمع إليه: كالمغرب مع العشاء، والظهر مع العصر، إذا كان مريضًا جمعها مع رفيقتها، الظهر مع العصر، والمغرب مع العشاء، وهكذا إذا كان مُسافرًا جمعهما، فالمريض والمسافر يجمع بين الظهر والعصر، والمغرب والعشاء، ولا يؤخر إلى وقتٍ آخر، فلا يؤخر المغرب والعشاء إلى بعد نصف الليل، ولا يُؤخر الظهر والعصر إلى بعد اصفرار الشمس، أو بعد غروب الشمس، لا، بل يُبادر بالوقت. فإذا أخَّرها -إمَّا نسيانًا أو لنومٍ- بادر بها من حين أن ينتبه، يستيقظ أو يَذْكُر، يُبادر بها، ولا يُؤخّرها إلى الصلاة الأخرى، لا، بل يُبادر بها، كما قال النبيُّ ﷺ: مَن نام عن الصلاة أو نسيها فليُصلها إذا ذكرها..... في الليل ونام في أول الليل عن العشاء، بادر بها ولم يُؤخِّرها، وهكذا في الظهر والعصر لو نام فلم يستيقظ إلا بعدما اصفرت الشمسُ؛ بادر بها في الحال، صلَّى الظهر والعصر، وإن لم يستيقظ إلا بعد المغرب بادر بها وصلَّاها قبل المغرب، صلَّى الظهر والعصر ثم صلى المغرب.\nالمقصود أنه يُبادر بها من حين يذكر إن كان ناسيًا، أو من حين يزول العذر إن كان نائمًا إذا استيقظ، وأما المريض فلا يُؤخّرها أبدًا، يُصليها في الوقت على حاله، ولو على جنبه، إذا عجز عن القيام صلَّى قاعدًا، وإذا عجز عن القعود صلَّى على جنبه، وإذا عجز عن الجنب صلى مُستلقيًا، لا يُؤخِّرها، يُصليها في الوقت ولو قاعدًا، أو على جنبه، أو مُستلقيًا، ولو مجموعة مع أختها: الظهر مع العصر، والمغرب مع العشاء، ولا يؤخر ولو كان مريضًا، الله يقول: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]، والنبي ﷺ يقول للمريض: صلِّ قائمًا، فإن لم تستطع فقاعدًا، فإن لم تستطع فعلى جنبٍ، فإن لم تستطع فمُستلقيًا، كل هذا من تيسير الله  ورحمته ورأفته بعباده.","link":"https://binbaz.org.sa/fatwas/20635/ما-حكم-من-اخر-الصلاة-عن-وقتها-لعذر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0561ما حكم من أخر الصلاة عن وقتها لعذر ابن باز فتاوى المحاضرات.mp3","categories":["وقت الصلاة"]},{"id":825,"question":"شخصٌ رأى في ثوبه أثرَ احتلامٍ، وتذكر أنه رأى في منامه ما سبب هذا منذ أربعة أو خمسة أيام، لا يدري أنه احتلم، ولم يدرِ عن ذلك، وصلَّى صلوات، فلما رأى هذا الأثر اغتسل، فماذا عليه؟ هل يُعيد صلاته التي صلَّاها هذه الفترة وهو لا يدري؟","title":"حكم مَن رأى أثر احتلام مضت عليه أيام","answer":"الجواب: إذا علم أنها مني فعليه أن يُعيد بعد آخر نومةٍ نامها؛ لأن هذا هو المتيقن، فإذا كان مثلًا رآها العصر، وآخر نومةٍ الضُّحى –الصبح- فهو يُعيد الظهر والعصر، وإذا كانت آخر نومةٍ الظهر، وما رآها إلا بعد العصر، يُعيد العصر، وهكذا، يعني: من آخر نومةٍ نامها ثم رأى المني يُعيد الصلاة التي بعد النومة؛ لأن الظاهر أنها من النومة الأخيرة، ولا يعمّم على النومات السَّابقات.","link":"https://binbaz.org.sa/fatwas/20866/حكم-من-راى-اثر-احتلام-مضت-عليه-ايام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0661شخص رأي في ثوبه أثر احتلام وتذكر أنه رأى في منامه ماسبب هذا فما الحكم؟ابن باز.mp3","categories":["الغسل","التيمم","وقت الصلاة"]},{"id":927,"question":"من المعلوم أنَّ المريض بعد إجراء العملية الجراحية يبقى مُخدَّرًا حتى يفيق، وبعد ذلك يبقى متألِّمًا من العملية لساعات، فهل يُصلي قبل دخول العملية، والوقت في الصلاة لم يَحِن بعد، أم يُؤخّر الصلاة حتى يكون قادرًا على أدائها بالحضور الحسي، ولو تأخَّر ذلك أكثر من يومٍ؟","title":"حكم ما يفوت من صلوات لإجراء جراحة","answer":"الجواب: الواجب أولًا على الطبيب أن ينظر في الأمر: فإذا أمكن أن يتأخَّر بدء العلاج حتى يدخل الوقتُ ويُصلي الظهر والعصر جميعًا إذا دخل وقتُ الظهر، أو المغرب في الليل، إذا دخل المغربُ صلَّى المغرب والعشاء جميعًا، أما إذا كان العلاجُ..... فإنَّ المريض معذورٌ، فإذا أفاق صلَّى، قضى ما عليه ولو بعد..... متى أفاق قضى ما عليه، والحمد لله، ولا شيء عليه، مثل: النائم إذا أفاق وانتبه ورجع إليه وعيُه صلَّى الأوقات التي فاتته على الترتيب، يُرتِّبها: الظهر، العصر، المغرب، العشاء، على الترتيب، والحمد لله، ولا حرجَ عليه.","link":"https://binbaz.org.sa/fatwas/20957/حكم-ما-يفوت-من-صلوات-لاجراء-جراحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0753هل يجوزأن يصلي قبل دخول العملية والوقت للصلاة لم يحن بعد أو يؤخر الصلاة بعد العملية؟ ابن باز.mp3","categories":["وقت الصلاة","صلاة المريض"]},{"id":1016,"question":"ما حكم مَن أخَّر صلاة الفجر إلى ما بعد طلوع الشمس، وتكرر منه ذلك، ليس تعمُّدًا أو تساهلًا، وإنما لسلطان النوم؟ فهل عليه إثمٌ في ذلك، علمًا بأنه محافظٌ على بقية الصَّلوات في المسجد؟","title":"حكم تأخير صلاة الفجر لغَلَبَة النوم دون عمد","answer":"الجواب: الشيخ: عليه أن يفعل الأسباب، ويتَّقي الله: بوضع الساعة التي تُعينه على معرفة الوقت، يُرتِّبها على وقت الفجر حتى يسمع التَّنبيه، أو بأهله يُوقظونه ويُؤكِّد عليهم، ولا يُصَيِّف، لا يسهر، فإذا فعل الأسباب وغلبه النومُ فلا شيء عليه.\nقد ثبت عنه ﷺ أنهم نزلوا في بعض الأسفار في أثناء الليل وغلبهم النومُ، حتى أنهم ما استيقظوا إلا بحرِّ الشمس، وفيهم رسولُ الله عليه الصلاة والسلام، فقام وأمر بالأذان، فتحوَّلوا عن مكانهم، وتوضَّؤوا، وصلَّى السنة الراتبة، ثم صلَّى بالناس، مع أنه أمر بلالًا أن يضبط الصبح، ويُراعي الصبح، لكن نام بلالٌ أيضًا معهم كما ناموا وغلبه النوم.\nفالإنسان إذا فعل الأسبابَ واجتهد وغلبه النومُ لا شيء عليه. أما إنسانٌ ما يُرَكِّب ساعةً، ولا يُبَكِّر، ويقول: غلبني النوم، كذَّابٌ، هذا قاصدٌ النوم عن الصلاة، فهو آثمٌ، يسهر ويريد أن ينام على كل حالٍ، ثم لا يُوقّت الساعة على وقت الصلاة، هذا مُتعمّدٌ، في حكم المتعمد.","link":"https://binbaz.org.sa/fatwas/21060/حكم-تاخير-صلاة-الفجر-لغلبة-النوم-دون-عمد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0856ما حكم من أخر صلاة الفجر إلى ما بعد طلوع الشمس وتكرر منه ذلك ليس تعمداً وإنما سلطان النوم؟.mp3","categories":["وقت الصلاة"]},{"id":1070,"question":"هل يُجزئ الغُسل عن الوضوء لأداء الصَّلاة؟","title":"هل يُجزئ الغُسل عن الوضوء لأداء الصَّلاة؟","answer":"الجواب:\nإذا كان الغسلُ للجنابة ونويتَ الحدثين؛ أجزأ. ولكن كونك تتوضأ كما توضأ النبيُّ ﷺ، ثم تغتسل، هذا هو الأكمل والأفضل. أما الغسل المستحبّ: كالجمعة، أو للتَّبرد، أو لإزالة الوسخ؛ فلا، لا بدّ من الوضوء، توضأ قبله أو بعده.","link":"https://binbaz.org.sa/fatwas/21112/هل-يجزى-الغسل-عن-الوضوء-لاداء-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0908هل يجزء الغسل عن الوضوء لأداء الصلاة ؟ ابن باز فتاوى المحاضرات.mp3","categories":["الغسل","التيمم","وقت الصلاة"]},{"id":1175,"question":"ما حكم مَن يتعمَّد تأخير صلاة الفجر حتى خروج وقتها، حيث إنَّ أغلب الناس يُوقِّتون الساعة على وقت أعمالهم، ويُؤدُّونها بعد ذلك، فما حكم عملهم هذا؟","title":"حكم مَن يتعمَّد تأخير صلاة الفجر عن وقتها","answer":"الجواب:\nتقدَّم التَّنبيه على هذا: أنه لا يجوز للإنسان أن يُؤخِّر الصلاة عن وقتها، لا الفجر، ولا غيرها، يجب على كل مؤمنٍ أن يُصليها في الوقت، وأن يُصليها في المسجد إذا كان قادرًا.  وإن كان مريضًا أو عاجزًا صلَّاها في البيت في وقتها. وأما القادر فيلزمه أن يُصلي في الجماعة؛ لقول النبي ﷺ: مَن سمع النِّداء فلم يأتِ فلا صلاةَ له إلا من عذرٍ، قيل لابن عباسٍ: ما هو العذر؟ قال: \"خوفٌ أو مرضٌ\".\nوجاءه ﷺ رجلٌ أعمى فقال: يا رسول الله، ليس لي قائدٌ يقودني إلى المسجد، فهل لي من رخصةٍ أن أُصلي في بيتي؟ فقال عليه الصلاة والسلام: هل تسمع النِّداء بالصلاة؟ قال: نعم، قال: فأجب.\nوثبت عنه ﷺ أنه همَّ أن يُحَرِّق على المتخلفين بيوتهم، فالواجب على المؤمن الحذر من ذلك.\nوأما كونه يُركِّب الساعة على وقت العمل، ويُؤخِّر الصلاة إلى ذلك الوقت؛ فهذا منكرٌ عظيمٌ، وكفرٌ أكبر عند جمعٍ من أهل العلم؛ لأنه قد عزم على تركها بالكلية في الوقت، ولهذا ذهب جمعٌ من أهل العلم إلى كفر مَن فعل ذلك، وهو القول الأرجح، وهو القول الأصح؛ لقوله ﷺ: بين الرجل وبين الكفر والشِّرك: ترك الصلاة، وقوله ﷺ: العهد الذي بيننا وبينهم الصلاة، فمَن تركها فقد كفر، وفي أحاديث أخرى، وهي عمود الإسلام، مَن أضاعها أضاع الدين، ولو صلَّى أربعًا وضيَّع واحدةً كفر، لا بد من الخمس كلها: الفجر والظهر والعصر والمغرب، لا بدّ، لا بد أن يُحافظ عليها جميعها، وأن يُؤدِّيها في الوقت، إلا إذا نام عنها أو نسي فالله جلَّ وعلا لا يُكلِّف نفسًا إلا وسعها، إذا نام ولم يتيسر استيقاظه ولم يسمع الساعة إذا قام يُصلي، وكذلك إذا نسي وشُغل عنها ثم ذكر صلَّى.\nأما كونه يتعمَّد ويُوقّت الساعة على وقت العمل بعد خروج الوقت؛ هذا منكرٌ عظيمٌ، وهذا عزمٌ على الترك، وهذا كفرٌ عند جمعٍ من أهل العلم، وهو مرويٌّ عن أصحاب النبي ﷺ، قال عبدالله بن شقيق العقيلي، رضي الله عنه، التابعي الجليل: \"لم يكن أصحابُ النبي ﷺ يرون شيئًا من الأعمال تركه كفر إلا الصلاة\"، فإنهم يرون تركها كفرًا. نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/21231/حكم-من-يتعمد-تاخير-صلاة-الفجر-عن-وقتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1163ما حكم من يتعمد تأخير صلاة الفجر حتى خروج وقتها؟ ابن باز فتاوى.mp3","categories":["صلاة الجماعة","وقت الصلاة"]},{"id":1278,"question":"أما هذا السؤال يا سماحة الشيخ فهو للأطباء، حيث يرون أنَّهم قد يحتاجون في العملية الجراحية إلى ساعات أطول، يفوت فيها أكثر من وقتٍ، وقطع العملية لأداء الصلاة فيه خطرٌ على المريض، فكيف يكون وقتهم بالنسبة للصلاة؟","title":"ما حكم تأخير الطبيب الصلاة أثناء العمليات؟","answer":"الجواب:\nهذا عذرٌ شرعيٌّ إذا دعت الحاجةُ، مثلما أنَّ المقاتلين قد يضطرون إلى تأخير الصلاة، النبي ﷺ يوم الأحزاب اضطر حتى صلَّى العصر بعد المغرب بسبب الحرب، والصحابة في تُستر في حرب العراق -حرب الفرس- لما طلع الفجرُ لم يتمكَّنوا من صلاة الفجر؛ لأنَّهم على الأبواب -أبواب المدينة- وبعضهم على الأسوار، وبعضهم قد نزل في البلد، فأجَّلوها إلى الضُّحى.\nفإذا كنتم في عمليةٍ إذا تركتُموها كان خطرًا على المريض؛ كمِّلوها ولو فات الوقتُ، وصلُّوا بعد ذلك ولا حرج، والحمد لله، هذا هو الصواب.","link":"https://binbaz.org.sa/fatwas/21327/ما-حكم-تاخير-الطبيب-الصلاة-اثناء-العمليات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1070ما حكم تأخير الصلاة للطبيب أثناء أجراء العملية؟ ابن باز فتاوى.mp3","categories":["وقت الصلاة"]},{"id":1388,"question":"هل تشترط الموالاة في الغسل أم يجوز تفريقه؟","title":"هل تُشترط الموالاة في الغُسْل؟","answer":"الجواب:\nالسنة الموالاة كما كان النبي ﷺ يوالي، لكن لو أخل بشيء وغسله بعد ذلك لا بأس، لو أخل بشيء من جسمه من رأسه أو من صدره أو كذا وغسله فالحمد لله.\nس: لو فرق تفريقًا طويلاً يعني غسل بعض أجزائه؟\nج: السنة الموالاة، المشروع الموالاة، لا يتعمد الترك، لكن لو وجد شيء أخل به ثم تَنَبَّه غسله، مثلًا نسي المضمضة، نسي الاستنشاق، ثم تنبه؛ يتمضمض ويستنشق بنية الغسل، والحمد لله.","link":"https://binbaz.org.sa/fatwas/21481/هل-تشترط-الموالاة-في-الغسل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسألة في الموالاة في الغسل.mp3","categories":["الغسل","التيمم","وقت الصلاة"]},{"id":1430,"question":"التخلف عن صلاة الفجر هل هو من مُحْدَثات الأمور؟","title":"ما حكم التخلف عن صلاة الفجر؟","answer":"الجواب:\nالتخلف عن صلاة الفجر: إن كان صلَّى في الوقت فهذا معصية، وإن كان تخلَّف حتى خرج الوقتُ عمدًا فهذا كفر، هذا ليس بدعة، هذا من الكفريات، التَّخلُّف عن الجماعة معصية، والتخلف عن الوقت كفر -نسأل الله العافية.\nالبدعة معناها: إحداث شريعةٍ في الدين، هذه هي البدعة، كونه يُحْدِث شيئًا ويقول: \"هذا مشروع\"، والله ما شرعه، هذا يُسمَّى بدعة، أما إذا فعل شيئًا منكرًا فهذا يُسمَّى معصيةً، ما يُسمَّى بدعة.","link":"https://binbaz.org.sa/fatwas/21525/ما-حكم-التخلف-عن-صلاة-الفجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم التخلف عن صلاة الفجر.mp3","categories":["وقت الصلاة"]},{"id":1539,"question":"رجل عند بوله يخرج قبل بوله بقليلٍ مَنِيّ؛ لشدة قوة مَنِيِّه وكثرته، كما قال الأطباء، فهل يغتسل لكل...؟","title":"حكم خروج المَنِيّ بغير شهوة","answer":"الجواب:\nلا، هذا إذا كان عنده شهوة، وأما العادي هذا الذي مع البول أو بعد البول ما يضر، هذا مرض.\nس: لونه لون المَنِيّ؟\nج: لا بدّ عن شهوة: إذا فَضَخْتَ مَنِيَّكَ فاغتسل، لا بدّ أن يكون عن شهوةٍ: إما مجامعة، وإلا ملامسة، وإلا تقبيل، وإلا تفكير.\nس: يترك الاغتسال الآن؟\nج: لا، ما عليه اغتسال، ما عليه إلا الاستنجاء.","link":"https://binbaz.org.sa/fatwas/21639/حكم-خروج-المني-بغير-شهوة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم خروج المني عند الوضوء.mp3","categories":["الغسل","التيمم","وقت الصلاة"]},{"id":1683,"question":"لو استيقظ الإنسانُ وما بقي على خروج وقت الفجر إلا وقتٌ يسيرٌ لأداء ركعتين؟","title":"هل يُبدأ بسُنة الفجر لو ضاق وقت الفرض؟","answer":"الجواب:\nولو، يُصلِّي الركعتين ثم يُصلِّي الفجر بعدها، فالنبي لما فاتته الصلاةُ صلَّى ركعتين ثم صلَّى الفجر.\nس: يُقَدِّم السُّنَّةَ؟\nج: نعم، يُقدِّم السنةَ؛ لأنَّ وقتها وقت الاستيقاظ، هو وقتها.","link":"https://binbaz.org.sa/fatwas/21789/هل-يبدا-بسنة-الفجر-لو-ضاق-وقت-الفرض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/استيقظ وما بقي على خروج وقت الفجر إلا وقت يسير فماذا يقدم.mp3","categories":["وقت الصلاة"]},{"id":2146,"question":"إذا كان العبدُ قد اغتسل في هذا اليوم اغتسالًا لأجل التَّطهر لا لأجل الجمعة، ثم صلَّى الجمعة، فهل الصّواب أن الطهارة تعمّ الأمرين؟","title":"حكم مَن اغتسل للتطهر فقط يوم الجمعة","answer":"الجواب:\nلا، بسالغُسل، إذا كان ما توضأ ما يصح، فلا بد أن يتوضأ الوضوء الشرعي، أما الجنابة –عند جمعٍ من أهل العلم- إذا نواهما جميعًا انتقل إلى الصنف الأكبر، إذا كان جنابةً.\nس: يعني: يُعيد الصلاةَ التي صلَّاها بهذا الغُسل؟\nج: نعم، يُعيدها ظهرًا.","link":"https://binbaz.org.sa/fatwas/22265/حكم-من-اغتسل-للتطهر-فقط-يوم-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل الاغتسال لرفع الحدث يعم اغتسال الجمعة.mp3","categories":["الغسل","التيمم","وقت الصلاة"]},{"id":2180,"question":"التَّسَتُّر حال الاغتسال عريانًا يكون أفضل أو ..؟","title":"هل يُشرع التَّسَتُّر حال الاغتسال؟","answer":"الجواب:\nالاغتسال عُريانًا لا بأس به، فالنبي ﷺ كان يغتسل عريانًا، واغتسل موسى عريانًا، واغتسل أيوب عريانًا.\nس: ومَن قال أن الاغتسال عريانًا جائز، ولكن التَّستر أفضل؟\nج: لا، لا بأس بالاغتسال عريانًا، أما التَّسَتُّر فقد يشقّ عليه؛ لأنَّ التَّسَتُّر  قد يطبع ثيابه أو يملؤها بالماء.\nس: لكن لا بأس؟\nج: الأمر واسع إذا كان في حجرةٍ ولا يراه أحدٌ.","link":"https://binbaz.org.sa/fatwas/22301/هل-يشرع-التستر-حال-الاغتسال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الاغتسال عريانا.mp3","categories":["الغسل","التيمم","وقت الصلاة"]},{"id":2339,"question":"سائلة تقول: جاء وقتُ صلاة المغرب وهي في البلد، ولا يوجد مسجدٌ؟","title":"حكم مَنْ لم تجد مكانًا تصلي فيه وقت الصلاة","answer":"الجواب:\nتُصلِّي في أحد المساجد، أو تصبر حتى تصل بيتَها.\nس: ولو غربت الشمسُ؟\nج: الوقت الذي تغيب فيه الشمسُ وقتٌ طويلٌ؛ ساعة ونصف تقريبًا.\nس: يكفيها؟\nج: يكفيها إلى أن تصل بيتها وتُصلي: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ[التغابن:16].\nس: لا تُصلي خارج بيتها؟\nج: إذا وجدتْ مكانًا خارج بيتها فطيبٌ: كمسجدٍ أو محلٍّ تُصلِّي فيه.","link":"https://binbaz.org.sa/fatwas/22463/حكم-من-لم-تجد-مكانا-تصلي-فيه-وقت-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حضرت صلاة المغرب وهي في البلد، ولا يوجد مسجدٌ.mp3","categories":["وقت الصلاة"]},{"id":2562,"question":"الرجل الذي يتعمد تأخير الصلاة؟","title":"ما حكم من يتعمد تأخير الصلاة؟","answer":"الجواب: يُحَذَّر ويُعَلَّم أن هذا مُنْكَر وخطر، مِن الكفر؛ لأن بعض أهل العلم يراه كافرًا إذا تعمد حتى خرج وقتها يعتبر كافرًا.","link":"https://binbaz.org.sa/fatwas/22694/ما-حكم-من-يتعمد-تاخير-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/تعمد تأخير الصلاة.mp3","categories":["وقت الصلاة"]},{"id":2676,"question":"هل المُحْتَلِم لا تَقْرَبُه الملائكة؟","title":"ما صحة أن المُحْتَلِم لا تَقْرَبُه الملائكة؟","answer":"الجواب: النبي ﷺ لما جاءه أبو هريرة وحذيفة وانْخَنَسا منه قال ﷺ: إن المسلم لا يَنْجُس فالجنابة معنى من المعاني ما هي بنجاسة، معنى من المعاني تُوجِب الغُسل، وهكذا الحيض يوجب الغُسل، والمرأة طاهرة عرقها طاهر وريقها طاهر وما مسته طاهر وشعرها طاهر، وهكذا الجُنُب عرقه طاهر وبدنه طاهر، لكن عليه أن يغتسل كما أمره الله.","link":"https://binbaz.org.sa/fatwas/22814/ما-صحة-ان-المحتلم-لا-تقربه-الملاىكة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل المحتلم لا تقربه الملائكة.mp3","categories":["الغسل","التيمم","وقت الصلاة"]},{"id":2864,"question":"في حديث عائشة في غسل الجنابة في آخر الحديث: ثم يغسل رجليه بعد أن يتوضأ يؤخر غَسل الرجلين؟","title":"حكم تأخير غَسل الرِّجلين في غُسل الجنابة","answer":"الجواب: هذا أفضل، وضوء كامل أولًا، ثم يغتسل، ثم يغسل رجليه من باب الكمال بعدما ينالها من أوساخ الجسد ونحوه، وإن توضأ وخلى الرجلين حتى يُكمّل الغسل ثم غسلها؛ كلها جاء، في حديث ميمونة وفي حديث عائشة، كله طيب. لكن الأكمل: يتوضأ وضوء كاملًا ثم يغسلهما غسلة أخرى، هذا الأفضل.\nس: بعض العلماء يقول أنه شاذ؛ لأنه لا معنى لغَسل الرجلين؟\nالشيخ: لا، ما هو شاذ، هو ثابت في الصحيحين.","link":"https://binbaz.org.sa/fatwas/23017/حكم-تاخير-غسل-الرجلين-في-غسل-الجنابة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/تأخير غسل الرجلين في غسل الجنابة.mp3","categories":["الغسل","التيمم","وقت الصلاة"]},{"id":2954,"question":"أرجو من سماحتكم أن تخبرونا عن كيفية الغسل من الجنابة؛ لأن بعض النساء تقوم بغسل مؤخرة الرأس أي الشعر وتقول إنه يجوز ويكفي لغسل الشعر كله، أو تقوم بغسل بعض الشعر بأن يتخلل الماء مؤخرة الشعر أي بعضه، فهل هذا يجوز؟ أما أنها تغسل الشعر كله سواء كان الشعر مربوطًا أم مفكوكًا، أرجو أن تخبرونا عن كيفية الغسل؟","title":"ما كيفية الغُسل من الجنابة للنساء؟","answer":"الجواب: السُّنَّة أن يستنجي الإنسان، يستنجي أولًا بعد الجماع، ثم يتوضأ وضوء الصلاة، ثم يفرغ على رأسه الماء ثلاث مرات، ثم يغسل بقية جسده، يبدأ بالشق الأيمن قبل الأيسر حتى يكمل الغسل.  والمرأة يكفيها إذا أمرّت الماء على رأسها ثلاث مرات يكفي، قالت أم سلمة: يا رسول الله إني امرأة أشد شعر رأسي أفأنقضه لغسل الجنابة؟ وفي رواية الحيضة؟ قال: يكفيك أن تحثي على رأسك ثلاث حثيات ثم تفيضي عليك الماء فإذا أفاضت عليه ثلاث حثيات مر على جميعه فلا يلزم النقض، وهكذا الرجل لو كان له رأس يُفيض عليه الماء ولا يحتاج للنقض.","link":"https://binbaz.org.sa/fatwas/23110/ما-كيفية-الغسل-من-الجنابة-للنساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/كيفية الغسل من الجنابة للنساء.mp3","categories":["الغسل","التيمم","وقت الصلاة"]},{"id":3027,"question":"أبْرِدُوا بالصلاة.. فيه من يقول: الآن في مكيفات ولا داعي للإبراد في الصلاة؟","title":"حكم الإبراد بصلاة الظهر في وقتنا الحالي","answer":"الجواب: لا، لا بدّ مِن الأخذ بالسُّنَّة لأن الطرق فيها حر، ولا كل أحد عنده مبرّدات، السُّنَّة تُستعمل ولا ينبغي إضاعتها وإهمالها بهذه الدعوى إذا اشتد الحر فأبردوا بالصلاة هكذا قال النبي ﷺ، وهكذا تأخيرها في العشاء إذا لم يجتمع الناس إذا أحبوا التأخير، إذا تأخروا تأخر، وإذا تقدموا تقدم؛ مراعاة لما قاله النبي ﷺ، أمر لازم.","link":"https://binbaz.org.sa/fatwas/23187/حكم-الابراد-بصلاة-الظهر-في-وقتنا-الحالي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الأولى الأخذ بالسنة.mp3","categories":["وقت الصلاة"]},{"id":3172,"question":"الشخص إذا جمع بين الوضوء والغسل كما ذكرتم آنفا فإنه لا محالة أنه يمس بعد أن يتوضأ، ربما يمس فرجيه؟","title":"ما كيفية الجمع بين الوضوء والغسل؟","answer":"الجواب: لا يمسهما، يستنجي قبل، ويكفي، يستنجي يغسل فرجيه قبل، ثم الأفضل يتوضأ وضوء الصلاة، فإن كان ما توضأ ونوى الغسل والوضوء جميعًا؛ أجزأ عند جمع من أهل العلم، يدخل الأصغر في الأكبر.","link":"https://binbaz.org.sa/fatwas/23335/ما-كيفية-الجمع-بين-الوضوء-والغسل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الجمع بين الوضوء والغسل.mp3","categories":["الغسل","التيمم","وقت الصلاة"]},{"id":3372,"question":"ما ورد الوعيد في تأخير الغُسْل من الجنابة؟","title":"ما حكم تأخير الغُسْل من الجنابة؟","answer":"الجواب: ما أتذكر شيئًا، التأخير إذا كان ما فيه مانع، لو جامع في أول الليل جاز التأخير إلى آخر الليل، النبي ﷺ كان يؤخر عليه الصلاة والسلام.","link":"https://binbaz.org.sa/fatwas/23539/ما-حكم-تاخير-الغسل-من-الجنابة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/تأخير الغسل من الجنابة.mp3","categories":["الغسل","التيمم","وقت الصلاة"]},{"id":3396,"question":"هل هذا الحديث (حتى أقبل على الجدار، فمسح...) يدل على جواز التيمم من أجزاء الأرض المتولدة كالطين، والرخام، وغيره؟","title":"هل يجوز التيمم بالطين والرخام ونحوهما؟","answer":"الجواب: جنس التراب، سواء في الجدار، أو في الأرض، وإذا دعت الحاجة إلى غيره كالذي في الأرض سبخة، أو في أرض رمل؛ تيمم منها، فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]؛ لعموم الحديث، وعموم الآية: فَلَمْ تَجِدُوا [النساء:43].","link":"https://binbaz.org.sa/fatwas/23567/هل-يجوز-التيمم-بالطين-والرخام-ونحوهما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حديث .. حتى أقبل على الجدار، فمسح بوجهه.. هل يدل على جواز التيمم من أجزاء.mp3","categories":["الغسل","التيمم","وقت الصلاة"]},{"id":3498,"question":"إمام يصلي العشاء من الحادية عشرة مساء وينتهي في الثانية صباحًا؟","title":"حكم تأخير العشاء وإطالتها بعد منتصف الليل","answer":"الجواب: صلاة فريضة وإلا تهجد؟ الطالب: لا، الفريضة. الشيخ: مريض يعني؟\nس: لا، ما هو مريض، هو اعتاد أن يصلي بالمأمومين.\nالشيخ: لا، ما يجوز له، الواجب أن يصلي مع الناس، ولا يجوز له أن يؤخر الوقت.\nس: هو إمام ويصلي بالناس من قبل منتصف الليل إلى بعد منتصف الليل.....\nالشيخ: الناس ما يصلون الحادية عشرة.\nس: يمكن أنه في مزرعة...؟\nالشيخ: المقصود إذا كان صادف وقت العشاء فلا بأس، لكن ينبغي له ألا يتأخر عن الثلث، ثلث الليل، كان النبي ﷺ إذا أخرها أخرها إلى ثلث الليل، ونهايتها النصف، وقت العشاء إلى نصف الليل.","link":"https://binbaz.org.sa/fatwas/23676/حكم-تاخير-العشاء-واطالتها-بعد-منتصف-الليل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/تأخير صلاة العشاء.mp3","categories":["وقت الصلاة"]},{"id":3505,"question":"من استيقظ في آخر الوقت، ما يبدأ بالفريضة؟","title":"هل يُبدأ بالفريضة أم الراتبة في آخر الوقت؟","answer":"الجواب: يصلي الراتبة ثم الفريضة: من نام عن الصلاة أو نسيها فليصلها إذا ذكرها هذا وقتها.\nس: ذاك وقتها، يصليها قضاء؟\nالشيخ: الأمر سهل، سواء سُمّي قضاء وإلا أداء، الأمر سهل ما يضر.","link":"https://binbaz.org.sa/fatwas/23685/هل-يبدا-بالفريضة-ام-الراتبة-في-اخر-الوقت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/بماذا يبدأ من استيقظ آخر الوقت بالفريضة أم الراتبة.mp3","categories":["وقت الصلاة"]},{"id":3527,"question":"من أراد أن يؤخر الصلاة -غير الظهر- هل الأولى أن يؤذن مع الناس في الوقت ثم يصلي ما بدا له؟","title":"هل يُؤذَّن في الوقت بمسجدٍ يؤخّر الصلاة؟","answer":"الجواب: نعم يؤذن مع الناس، والصلاة على حسب، مثل العشاء، العشاء إن رآهم اجتمعوا عَجَّل، وإن رآهم تأخروا أخَّر.\nس: لكن الظهر وحدها تُؤخَّر أذاناً وصلاةً؟\nالشيخ: إذا اشتدّ الحَرّ يؤخّرون الأذان والصلاة، هذه السنة.\nس: يعني هذا خاص بالظهر، أما غير الظهر فيؤذن بالوقت؟\nالشيخ: نعم.","link":"https://binbaz.org.sa/fatwas/23708/هل-يوذن-في-الوقت-بمسجد-يوخر-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/كيف يعمل من أراد أن يؤخر الصلاة.mp3","categories":["وقت الصلاة"]},{"id":3773,"question":"ما يدل على الوجوب قوله: أحوط (أي: الغُسل بعد الجِماع وإن لم يُنْزِل)؟","title":"هل يجب الغُسل بعد الجِماع وإن لم يُنْزِل؟","answer":"الجواب: محتمل، لكن السنة ثابتة، الواجب هو الغُسل، وإن لم ينزل، وإذا أنزل وجب عليه الغُسل. لكن إذا لم ينزل فالواجب الغُسل؛ لأن الرسول ﷺ أوضح لهم آخرًا، وأبو هريرة ممن أسلم آخرًا، وحديث عائشة صريح في أنه إذا مس الختان الختان فقد وجب الغسل، وقال: كنت أفعله مع هذه فأغتسل لما سئل عليه الصلاة والسلام، كلها رواها مسلم، وغيره، والرواية في الصحيحين.\nس: ابن حجر ذكر في الشرح قال: قول النبي الماء من الماء قال المراد بالماء الأول ماء الغسل، والثاني المني هذا صحيح؟\nالشيخ: نعم هذا المراد.","link":"https://binbaz.org.sa/fatwas/23969/هل-يجب-الغسل-بعد-الجماع-وان-لم-ينزل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/وجوب الغسل بعد الجماع وإن لم ينزل.mp3","categories":["الغسل","التيمم","وقت الصلاة"]},{"id":4365,"question":"في المدارس بارك الله فيك بعض المدرسين يتأخرون عن تكبيرة الإحرام ركعة أو ركعتين حتى يضبطون الطلاب من العبث، فما الأفضل؟","title":"حكم التأخر عن الصلاة بالمدارس لضبط الطلبة","answer":"الجواب: الواجب يتقدمون في الصلاة ينظمونهم قبل الصلاة حتى لا يفوتهم شيء من الصلاة، ينظمونهم قبل الصلاة.","link":"https://binbaz.org.sa/fatwas/24642/حكم-التاخر-عن-الصلاة-بالمدارس-لضبط-الطلبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/التأخر عن تكبيرة الإحرام في المدارس لضبط الطلبة من العبث.mp3","categories":["وقت الصلاة"]},{"id":4410,"question":"غسل الرجل مع امرأته يكون سُنةً؟","title":"حكم غسل الرجل مع امرأته","answer":"الجواب: جائز، جائز، حكمه الجواز.\nس: ما يكون سنةً؟\nج: محل نظرٍ، النبي فعله يدل على جوازه، عليه الصلاة والسلام.","link":"https://binbaz.org.sa/fatwas/24687/حكم-غسل-الرجل-مع-امراته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم غسل الرجل مع امرأته.mp3","categories":["الغسل","التيمم","وقت الصلاة"]},{"id":4422,"question":"المني إذا خرج من غير شهوةٍ؟","title":"ما حكم المني إذا خرج من غير شهوةٍ؟","answer":"الجواب: إذا خرج لأجل المرض يكون الحكم حكم الأبوال، ..... الحكم حكم سائر الفضلات التي تخرج من الإنسان؛ توجب الوضوء.","link":"https://binbaz.org.sa/fatwas/24700/ما-حكم-المني-اذا-خرج-من-غير-شهوة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم المني إذا خرج من غير شهوةٍ.mp3","categories":["الغسل","التيمم","وقت الصلاة"]},{"id":4474,"question":"هل يُباشر الوضوء قبل مُباشرة الغسل، وقد يمسّ فرجه للتنظيف؟","title":"حكم مس الفرج بعد الوضوء وقبل الغسل","answer":"الجواب: ما يمس، إذا استنجى لا يمس فرجه، انتهى، إذا استنجى وغسله بنية الطهارة انتهى، لكن لو غسل ما حوله، ومسح يده على ما حوله... ما يضره.\nس: يعني: يُباشر الوضوء، يعني: قبل مُباشرة الغسل يبدأ بالوضوء؟\nج: ... نعم: ثم يتوضأ وضوء الصَّلاة.","link":"https://binbaz.org.sa/fatwas/24753/حكم-مس-الفرج-بعد-الوضوء-وقبل-الغسل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسألة في الوضوء قبل مُباشرة الغسل، ومس الفرج.mp3","categories":["الغسل","التيمم","وقت الصلاة"]},{"id":4494,"question":"آخر وقت العشاء؟","title":"متى آخر وقت العشاء؟","answer":"الجواب: نصف الليل كما في حديث عبدالله بن عمرو، هذا وقتها وإذا صلَّاها بعد ثلث الليل إذا توافق الناسُ على هذا جماعة في مسجدٍ ناسبهم هذا فلا بأس، ثم أخَّر فهو أفضل... لكن إذا لم يتَّفقوا من المساجد المعروفة فالأفضل فيها عدم التأخير؛ لأنَّ الناس لهم حاجات، يُؤخّر قليلًا في العشاء، ثم يُصلي، نعم.","link":"https://binbaz.org.sa/fatwas/24774/متى-اخر-وقت-العشاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/آخر وقت العشاء.mp3","categories":["وقت الصلاة"]},{"id":4806,"question":"إذا اغتسل ناويًا التَّبرد، ونوى الوضوء هل يُجزئ؟","title":"هل يُجزئ غسل التَّبرد عن الوضوء؟","answer":"ما يُجزئ، لا بدّ من الوضوء الشرعي.","link":"https://binbaz.org.sa/fatwas/25201/هل-يجزى-غسل-التبرد-عن-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/من اغتسل ناويًا التَّبرد ونوى الوضوء فهل يُجزئ.mp3","categories":["الغسل","التيمم","وقت الصلاة"]},{"id":4850,"question":"بعد اصفرار الشمس هل تكون صلاةُ العصر أداءً أم قضاءً؟","title":"ما حكم صلاة العصر بعد اصفرار الشمس؟","answer":"أداء.\nس: يقضيها إذا خرج الوقتُ؟\nج: يقضيها، وهذا أحوط؛ خروجًا من الخلاف، وإلا فهي باطلة، لكن إن قضاها خروجًا من الخلاف فحسنٌ، وإلا فلا يلزمه قضاؤها؛ لأنه تعمَّد، إلا بالتوبة، فيتوب إلى الله جلَّ وعلا ويستدرك.","link":"https://binbaz.org.sa/fatwas/25302/ما-حكم-صلاة-العصر-بعد-اصفرار-الشمس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/إذا صلى العصر بعد اصفرار الشمس هل تكون أداءً أم قضاءً.mp3","categories":["وقت الصلاة"]},{"id":4851,"question":"الجمع بين حديث: أنَّ النبي ﷺ كان يُصلي الفجر بغَلسٍ، وقوله ﷺ فيما أخرجه الخمسة: أسفروا بالصُّبْح؛ فإنَّه أعظم للأجر؟","title":"ما الجمع بين حديثي صلاة الفجر بغَلسٍ والإسفار؟","answer":"يعني: يتأكَّد، هذا هو، فلا يتعجَّل بالصبح ولا يُخاطر بها.","link":"https://binbaz.org.sa/fatwas/25303/ما-الجمع-بين-حديثي-صلاة-الفجر-بغلس-والاسفار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الجمع بين حديث كان يُصلي الفجر بغَلسٍ، وحديث أسفروا بالصُّبْح..mp3","categories":["وقت الصلاة"]},{"id":4943,"question":"من قال أن العلة من الإبراد شدة الحر وفي الوقت هذا المكيفات تلغي هذه العلة؟","title":"هل يُعمل بالإبراد بالصلاة مع وجود المكيّفات؟","answer":"الجواب: ولو، لا تُعطّل السُّنة؛ لأن الطرق ما فيها مكيفات، الطرق فيها الحر، ما فيها مكيفات، ولا كل بلاد فيها مكيفات.\nس: هل يتأخر.. الحر قد يمتد؟\nالشيخ: حتى ينكسر، إذا مضى نصف ساعة أو نحوها ينكسر الحر.","link":"https://binbaz.org.sa/fatwas/27368/هل-يعمل-بالابراد-بالصلاة-مع-وجود-المكيفات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يُعمل بالإبراد بالصلاة مع وجود المكيّفات؟.mp3","categories":["وقت الصلاة"]},{"id":5140,"question":"أما هذا السؤال يا سماحة الشيخ فهو للأطباء، حيث يرون أنهم قد يحتاجون في العملية الجراحية إلى ساعات أطول، يفوت فيها أكثر من وقتٍ، وقطع العملية لأداء الصلاة فيه خطرٌ على المريض، فكيف يكون وقتُهم بالنسبة للصلاة، جزاكم الله خيرَا؟","title":"حكم تأخير الصلاة لإجراء العمليات الجراحية","answer":"الجواب: هذا عذرٌ شرعيٌّ إذا دعت الحاجة، مثلما أن المُقاتلين قد يضطرون إلى تأخير الصلاة، فالنبي ﷺ يوم الأحزاب اضطُرَّ حتى صلَّى العصر بعد المغرب بسبب الحرب، والصحابة في تستر في العراق في حرب الفرس لما طلع الفجرُ لم يتمكنوا من صلاة الفجر؛ لأنَّهم كانوا على أبواب المدينة، وبعضهم على الأسوار، وبعضهم قد نزل في البلد، فأجَّلوها إلى الضُّحى. فإذا كنتم في عمليةٍ، وإذا تركتموها كان ذلك خطرًا على المريض؛ فأكملوها ولو فات الوقتُ، وصلُّوا بعد ذلك، ولا حرج والحمد لله، هذا هو الصَّواب.","link":"https://binbaz.org.sa/fatwas/30055/حكم-تاخير-الصلاة-لاجراء-العمليات-الجراحية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 76.mp3","categories":["وقت الصلاة"]},{"id":5308,"question":"بعض النساء يُشكل عليها الغسل من الجنابة والحيض، نرجو من سماحتكم تفصيل كيفية الغسل، وهل تطهر المرأة من الجنابة إذا حثت على رأسها ثلاث حثيات، وهل يلزمها غسل جميع الرأس بالماء؟","title":"ما صفة الغسل من الجنابة والحيض والنفاس؟","answer":"الجواب: الجنب والحائض والنفساء كلهم غسلهم متقارب، تعم بدنها بالماء وتفيض على رأسها الماء، لكن السُّنة أن يبدأ بالوضوء، يستنجي أولًا، الحائض تستنجي والنفساء والجنب، تستنجي أولًا، ثم يتوضأ وضوء الصلاة ثم يفيض الماء على رأسه ثلاث غرفات، ثم على جنبه الأيمن ثم جنبه الأيسر ثم يُكمل، هذا السُّنة ولا حاجة إلى نقض الرأس، لكن الحائض يستحب لها النقض؛ لأن مدتها تطول، والنفساء، فإذا نقضت كان أفضل في الغسل فتغسله بالماء، فإن أمرّت عليه الماء من غير نقض فكفى. فالحاصل أن المقصود هو إفاضة الماء على البدن، فإذا أفاض الماء على بدنه بنية غسل الحيض أو غسل الجنابة أو غسل النفاس؛ كفى، لكن الأفضل أنه بعد الاستنجاء يتوضأ وضوء الصلاة، ثم يفيض الماء على رأسه ثلاث غرفات يعمها على الرأس، ثم جنبه الأيمن ثم جنبه الأيسر، ثم بقية بدنه حتى يكمل، الجنب والحائض والنفساء، لكن النفساء والحائض يستحب لهما النقض، في بعض الأحاديث النقض (انقضي رأسك) فإذا نقضت كان أفضل مع الماء والسدر، والجُنب لا يحتاج إلى سدر، الماء يكفي.[1]","link":"https://binbaz.org.sa/fatwas/30962/ما-صفة-الغسل-من-الجنابة-والحيض-والنفاس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/aljwab_alkafi 028.mp3","categories":["الغسل","التيمم","وقت الصلاة"]},{"id":5395,"question":"ذكر المؤلف أن حكمة تأخير الإبراد بالظهر لكسر الحرِّ، لكن في هذه الأيام تكثر المُكيِّفات؟","title":"هل تنتفي علة الإبراد بالصلاة مع وجود المُكيِّفات؟","answer":"الجواب: هذا الأصل: إذا اشتدَّ الحرُّ فأبردوا بالصلاة، فإنَّ شدَّة الحرِّ من فَيح جهنم. س: كثرت الآن المكيِّفات؟ ج: ولو؛ لأنَّ الطرق يعتريها الحرُّ، وخروجه في الطُّرق والشمس قوية فيتأثَّر؛ حرٌّ بعد بردٍ، وبردٌ بعد حرٍّ؛ يتأثر. س: لكن يا شيخ من ناحية الأذان: إذا مثلًا أذَّن يُشوش على المساجد؟ ج: على كل حال، إن اتفقوا على تأخير الأذان فهو أفضل، السنة تأخير الأذان، لكن لو ما أخَّروه يُؤخِّرون الإقامة، لكن السنة تأخير الأذان أيضًا؛ لأن الناس إذا سمعوا الأذان تحرَّكوا، فالسنة تأخيره، والنبي ﷺ في السفر لما أراد المؤذنُ أن يُؤذِّن قال: أبرد، أبرد، أبرد، فلم يزل يقول له: أبرد حتى رأينا فَيْءَ التُّلول، ثم أمره بالأذان. س: وإذا حُددت الأوقات –وقت الأذان- لهم أن يُبردوا؟ ج: لا، إذا حُددت يمتثلون؛ لأنَّ هذا يُسبب الاختلافَ والتنازع، فاتِّفاقهم أوْلى من التنازع. س: حديث بأن جهنم تُسَجَّر في هذا الوقت؟ ج: صحيح، وهذه عِلَّة أخرى، تسجير جهنم، وما فيه من التيسير على المسلمين وأداء الصلاة بقلبٍ خاشعٍ، فشدَّة الحرِّ من تسجير جهنم، وشدَّة الحرِّ يُعالَج بالإبراد، الإخبار عن أسباب تسجير جهنم إخبار عن أسباب شدَّة الحر.[1]","link":"https://binbaz.org.sa/fatwas/31140/هل-تنتفي-علة-الابراد-بالصلاة-مع-وجود-المكيفات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/alwabel _alsaib 010.mp3","categories":["وقت الصلاة"]},{"id":5540,"question":"بعض العلماء يقولون: آخر وقت العشاء نصف الليل الأوسط، ويستدلون بحديث المواقيت، وبعضهم يقول: ما بعد نصف الليل يكون وقت ضرورةٍ. يعني: لا قضاءَ، فإذا كان الراجحُ هذا ما هو الدليل عليه؟ إذا كان الراجح الرأي الأخير.","title":"متى آخر وقت صلاة العشاء؟","answer":"الجواب: أما النصف فلحديث عبدالله بن عمرو المعروف، رواه مسلم، وأما باقي الليل فلأنه وقت ضرورةٍ مثلما بعد الصُّفرة والشمس بعد العصر؛ لحديث: ليس في النوم تفريطٌ، إنما التَّفريط أن يُؤخر الصلاةَ إلى أن يدخل وقتُ الصلاة التي بعدها، هذا يدل على أنه يمتد الوقت، يمتد إلى ما بعدها، ما عدا الفجر؛ فإنها ليس بعدها شيء، يمتد وقتها إلى طلوع الشمس، أما غيرها فيمتد وقتها إلى وقت الأخرى.[1]","link":"https://binbaz.org.sa/fatwas/31475/متى-اخر-وقت-صلاة-العشاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/zad almaad 003.mp3","categories":["وقت الصلاة"]},{"id":5564,"question":"إذا اغتسل من الجنابة قبل أذان الفجر ونوى يوم الجمعة؟","title":"هل يجزئ الغسل قبل الفجر للجنابة والجمعة؟","answer":"الجواب: لا، إذا كان قبل الفجر لا، يغتسل يوم الجمعة، إذا اغتسل من الجنابة في الليل قبل الفجر ما يكفي، يُستحب له غسل الجمعة بعد الأذان عند ذهابه إلى الجمعة. س: ولو كان بعد الفجر؟ ج: بعد الفجر يكفي، وإذا اغتسل عند ذهابه إلى الجمعة طيب؛ لأن بينهما مسافة.[1]","link":"https://binbaz.org.sa/fatwas/31516/هل-يجزى-الغسل-قبل-الفجر-للجنابة-والجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/al rawth_almuraba 004.mp3","categories":["الغسل","التيمم","وقت الصلاة"]},{"id":5574,"question":"المُكره على الجماع؟","title":"هل يجب الغسل على مَن أُكره على الجماع؟","answer":"الجواب: محل نظرٍ والله أعلم، إن خرج المني يغتسل، لكن إذا أُكره ولا خرج مني هذا محل نظرٍ، ولعلَّ الغسل أقرب؛ لأنه شمله: إذا مسَّ الختانُ الختانَ، لعله أقرب.\nوكذلك النائم إذا علم أنه أدخل فرجه، قد يقال أنه يغتسل احتياطًا وإن كان ما قصد، أما الوجوب فمحل نظرٍ؛ لأنه ما عنده قصد ولا فعل شيئًا.[1]","link":"https://binbaz.org.sa/fatwas/31526/هل-يجب-الغسل-على-من-اكره-على-الجماع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/al rawth_almuraba 014.mp3","categories":["الغسل","التيمم","وقت الصلاة"]},{"id":5585,"question":"إذا خشي خروج الوقت بالغسل؟","title":"ما حكم مَن خشي خروج الوقت إذا اغتسل؟","answer":"الجواب: إذا كان مُستيقظًا وفرَّط يُصلي، يغتسل ويُصلي. أما إذا كان نائمًا لا، ولو خرج الوقت؛ لأن الرسول ﷺ لما نام عن الصلاة أخَّرها حتى توضؤوا وصلّوا، معذور، والنبي عليه الصلاة والسلام قال: مَن نام عن الصلاة فليُصلها إذا ذكرها. أما إنسان مُستيقظ ليس له التأخير، بل يُصلي على حسب حاله. س: إذا كان مُستيقظًا وأخَّر؟ ج: لا يجوز له التأخير، المستيقظ يُصلي في الوقت. س: إذا أخَّرها وخشي خروج الوقت إذا اغتسل؟ ج: الظاهر أنه يُصلي بالتيمم في هذه الحالة ولا يُؤخر، إذا كان طلبُ الوضوء أو طلبُ الغسل يُفوت الوقت، إلا إذا كان نائمًا، معذور ولو فات الوقت، مَن نام عن الصلاة أو نسيها، إذا كان نائمًا أو ناسيًا.[1]","link":"https://binbaz.org.sa/fatwas/31543/ما-حكم-من-خشي-خروج-الوقت-اذا-اغتسل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/al rawth_almuraba 025.mp3","categories":["وقت الصلاة"]},{"id":5604,"question":"تأخير العشاء إلى حدٍّ؟ ماذا آخر حدٍّ له؟","title":"هل يخرج وقت العشاء مطلقًا بعد نصف الليل؟","answer":"الجواب: نصف الليل، الوقت الاختياري نصف الليل على الصحيح. س: بعد نصف الليل العشاء وقت اضطرار؟ ج: وقت ضرورةٍ كما يأتي، ما بين النصف إلى الفجر وقت ضرورةٍ، كالعصر من اصفرار الشمس إلى غروبها وقت ضرورةٍ. س: مَن قال أنه بعد نصف الليل قد خرج وقت العشاء مطلقًا؟ ج: لا،ـ خرج وقت الاختيار، في الحديث الصحيح لما سُئل عن النوم قال: ليس في النوم تفريط، إنما التفريط في اليقظة أن يُؤخر الصلاة حتى يدخل وقتُ التي بعدها، فجعل ما بين الوقتين \"وقت\"، إلا الفجر فإنه ينتهي وقتها بطلوع الشمس.[1]","link":"https://binbaz.org.sa/fatwas/31571/هل-يخرج-وقت-العشاء-مطلقا-بعد-نصف-الليل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/al rawth_almuraba 044.mp3","categories":["وقت الصلاة"]},{"id":6881,"question":"رقدت عن صلاة الصبح، ولم أستيقظ إلا في الضحى، فهل يجوز لي صلاتها عندما أستيقظ، أم أصليها مع وقتها؟","title":"حكم من نام عن صلاة الصبح حتى خرج وقتها","answer":"الجواب: إذا نام الإنسان عن صلاة، ثم استيقظ؛ فإنه يصليها حال استيقاظه مع سنتها، لقول النبي ﷺ: من نام عن الصلاة، أو نسيها؛ فليصلها إذا ذكرها، لا كفارة لها إلا ذلك.  ولما نام النبي ﷺ في بعض غزواته، وبعض أسفاره عن صلاة الصبح، فلم يستيقظوا إلا بحر الشمس؛ قام -عليه الصلاة والسلام- وأمر بلالًا فأذن، وتوضؤوا للصلاة، وصلوا سنتها، ثم أقام، وصلاها كما كان يصليها في وقتها -عليه الصلاة والسلام-.","link":"https://binbaz.org.sa/fatwas/2774/حكم-من-نام-عن-صلاة-الصبح-حتى-خرج-وقتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1266.mp3","categories":["وقت الصلاة"]},{"id":6897,"question":"رقدت عن صلاة الصبح، ولم أستيقظ إلا في الضحى، فهل يجوز لي صلاتها عندما أستيقظ، أم أصليها مع وقتها؟","title":"حكم من نام عن صلاة الصبح حتى خرج وقتها","answer":"الجواب: إذا نام الإنسان عن صلاة، ثم استيقظ؛ فإنه يصليها حال استيقاظه مع سنتها، لقول النبي ﷺ: من نام عن الصلاة، أو نسيها؛ فليصلها إذا ذكرها، لا كفارة لها إلا ذلك.  ولما نام النبي ﷺ في بعض غزواته، وبعض أسفاره عن صلاة الصبح، فلم يستيقظوا إلا بحر الشمس؛ قام -عليه الصلاة والسلام- وأمر بلالًا فأذن، وتوضؤوا للصلاة، وصلوا سنتها، ثم أقام، وصلاها كما كان يصليها في وقتها -عليه الصلاة والسلام-.","link":"https://binbaz.org.sa/fatwas/2774/حكم-من-نام-عن-صلاة-الصبح-حتى-خرج-وقتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1266.mp3","categories":["وقت الصلاة"]},{"id":7742,"question":"من المحتار والمشغول الضمير علي حسن الزهراني من الرياض وزارة الداخلية يقول: أنا شاب عمري ثلاثة وعشرين سنة، ومتزوج ولله الحمد والشكر، ولكن لدي موضوع -وهي في الحقيقة مشكلة- وهي على النحو التالي: أصلي جميع الفروض ما عدا صلاة الفجر فهي تفوتني كل صبح إلا ما شاء الله تعالى، وأنا في حيرة من أمري، وقلق من هذه الحالة التي أنا فيها ومشغول يقول: أرجو أن أجد حلاً لمشكلتي هذه؟!","title":"توجيه لمن تفوته صلاة الفجر بسبب النوم","answer":"الجواب: هذه المشكلة ليست لك وحدك بل معك فيها ناس كثير وشباب كثير وغير الشباب أيضاً وهو التأخر عن صلاة الفجر، ولهذا أسباب من أهمها ومن أخطرها السهر وعدم النوم المبكر هذا هو السبب الوحيد، الغالب على الناس يسهرون لمشاهدة التلفاز أو لأسباب أخرى، فإذا سقط في آخر الليل نائماًَ عجز أن يقوم في آخر الليل حتى ولو كان عنده ساعة تنبه ما يسمعها حتى ولو جاءه منبهون يعجزون عنه بسبب ثقل النوم وغلبته عليه؛ فالعلاج الوحيد لهذا الأمر مع سؤال الله التوفيق والإعانة العلاج الوحيد هو عدم السهر، أن ينام المؤمن مبكراً، وألا يضر نفسه بمشاهدة التلفاز حتى يمضي عليه الليل الكثير أو يشتغل بأشياء أخرى من سماع أغاني أو سماع القيل والقال من أصحابه وزملائه أو موانع أخرى تمنعه من النوم المبكر، وإذا عالج الأمر بهذه الطريقة إن شاء الله يفلح.\nوأنت يا أيها السائل! الواجب عليك ألا تسهر وأن تنظر في الأسباب التي منعتك من القيام فإن كانت الأسباب أنك تتأخر في النوم تسهر فاتق الله وبادر بالنوم في أول الليل بعد صلاة العشاء بادر بالنوم حتى تستطيع القيام لصلاة الفجر وتصلي مع المسلمين في جماعة المسلمين، وهذا واجب عليك، والتساهل بهذا محرم ومن التشبه بالمنافقين لأن المنافقين لا يأتون الصلاة إلا دباراً ولا يشهدون العشاء والفجر هذه من أعمالهم الخبيثة، فالواجب على المسلم أن يحذر مشابهة المنافقين، وأن يجتهد في أداء فريضة الله في أوقاتها مع إخوانه المسلمين هذا إذا كان رجل، والمرأة كذلك عليها أن تتقي الله وأن تجتهد في أداء الصلاة في وقتها بعد طلوع الفجر قبل الشمس، ولا يجوز أبداً لأحد من الناس أن يؤخرها بعد طلوع الشمس كما يفعل بعض الناس يؤخرها فإذا قام لعمله بعد طلوع الشمس صلى هذا غلط عظيم ومنكر كبير لا يجوز لا للرجل ولا للمرأة ليس للرجل أن يؤخر ذلك حتى يقوم للدراسة أو للعمل ثم يصلي بعد طلوع الشمس؛ هذا لا يجوز هذا محرم، بل ذهب جمع من أهل العلم إلى أن من فعله كفر؛ لأن تأخير الصلاة عن وقتها كفر إذا تعمد ذلك لقول النبي ﷺ: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر. هكذا بعض الطالبات تؤخر الصلاة حتى تقوم للدراسة بعد طلوع الشمس، وهذا أيضاً منكر ولا يجوز، والواجب على الجميع تقوى الله -وعلى أهلهن التنبيه على آبائهن وأمهاتهن وعلى إخوانهن التنبيه على ذلك وعلى آباء الشباب كذلك وأمهات الشباب، كل هذه أمور عظيمة يشترك فيها أهل البيت في إثمها إذا لم يتعاونوا على زوالها والمسلمون شيء واحد وأهل البيت شيء واحد يجب أن يتعاونوا في نصيحة المتخلف والأخذ على يديه حتى يستقيم على طاعة الله وأداء فرائضه، هذا هو الواجب على الجميع فإن كان هناك أسباب أخرى غير السهر، فالواجب عليك أن تعالجها، وأن تنظر ما هي الأسباب إن كان النوم يطير عنك من أول الليل ما تنام فاسأل الأطباء لعل عندهم دواء يزيل عنك هذا القلق وهذا السهر ويحصل لك الراحة والطمأنينة حتى تنام، وإن كان هناك علل أخرى فعالجها وإن كنت ليس عندك من يوقظك فاجعل عندك الساعة المعروفة المنبهة وأكد ......... على الوقت المناسب الذي هو وقت الأذان أو قرب الأذان حتى تسمعها وتقوم.\nعلى كل حال الواجب العلاج، والعلاج لا يخفى على العاقل، العلاج واضح تارة بالساعة وتارة بالمنبهين وتارة بعدم السهر، الواجب العلاج على الرجل والمرأة على جميع الناس، على الشباب والشيب.. على البنات والعجائز على الجميع ليس هذا خاصاً بأحد دون أحد الواجب على الجميع أن يعالجوا ما يقع لهم من هذا التأخر وأن ينظروا في الأسباب حتى تزال هذه الأسباب التي تقتضي التأخر حتى لا يصلي إلا بعد الشمس هذا منكر عظيم يجب أن يعالج من ابتلي به الوضع حتى يصلي الصلاة في وقتها مع الجماعة إن كان رجلاً وحتى تصليها المرأة في بيتها في الوقت قبل طلوع الشمس ونسأل الله للجميع الهداية والتوفيق.\nالمقدم: أحسنتم وأثابكم الله.","link":"https://binbaz.org.sa/fatwas/4942/توجيه-لمن-تفوته-صلاة-الفجر-بسبب-النوم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_041/04103.mp3","categories":["نصائح وتوجيهات","وقت الصلاة"]},{"id":7930,"question":"هذه الرسالة التي بين يدينا تحمل عدة أسئلة، وأسئلة مفيدة من ناحية زمار قرية خمروك بمحافظة نينوى بالعراق، يقول: بسم الله الرحمن الرحيم، السلام عليكم ورحمة الله.إخواني! إنني ينشرح صدري كثيراً حينما أصغي إلى طرح الأسئلة الشرعية والإجابة عليها من قبل فضيلة العلماء لديكم، لكن في نفس الوقت أقترح إطالة فترة البرنامج وطرح عدد أكثر من الأسئلة والإجابة عليها.نقول لك يا أخ: نحن نطرح كثير من الأسئلة ونستغرق وقت البرنامج كله.يقول: إخواني! لدي أسئلة أولها: أرجو أن توضحوا لي وتفيدوني عن صلاة الحرب الخاصة بالعسكريين المتواجدين في ساحة المعركة، وهو بعث هذه الرسالة من ساحة المعركة، يقول: هل أن العسكري يصلي دائماً صلاة القصر، أو إذا استقر بعض الشيء عن ساحة المعركة يصلي صلاة الحضر مع بقية النوافل والسنن، وإذا كانت له الرغبة في ذلك فأيهما أفضل وفقكم الله؟","title":"كيفية الصلاة في الحرب","answer":"الجواب: صلاة الحرب مختلفة، إن كان مسافراً ليس في بلده فإنه يصلي صلاة قصر، يصلي ثنتين الظهر ثنتين والعصر ثنتين والعشاء ثنتين كسائر المسافرين، والسنة لهم أن يصلوها كما صلاها النبي صلى الله عليه وسلم، يصلوها جماعة، الواجب أن يصلوها جماعة مع القدرة بإمام، ويصلي بهم ركعتين، وإذا كان العدو في القبلة يصلي بهم جميعاً، ويركع بهم جميعاً، ثم يسجد بالصف الأول، ويبقى الصف الثاني يراقب لئلا يهجم العدو، فإذا قام الصف الأول من السجود سجد الصف الثاني كما فعله الصحابة مع النبي صلى الله عليه وسلم، ثم بعد ذلك يتقدم الصف الأول ويتأخر الصف الثاني، ويصلي بهم جميعاً ويركع بهم جميعاً ثم يسجد بالصف الأول الذي كان مؤخراً في الركعة الأولى، ويقف الصف الثاني الذي هو المقدم في الأولى يقف ينتظر وينظر ويحرس، فإذا قام الصف الأول من سجوده سجد الصف الثاني، ثم سلم بهم جميعاً، هذا نوع من صلاة الخوف، وهناك أنواع أخرى في صلاة الخوف، ينبغي أن يراعيها الإمام الذي يصلي بهم، ومنها. أنه يصلي بطائفة ركعة ثم تصلي لنفسها الركعة الثانية وتسلم وتذهب للحراسة، وتأتي الطائفة الأخرى فتصلي معه الركعة الثانية فإذا فرغت من السجود قامت وقضت ما عليها من ركعة ثم سلم بها، هذا نوع آخر فعله النبيﷺ، وهناك أنواع أخرى تعرف من كتب أهل الحديث مثل بلوغ المرام.. مثل منتقى الأخبار.. مثل صحيح البخاري .. مثل صحيح مسلم ، السنن الأربع، موضحة فيها أنواع صلاة الخوف، ويجوز أن يصلي بهم ركعة واحدة هذا على القول المختار أيضاً، يجوز أن تصلي كل طائفة ركعة واحدة، أو يصلي بهم جميعاً ركعة واحدة، فلا بأس.\nالحاصل أن صلاة الخوف أنواع معروفة فينبغي للإمام أن يصلي بهم ما تيسر من الأنواع التي يستطيعها، فإذا لم يستطيعوا وصارت الحرب شديدة والاختلاط بين العدو وخصمه فإنهم يصلون رجالاً وركباناً ولو بالإيماء، كل يصلي لنفسه، مستقبل القبلة وغير مستقبلها عند الضرورة كما قال الله جل وعلا: فَإِنْ خِفْتُمْ فَرِجَالًا أَوْ رُكْبَانًا [البقرة:239].\nوأما إن كان الحرب في الحضر في بلد الإقامة فإنه يصلي أربعاً كسائر المقيمين، ولا يصلي ثنتين، إنما هذا في السفر خاصة، أما الذي حربه في البلد في أطراف البلد فيصلي أربعاً ولا يصلي ثنتين. نعم.\nالمقدم: لكن في الحرب إذا كان في المعركة وعلى دبابته أو ما شابه ذلك يصلي على أي .... ؟\nالشيخ: ... يصلي على حاله بالإيماء، إذا لم يقدر على غيرها، وإن قدر يركع ويسجد في محله الذي يصلي فيه فعل وإلا صلى بالإيماء، وإن قدر إلى القبلة فالحمد لله وإلا إلى أي جهة..\nالمقدم: إلى أي جهة؟\nالشيخ: نعم. عند الضرورة.\nالمقدم: عند الضرورة؟\nالشيخ: عند الضرورة. نعم.","link":"https://binbaz.org.sa/fatwas/5446/كيفية-الصلاة-في-الحرب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_066/06602.mp3","categories":["صلاة الخوف","وقت الصلاة"]},{"id":8058,"question":"سؤالها الأخير تقول: السؤال الثالث: هو أنني ملتزمة بدوام رسمي في دائرتين من الساعة السابعة والنصف صباحاً حتى حدود الخامسة عصراً، أو الرابعة عصراً، فإنني أصلي صلاة الظهر حدود الواحدة والنصف ظهراً، أو الثانية، أو الثانية والنصف، فهل تصح هذه الصلاة، مع العلم بأن هذه الصلاة تكون ضمن الدوام الثاني في الدائرة الثانية، وليس لدي وقت ولا مكان لكي أصليها في وقتها في الدائرة الأولى، أما صلاة العصر فأصليها عندما أعود إلى المنزل؟ فهل هذه الصلاة صحيحة أفيدوا؟","title":"حكم تأخير الصلاة بسبب العمل إلى ما قبل خروج الوقت","answer":"الجواب: لا حرج فيه الصلاة صحيحة، ولكن الواجب عليها أن تحذر التساهل حتى يخرج الوقت في الظهر، فإن الصلاة عند ثنتين ونصف قرب خروج الوقت، فينبغي أن تقدمي صلاة الظهر قبل هذا، حتى تحتاطي لدينك ولصلاتك، فإذا حضرت الصلاة صليتيها في الدائرة الأولى، واجتهدت في المكان المناسب، حتى تصلي فيه صلاة الظهر في أول وقتها، هذا هو الأفضل، فإن لم يتيسر ذلك فلا حرج أن تصليها في الدائرة الثانية أو في البيت في الوقت، قبل خروج الوقت، ولو في آخر الوقت، لكن لا يجوز أبداً أن تؤخر إلى خروج الوقت، بل يجب أن تقدم قبل العصر، قبل وقت العصر، والعصر كذلك تراعى، تراعى صلاتها قبل أن تصفر الشمس، يجب أن يراعي المؤمن أداء الصلاة صلاة العصر، قبل أن تصفر الشمس، في أي مكان كان، ولا يجوز تأخير العصر إلى أن تصفر الشمس، بل لابد أن تفعل والشمس حية واضحة بيضاء، ليس بها اصفرار، في أي دائرة كان وفي السفر أو في الحضر؛ لأن حق الله يجب أن يقدم على حق المخلوقين، الصلاة مستثناة من هذه الأعمال لابد من فعلها في أوقاتها، وإن كان الإنسان في هذه الأعمال، فإنه يجب أن يتحرى الوقت المناسب حتى يصلي الصلاة في وقتها، مؤدياً حق الله، ومحافظاً عليه، ومبتعداً عن كل ما يسبب إضاعة حق الله.","link":"https://binbaz.org.sa/fatwas/5852/حكم-تاخير-الصلاة-بسبب-العمل-الى-ما-قبل-خروج-الوقت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_082/08206.mp3","categories":["وقت الصلاة"]},{"id":8154,"question":"سؤاله الثاني: سؤال عبد الكريم من الحدود الشمالية يقول: هل اللزوم فجراً له حد فاصل قاطع مثلما يكون للإفطار عند أذان المغرب، أم أنه فيه تساهل؛ لأننا نرى كثيراً من الناس يقولون: الفجر ليس مثل المساء؟","title":"عدم استواء الفجر والمغرب في معرفة وقت دخولهما","answer":"الجواب: صدقوا، الفجر لابد من تبين الصبح، إذا بان الصبح؛ لأن الله قال: وَكُلُوا وَاشْرَبُوا حَتَّى يَتَبَيَّنَ لَكُمُ الْخَيْطُ الأَبْيَضُ مِنَ الْخَيْطِ الأَسْوَدِ مِنَ الْفَجْرِ [البقرة:187].\nفلابد أن يتبين الصبح، مادام فيه شك الصبح فللناس أن يأكلوا ويشربوا حتى يتضح الصبح، ويعترض في جهة الشرق صبح واضح، فإن الصادق يعترض في الأفق وينتشر يميناً وشمالاً ويثبت ويزيد نوره، هذا هو الفجر الصادق، أما الكاذب فيستطيل في الأفق ثم يذهب ويضمحل، أما غروب الشمس فمعروف، إذا أذن المؤذن لغروب الشمس أفطر الناس، وإذا سقطت الشمس وهو في البرية رآها سقطت أفطر، واضح.. مسألة الشمس واضحة، سقوطها واضح، أما الصبح فقد يشتبه على الناس بالصبح الكاذب، فإن فيه صبح كاذب يكون عمود ومثلما قال ............. يكون عمود مرتكز مضيء ثم يذهب ويضمحل مظلم، ثم يأتي بعده الفجر الصادق، فالفجر الصادق هو الذي عليه العمدة هو الذي يستطيل في الأفق ينتشر، هكذا يمتد في جهة الأفق يميناً وشمالاً حتى يعترض مستطيل ويزداد نوره ويتضح نوره، هذا هو الصادق. نعم.","link":"https://binbaz.org.sa/fatwas/5953/عدم-استواء-الفجر-والمغرب-في-معرفة-وقت-دخولهما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_090/09005.mp3","categories":["وقت الصلاة"]},{"id":8630,"question":"هذه رسالة وردتنا من السائل يوسف عمر ، من الخرطوم جمهورية السودان الديمقراطية، يقول في رسالته: أرجو أن تفيدوني عن الوقت الضروري لكل من صلاة الظهر والعصر والمغرب؟","title":"ما الوقت الضروري لصلاة الظهر والعصر والمغرب؟","answer":"الجواب: أما الظهر فليس فيها وقت ضروري كله وقت اختيار، فإذا زالت الشمس دخل وقت الظهر ولا يزال الوقت وقت اختيار إلى أن يصير ظل كل شيء مثله بعد فيء الزوال، كل هذا وقت اختيار، لكن الأفضل تقديمها في أول الوقت بعدما يؤذن وتصلى الراتبة ويتأنى الإمام بعض الوقت حتى يتلاحق الناس يصلون في أول الوقت هذا هو الأفضل، ولو أخر ذلك إلى نصف الوقت أو إلى آخر الوقت فلا حرج.\nوأما العصر ففيها وقت اختيار ووقت ضرورة، أما الاختيار فمن أول وقت العصر إلى أن تصفر الشمس هذا اختيار، فإذا اصفرت الشمس هذا ضرورة لا يجوز التأخير إليه، فإن صلاها في ذلك الوقت فقد أداها في الوقت إلى أن تغيب الشمس، لكن لا يجوز له التأخير؛ لأن النبي ﷺ قال: وقت العصر ما لم تصفر الشمس ويقول في المنافق: تلك صلاة المنافق.. تلك صلاة المنافق يرقب الشمس حتى إذا كانت بين قرني شيطان قام فنقر أربعاً لا يذكر الله فيها إلا قليلا هو ذكر هذا وصف المنافقين، فالمؤمن لا يؤخرها إلى أن تصفر الشمس بل يبادر فيصليها قبل أن تصفر الشمس في وقت الاختيار.\nوأما المغرب فوقتها كله وقت اختيار أيضاً من حين تغرب الشمس إلى أن يغيب الشفق كله وقت اختيار، لكن تقديمها في أول الوقت أفضل، كان النبي يصليها في أول الوقت عليه الصلاة والسلام، إذا أذن المؤذن أخر قليلاً ثم أقام عليه الصلاة والسلام فصلاها في أول الوقت، ولو أخر بعض الوقت فلا بأس، ووقتها ينتهي بغيبوبة الشفق إذا غاب الشفق وهو الحمرة في جهة المغرب انتهى وقت المغرب، فهو وقت ممتد إلى أن يغيب الشفق الأحمر فإذا غاب دخل وقت العشاء إلى نصف الليل، وما بعد نصف الليل وقت ضرورة للعشاء فلا يجوز التأخير إلى بعد نصف الليل ولكن ما بين غروب الشفق إلى نصف الليل كله وقت للعشاء، فلو صلاها بعد نصف الليل أداها في الوقت لكنه يأثم؛ لأنه أخرها إلى وقت الضرورة.\nأما الفجر فكل وقتها اختيار من طلوع الفجر إلى طلوع الشمس هذا كله وقت اختيار، لكن الأفضل أن تقدم في أول وقتها ولا تؤخر إلى أن يزول أثر الليل ويبقى النور كاملاً، بل الأفضل والأولى أن يصليها بغلس ولا يجوز تأخيرها إلى طلوع الشمس، بل يجب أن تقدم قبل طلوع الشمس، والأفضل أن تصلى بغلس بعد طلوع الفجر بعد أن يشق الفجر ويتحقق يصلي الناس الفجر. نعم.\nالمقدم: بارك الله فيكم وجزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/6763/ما-الوقت-الضروري-لصلاة-الظهر-والعصر-والمغرب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_211/21104.mp3","categories":["وقت الصلاة"]},{"id":9208,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من إحدى الأخوات المستمعات تقول: أختكم أم أيمن من الدمام، أختنا بدأت أسئلتها بالتالي:في بعض المحاضرات لا ننتهي إلا في الثانية عشرة والنصف أو الثانية عشرة والربع، في حين أن وقت صلاة الظهر في الساعة الحادية عشرة والنصف، هل نأثم بهذا التأخير؟","title":"حكم تأخير الصلاة عن أول وقتها بسبب المحاضرات الجامعية","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nالصلاة في أول الوقت أفضل، ولكن إذا أخرت لأسباب في أثناء الوقت فلا بأس بذلك إنما المحرم تأخيرها عن وقتها، أما كونها تؤخر عن أول الوقت فلا حرج في ذلك والحمد لله. نعم.","link":"https://binbaz.org.sa/fatwas/7368/حكم-تاخير-الصلاة-عن-اول-وقتها-بسبب-المحاضرات-الجامعية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_152/15201.mp3","categories":["وقت الصلاة"]},{"id":9240,"question":"السؤال الثالث في هذه الرسالة يقول فيه الإخوة: نحن عمال في مزرعة نصلي جميع الفرائض بها، وذلك لبعد المسجد عنا حوالي اثنين كيلو متر، ولعدم سماعنا الأذان فنحن نؤذن ونقيم في المزرعة، وربما أخرنا الصلاة عن وقتها نصف ساعة من أجل العمل فما حكم ذلك؟","title":"حكم الصلاة في المزرعة وتأخيرها عن أول وقتها بقليل","answer":"الجواب: لا حرج في صاحب المزرعة إذا كان المسجد بعيداً عنه لا حرج، وكونه يؤخر عن أول الوقت نصف ساعة لا يضر، إذا كان التأخير على أول الوقت نصف ساعة فلا بأس، أما التأخير عن الوقت نفسه، لا يجوز التأخير عن الوقت، لكن إذا كان التأخير عن أول الوقت مثل: لا يصلون إلا بعد نصف ساعة من زوال الشمس، أو نصف ساعة من دخول وقت العصر، أو نصف ساعة من غروب الشمس، أو نصف ساعة من غروب الشفق هذا لا بأس به، لا حرج. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7405/حكم-الصلاة-في-المزرعة-وتاخيرها-عن-اول-وقتها-بقليل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_235/23504.mp3","categories":["صلاة الجماعة","وقت الصلاة"]},{"id":9251,"question":"السؤال الثالث في هذه الرسالة يقول فيه الإخوة: نحن عمال في مزرعة نصلي جميع الفرائض بها، وذلك لبعد المسجد عنا حوالي اثنين كيلو متر، ولعدم سماعنا الأذان فنحن نؤذن ونقيم في المزرعة، وربما أخرنا الصلاة عن وقتها نصف ساعة من أجل العمل فما حكم ذلك؟","title":"حكم الصلاة في المزرعة وتأخيرها عن أول وقتها بقليل","answer":"الجواب: لا حرج في صاحب المزرعة إذا كان المسجد بعيداً عنه لا حرج، وكونه يؤخر عن أول الوقت نصف ساعة لا يضر، إذا كان التأخير على أول الوقت نصف ساعة فلا بأس، أما التأخير عن الوقت نفسه، لا يجوز التأخير عن الوقت، لكن إذا كان التأخير عن أول الوقت مثل: لا يصلون إلا بعد نصف ساعة من زوال الشمس، أو نصف ساعة من دخول وقت العصر، أو نصف ساعة من غروب الشمس، أو نصف ساعة من غروب الشفق هذا لا بأس به، لا حرج. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7405/حكم-الصلاة-في-المزرعة-وتاخيرها-عن-اول-وقتها-بقليل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_235/23504.mp3","categories":["صلاة الجماعة","وقت الصلاة"]},{"id":9259,"question":"ما هو آخر وقت لصلاة العشاء؟","title":"آخر وقت صلاة العشاء","answer":"الجواب: آخر وقتها نصف الليل، إذا انتصف الليل لم يجز التأخير إليه ، لكن لو كان الإنسان ساهياً أو نائماً ثم استيقظ يصلي حين يستيقظ ولو في النصف الأخير لقول النبي ﷺ: من نام عن الصلاة أو نسيها فليصلها إذا ذكرها لا كفارة لها إلا ذلك، لكن ليس له أن يؤخرها عمداً، يقول النبي ﷺ: ووقت العشاء إلى نصف الليل فليس للمؤمن ولا للمؤمنة أن يؤخرا صلاة العشاء إلى نصف الليل، فإذا كان الليل تسع ساعات مثلاً: فالنصف أربع ونصف، وإذا كان الليل عشر ساعات فالنصف الساعة الخامسة من غروب الشمس ونهايتها.\nالمقصود: أن صلاة العشاء لا تؤخر إلى نصف الليل ولا مانع من تأخيرها إلى قرب نصف الليل إلى مضي ثلث الليل لا حرج في ذلك مثل: المرأة والمريض، أما الرجل يصلي مع الناس في المساجد وليس له أن يصلي في بيته ولا يؤخر بل يلزمه أن يصلي مع الناس في المساجد إذا كان صحيحاً، أما إذا كان مريضاً فهو معذور يصلي في بيته متى شاء قبل نصف الليل. نعم.","link":"https://binbaz.org.sa/fatwas/7422/اخر-وقت-صلاة-العشاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_153/15309.mp3","categories":["وقت الصلاة"]},{"id":9678,"question":"أولى الرسائل وردت من المرسل سليمان من المدينة المنورة، يقول في رسالته: نحن نقضي وقت المغرب حتى العشاء في الجلوس أمام مشاهدة المباراة في التلفاز وأحياناً سماعها بالراديو، ونصلي لكن بعد انتهاء وقت العشاء، فهل نقدم المغرب على العشاء أم العشاء على المغرب، أفيدونا أفادكم الله؟","title":"حكم تأخير الصلاة عن وقتها بسبب الانشغال بمشاهدة المباريات","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فالواجب على كل مسلم أن يقدم حق الله على هوى نفسه، وعلى مشاهداته للمباراة وغير المباراة. فالصلاة حق الله، وهي فرض على المسلم في كل وقت، ومن فرائضها أن تؤدى في الجماعة.\nفالواجب على من يشاهد المباراة وعلى غيره أن يدع ما هو فيه عند حضور الصلاة، وأن يبادر ويسارع إلى أدائها مع إخوانه في الجماعة، وليس له عذر أن يترك الجماعة ويصلي في البيت بعدما تنتهي الجماعة، وبعدما يفرغ من حظه العاجل بالمباراة، فهذا غلط عظيم ومنكر كبير فيجب الحذر منه.\nفالواجب على المسلمين أن يهتموا بأمر دينهم قبل كل شيء، والصلاة هي أعظم الأركان وأهم الأركان بعد الشهادتين، وقد قال فيها الرب : حَافِظُوا عَلَى الصَّلَوَاتِ وَالصَّلاةِ الْوُسْطَى [البقرة:238] وقال سبحانه: إِنَّ الصَّلاةَ كَانَتْ عَلَى الْمُؤْمِنِينَ كِتَابًا مَوْقُوتًا [النساء:103] وقال: وَأَقِيمُوا الصَّلاةَ وَآتُوا الزَّكَاةَ وَارْكَعُوا مَعَ الرَّاكِعِينَ [البقرة:43] يعني: صلوا مع المصلين.\nوقال سبحانه: وَإِذَا كُنتَ فِيهِمْ فَأَقَمْتَ لَهُمُ الصَّلاةَ فَلْتَقُمْ طَائِفَةٌ مِنْهُمْ مَعَكَ وَلْيَأْخُذُوا أَسْلِحَتَهُمْ فَإِذَا سَجَدُوا فَلْيَكُونُوا مِنْ وَرَائِكُمْ وَلْتَأْتِ طَائِفَةٌ أُخْرَى لَمْ يُصَلُّوا فَلْيُصَلُّوا مَعَكَ وَلْيَأْخُذُوا حِذْرَهُمْ وَأَسْلِحَتَهُمْ [النساء:102] الآية. فلم يعذرهم سبحانه مع الخوف ومع القتال لم يعذرهم في ترك الجماعة وترك الصلاة مع المسلمين، بل أمرهم أن ينقسموا طائفتين: طائفة تصلي معه مع الرسول ﷺ ثم تنصرف، ثم تأتي الطائفة الأخرى فتصلي معه بقية الصلاة، فيكونوا كلهم صلوا في الجماعة مع الخوف ومع مقابلة العدو، فكيف بحال الأمن والراحة.\nفالمقصود أن الواجب على المؤمن أن يقدم حق الله، وأن يرعى هذه الصلاة العظيمة، وأن يؤديها مع إخوانه في بيوت الله في المساجد، وأن يحذر إيثار مباراة أو غيرها على ذلك، وقد قال عليه الصلاة والسلام: من سمع النداء فلم يأت فلا صلاة له إلا من عذر قال لـعبد الله بن أم مكتوم لما سأله عن صلاة الجماعة وقال: يا رسول الله! إنه ليس لي قائد يلائمني إلى المسجد، فهل لي من رخصة أصلي في بيتي؟ قال له النبي عليه الصلاة والسلام: هل تسمع النداء بالصلاة؟ قال: نعم، قال: فأجب وفي لفظ، قال: لا أجد لك رخصة فإذا كان لا يجد رخصة للكفيف الذي ليس له قائد يلائمه فكيف بحال غيره؟!\nثم التهاون بأدائها في الجماعة وسيلة إلى تركها بالكلية، ووسيلة إلى التساهل بها حتى لا تؤدى إلا في آخر الوقت، فالواجب على المؤمن أن يحذر ذلك، وأن يصلي مع إخوانه في مساجد الله، وأن يبادر إلى ذلك، وأن لا يتشبه بالمنافقين، فالمنافق هو الذي يتساهل بها ولا يبالي بأدائها في الجماعة، فلا يجوز للمسلم أن يتشبه بالمنافقين، يقول عبد الله بن مسعود  في أمر الجماعة: لقد رأيتنا وما يتخلف عنها إلا منافق معلوم النفاق -وفي لفظ: أو مريض.\nفعلى المسلمين جميعاً أن يتقوا الله، وأن يعظموا ما عظمه الله، ومن ذلك أمر الصلاة فإنها عمود الإسلام وأعظم الفرائض وأهم الفرائض بعد الشهادتين، فالواجب على كل مسلم ومسلمة المحافظة عليها في أوقاتها، وعدم إيثار المباراة أو غيرها على ذلك، وعلى الرجل أن يصليها في الجماعة في المساجد مع الناس مع المسلمين دائماً، إلا أن يحبسه مرض، والله ولي التوفيق. نعم.\nالمقدم: بارك الله فيكم وجزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/7853/حكم-تاخير-الصلاة-عن-وقتها-بسبب-الانشغال-بمشاهدة-المباريات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_252/25210.mp3","categories":["وقت الصلاة"]},{"id":9680,"question":"أولى الرسائل وردت من المرسل سليمان من المدينة المنورة، يقول في رسالته: نحن نقضي وقت المغرب حتى العشاء في الجلوس أمام مشاهدة المباراة في التلفاز وأحياناً سماعها بالراديو، ونصلي لكن بعد انتهاء وقت العشاء، فهل نقدم المغرب على العشاء أم العشاء على المغرب، أفيدونا أفادكم الله؟","title":"حكم تأخير الصلاة عن وقتها بسبب الانشغال بمشاهدة المباريات","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فالواجب على كل مسلم أن يقدم حق الله على هوى نفسه، وعلى مشاهداته للمباراة وغير المباراة. فالصلاة حق الله، وهي فرض على المسلم في كل وقت، ومن فرائضها أن تؤدى في الجماعة.\nفالواجب على من يشاهد المباراة وعلى غيره أن يدع ما هو فيه عند حضور الصلاة، وأن يبادر ويسارع إلى أدائها مع إخوانه في الجماعة، وليس له عذر أن يترك الجماعة ويصلي في البيت بعدما تنتهي الجماعة، وبعدما يفرغ من حظه العاجل بالمباراة، فهذا غلط عظيم ومنكر كبير فيجب الحذر منه.\nفالواجب على المسلمين أن يهتموا بأمر دينهم قبل كل شيء، والصلاة هي أعظم الأركان وأهم الأركان بعد الشهادتين، وقد قال فيها الرب : حَافِظُوا عَلَى الصَّلَوَاتِ وَالصَّلاةِ الْوُسْطَى [البقرة:238] وقال سبحانه: إِنَّ الصَّلاةَ كَانَتْ عَلَى الْمُؤْمِنِينَ كِتَابًا مَوْقُوتًا [النساء:103] وقال: وَأَقِيمُوا الصَّلاةَ وَآتُوا الزَّكَاةَ وَارْكَعُوا مَعَ الرَّاكِعِينَ [البقرة:43] يعني: صلوا مع المصلين.\nوقال سبحانه: وَإِذَا كُنتَ فِيهِمْ فَأَقَمْتَ لَهُمُ الصَّلاةَ فَلْتَقُمْ طَائِفَةٌ مِنْهُمْ مَعَكَ وَلْيَأْخُذُوا أَسْلِحَتَهُمْ فَإِذَا سَجَدُوا فَلْيَكُونُوا مِنْ وَرَائِكُمْ وَلْتَأْتِ طَائِفَةٌ أُخْرَى لَمْ يُصَلُّوا فَلْيُصَلُّوا مَعَكَ وَلْيَأْخُذُوا حِذْرَهُمْ وَأَسْلِحَتَهُمْ [النساء:102] الآية. فلم يعذرهم سبحانه مع الخوف ومع القتال لم يعذرهم في ترك الجماعة وترك الصلاة مع المسلمين، بل أمرهم أن ينقسموا طائفتين: طائفة تصلي معه مع الرسول ﷺ ثم تنصرف، ثم تأتي الطائفة الأخرى فتصلي معه بقية الصلاة، فيكونوا كلهم صلوا في الجماعة مع الخوف ومع مقابلة العدو، فكيف بحال الأمن والراحة.\nفالمقصود أن الواجب على المؤمن أن يقدم حق الله، وأن يرعى هذه الصلاة العظيمة، وأن يؤديها مع إخوانه في بيوت الله في المساجد، وأن يحذر إيثار مباراة أو غيرها على ذلك، وقد قال عليه الصلاة والسلام: من سمع النداء فلم يأت فلا صلاة له إلا من عذر قال لـعبد الله بن أم مكتوم لما سأله عن صلاة الجماعة وقال: يا رسول الله! إنه ليس لي قائد يلائمني إلى المسجد، فهل لي من رخصة أصلي في بيتي؟ قال له النبي عليه الصلاة والسلام: هل تسمع النداء بالصلاة؟ قال: نعم، قال: فأجب وفي لفظ، قال: لا أجد لك رخصة فإذا كان لا يجد رخصة للكفيف الذي ليس له قائد يلائمه فكيف بحال غيره؟!\nثم التهاون بأدائها في الجماعة وسيلة إلى تركها بالكلية، ووسيلة إلى التساهل بها حتى لا تؤدى إلا في آخر الوقت، فالواجب على المؤمن أن يحذر ذلك، وأن يصلي مع إخوانه في مساجد الله، وأن يبادر إلى ذلك، وأن لا يتشبه بالمنافقين، فالمنافق هو الذي يتساهل بها ولا يبالي بأدائها في الجماعة، فلا يجوز للمسلم أن يتشبه بالمنافقين، يقول عبد الله بن مسعود  في أمر الجماعة: لقد رأيتنا وما يتخلف عنها إلا منافق معلوم النفاق -وفي لفظ: أو مريض.\nفعلى المسلمين جميعاً أن يتقوا الله، وأن يعظموا ما عظمه الله، ومن ذلك أمر الصلاة فإنها عمود الإسلام وأعظم الفرائض وأهم الفرائض بعد الشهادتين، فالواجب على كل مسلم ومسلمة المحافظة عليها في أوقاتها، وعدم إيثار المباراة أو غيرها على ذلك، وعلى الرجل أن يصليها في الجماعة في المساجد مع الناس مع المسلمين دائماً، إلا أن يحبسه مرض، والله ولي التوفيق. نعم.\nالمقدم: بارك الله فيكم وجزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/7853/حكم-تاخير-الصلاة-عن-وقتها-بسبب-الانشغال-بمشاهدة-المباريات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_252/25210.mp3","categories":["وقت الصلاة"]},{"id":9833,"question":"لها استفسار آخر في رسالتها تقول فيه: ما حكم تأخير صلاة العشاء حتى الساعة السادسة مساءً بالتوقيت الغروبي؟","title":"ما حكم تأخير صلاة العشاء؟","answer":"الجواب: الواجب أن تكون صلاة العشاء قبل النصف، ولا يجوز تأخيرها إلى النصف؛ لقوله ﷺ: وقت صلاة العشاء إلى نصف الليل، فعليك أن تصليها قبل نصف الليل، على حسب دوران الفلك، فإن الليل يزيد وينقص، والضابط هو نصف الليل بالساعات، فإذا كان الليل عشر ساعات لم يجز لك أن تأخيرها إلى الساعة الخامسة، وإذا كان الليل إحدى عشرة ساعة لم يجز تأخيرها إلى الخامسة والنصف.. وهكذا، وأفضل ما يكون أن تكون في الثلث الأول، ومن صلاها في أول الوقت فلا بأس، لكن إذا أخرها بعض الوقت فهو الأفضل، إذا أخرها عن أول الوقت بعض الشيء فهذا هو الأفضل؛ لأن الرسول ﷺ كان يستحب أن يؤخر صلاة العشاء بعض الوقت عليه الصلاة والسلام، ومن صلاها في أول الوقت بعد غروب الشفق هو الحمرة التي في الغرب فلا بأس بذلك، لكن تأخيرها في المساجد وغيرها شيئًا من الوقت يكون أفضل. نعم.\nالمقدم: جزاكم الله خيرا.","link":"https://binbaz.org.sa/fatwas/7997/ما-حكم-تاخير-صلاة-العشاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_198/19803.mp3","categories":["وقت الصلاة"]},{"id":9956,"question":"تقول صاحبتنا هذه أيضاً في آخر رسالتها: ما حكم صلاة الفجر بعد ظهور نور الفجر؟","title":"وقت الفجر الصادق الذي تجوز الصلاة فيه","answer":"الجواب: متى طلع الفجر واتضح الفجر الصادق الذي يتسع في المشرق، فإن المرأة والرجل كلاهما يصح منه صلاة الفجر متى اتضح؛ لأن الفجر فجران: فجر صادق وهو الذي ينتشر في الجو في جو الشرقي ويتسع. وفجر كاذب وهو الذي يستطيل قائماً في الأفق ثم يذهب ويزول، فإذا جاء الفجر الصادق المنتشر في المشرق فإن هذا يدخل به وقت الفجر وتصح به الصلاة، لكن عدم العجلة حتى يتضح وحتى ينشق الفجر ويكون واضحاً هذا هو الأفضل، مع بقاء الغلس هذا هو الأفضل، والرجل يذهب إلى المسجد ويصلي مع الناس، والمساجد عندها علم بهذا الأمر أي: أنها لا تعجل حتى يتضح الفجر، هذا هو الواجب على الأئمة أن يعنوا بالفجر وأن لا يعجلوا حتى يتحقق طلوع الفجر وحتى يتضح الفجر ثم يصلوا بعد ذلك بغلس، هذا هو الأفضل والوقت يستمر إلى طلوع الشمس، لكن لا يجوز تأخير الصلاة إلى طلوع الشمس ويكره تأخيرها إلى الإسفار الكثير، ولكن السنة البدار بها بعد التحقق من طلوع الفجر وبعد وضوحه، لكن ما دام هناك بعض الغلس، هذا هو الأفضل. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/8145/وقت-الفجر-الصادق-الذي-تجوز-الصلاة-فيه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_266/26605.mp3","categories":["وقت الصلاة"]},{"id":9965,"question":"تقول صاحبتنا هذه أيضاً في آخر رسالتها: ما حكم صلاة الفجر بعد ظهور نور الفجر؟","title":"وقت الفجر الصادق الذي تجوز الصلاة فيه","answer":"الجواب: متى طلع الفجر واتضح الفجر الصادق الذي يتسع في المشرق، فإن المرأة والرجل كلاهما يصح منه صلاة الفجر متى اتضح؛ لأن الفجر فجران: فجر صادق وهو الذي ينتشر في الجو في جو الشرقي ويتسع. وفجر كاذب وهو الذي يستطيل قائماً في الأفق ثم يذهب ويزول، فإذا جاء الفجر الصادق المنتشر في المشرق فإن هذا يدخل به وقت الفجر وتصح به الصلاة، لكن عدم العجلة حتى يتضح وحتى ينشق الفجر ويكون واضحاً هذا هو الأفضل، مع بقاء الغلس هذا هو الأفضل، والرجل يذهب إلى المسجد ويصلي مع الناس، والمساجد عندها علم بهذا الأمر أي: أنها لا تعجل حتى يتضح الفجر، هذا هو الواجب على الأئمة أن يعنوا بالفجر وأن لا يعجلوا حتى يتحقق طلوع الفجر وحتى يتضح الفجر ثم يصلوا بعد ذلك بغلس، هذا هو الأفضل والوقت يستمر إلى طلوع الشمس، لكن لا يجوز تأخير الصلاة إلى طلوع الشمس ويكره تأخيرها إلى الإسفار الكثير، ولكن السنة البدار بها بعد التحقق من طلوع الفجر وبعد وضوحه، لكن ما دام هناك بعض الغلس، هذا هو الأفضل. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/8145/وقت-الفجر-الصادق-الذي-تجوز-الصلاة-فيه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_266/26605.mp3","categories":["وقت الصلاة"]},{"id":10122,"question":"متى ينتهي وقت صلاة العشاء؟","title":"وقت صلاة العشاء الاختياري والاضطراري","answer":"الجواب: بنصف الليل، إذا انتصف الليل هذه النهاية، وقت النبي ﷺ صلاة العشاء إلى نصف الليل كما في حديث عبدالله بن عمرو قال: وقت العشاء إلى نصف الليل الأوسط وقت الليل يختلف؛ فإذا كان الليل عشر ساعات بمضي خمس من الليل انتهى النصف، وإذا كان الليل اثنى عشر بمضي ست ساعات انتهى النصف، فلا يجوز للمؤمن أن يؤخر الصلاة بعد النصف، يصلي قبل النصف، والواجب أن يصلي في الجماعة إلا المعذور كالمريض والمرأة فليس لهم أن يؤخروها إلى بعد نصف الليل. نعم.\nالمقدم: علمت منكم سماحة الشيخ أن هناك وقت أيضًا يمكن أن يصلي فيه المسلم صلاة العشاء وهو بعد منتصف الليل..\nالشيخ: إذا فاتته، إذا فاته صلاها بعد النصف؛ لأن ما بعد النصف وقت ضرورة إلى طلوع الفجر، مثل من فاتته الصلاة في العصر حتى اصفرت الشمس يصليها ولو بعد اصفرار الشمس، ويكون آثم إذا كان تعمد هذا، ولكن صلاتها في الوقت، ولكن ليس له أن يؤخر إلى بعد نصف الليل وليس له أن يؤخر العصر إلى بعد اصفرار الشمس، لكن لو أنه مثلًا عرض عارض واصفرت الشمس ليس له التأخير بل يبادر ويصلي قبل غروب الشمس صلاة العصر، ويتوب إلى الله إن كان متعمدًا، وهكذا العشاء لو أخرها غفلة منه أو سهوًا منه حتى انتصف الليل فعليه التوبة مع فعلها بعد نصف الليل، لا يؤخر إلى الفجر، يجب أن يبادر حتى يصلي قبل بعد نصف الليل مع التوبة إلى الله إذا كان عن تعمد، أما إن كان نسيان أو نوم فلا شيء عليه.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8293/وقت-صلاة-العشاء-الاختياري-والاضطراري","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_334/33409.mp3","categories":["وقت الصلاة"]},{"id":10186,"question":"رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين يقول (و. ع. أ) هذه الرسالة مشتملة على جمع من الأسئلة من بينها سؤال يقول: أنا والحمد لله أحب أن أصلي الصلاة في وقتها، إذا أذن المؤذن ولم أتمكن من الذهاب إلى المسجد هل أصلي بعد الأذان مباشرة أم بعد الإقامة؟","title":"وقت الصلاة يدخل بالأذان لا الإقامة","answer":"الجواب: الواجب عليك الذهاب إلى المسجد إذا كنت سليماً، وأما إذا كان هناك علة لمرض أو ممنوع من الخروج من بيتك كالسجين أو ما أشبه ذلك فإنك تصلي بعد الأذان، وليس لك تعلق بالإمامة والإقامة، تصلي إذا دخل الوقت سواء قبل الناس أو بعد الناس، لست مربوطاً بإقامة الصلاة، بل تصلي قبلهم أو بعدهم، إذا كنت عاجزاً عن الذهاب إلى المسجد لمرض أو نحوه، أما إذا كنت قادراً فالواجب عليك أن تجيب المؤذن وأن تصلي مع المسلمين؛ لقول النبي ﷺ: من سمع النداء فلم يأت فلا صلاة له إلا من عذر ولأنه ﷺ لما جاءه رجل أعمى قال: يا رسول الله! ليس لي قائد يقودني إلى المسجد، فهل لي من رخصة أن أصلي في بيتي؟ أجابه ﷺ بقوله: هل تسمع النداء بالصلاة؟ قال: نعم، قال: فأجب رواه مسلم في صحيحه، وفي رواية أخرى لغير مسلم: لا أجد لك رخصة فإذا كان الأعمى الذي ليس له قائد يلائمه ليس له رخصة فكيف بغيره؟! فالواجب عليك يا أخي أن تحرص على الصلاة في الجماعة، وإذا كنت معذوراً عذراً شرعياً فأنت بحمد الله تصلي إن شئت قبلهم أو بعدهم لا حرج عليك.","link":"https://binbaz.org.sa/fatwas/8376/وقت-الصلاة-يدخل-بالاذان-لا-الاقامة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_309/30915.mp3","categories":["الأذان والإقامة","وقت الصلاة"]},{"id":10189,"question":"رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين يقول (و. ع. أ) هذه الرسالة مشتملة على جمع من الأسئلة من بينها سؤال يقول: أنا والحمد لله أحب أن أصلي الصلاة في وقتها، إذا أذن المؤذن ولم أتمكن من الذهاب إلى المسجد هل أصلي بعد الأذان مباشرة أم بعد الإقامة؟","title":"وقت الصلاة يدخل بالأذان لا الإقامة","answer":"الجواب: الواجب عليك الذهاب إلى المسجد إذا كنت سليماً، وأما إذا كان هناك علة لمرض أو ممنوع من الخروج من بيتك كالسجين أو ما أشبه ذلك فإنك تصلي بعد الأذان، وليس لك تعلق بالإمامة والإقامة، تصلي إذا دخل الوقت سواء قبل الناس أو بعد الناس، لست مربوطاً بإقامة الصلاة، بل تصلي قبلهم أو بعدهم، إذا كنت عاجزاً عن الذهاب إلى المسجد لمرض أو نحوه، أما إذا كنت قادراً فالواجب عليك أن تجيب المؤذن وأن تصلي مع المسلمين؛ لقول النبي ﷺ: من سمع النداء فلم يأت فلا صلاة له إلا من عذر ولأنه ﷺ لما جاءه رجل أعمى قال: يا رسول الله! ليس لي قائد يقودني إلى المسجد، فهل لي من رخصة أن أصلي في بيتي؟ أجابه ﷺ بقوله: هل تسمع النداء بالصلاة؟ قال: نعم، قال: فأجب رواه مسلم في صحيحه، وفي رواية أخرى لغير مسلم: لا أجد لك رخصة فإذا كان الأعمى الذي ليس له قائد يلائمه ليس له رخصة فكيف بغيره؟! فالواجب عليك يا أخي أن تحرص على الصلاة في الجماعة، وإذا كنت معذوراً عذراً شرعياً فأنت بحمد الله تصلي إن شئت قبلهم أو بعدهم لا حرج عليك.","link":"https://binbaz.org.sa/fatwas/8376/وقت-الصلاة-يدخل-بالاذان-لا-الاقامة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_309/30915.mp3","categories":["الأذان والإقامة","وقت الصلاة"]},{"id":10358,"question":"قد يعيش مع الإنسان أناس يصلون ولكنهم يتأخرون عن صلاة الفجر بمقدار ساعة، كيف هو التوجيه، لو تكرمتم؟","title":"حكم تأخير صلاة الفجر ساعة بعد الأذان","answer":"الجواب: الواجب على المسلم والمسلمة فعل الصلاة في الوقت، الفجر والمغرب والعشاء والظهر والعصر يجب على المسلم والمسلمة أن يعتني بأداء الصلاة في الوقت، ولا يجوز لكل منهما تأخيرها عن الوقت، ويزيد الرجل في ذلك صلاتها في جماعة، يلزمه أن يصليها في الجماعة في مساجد الله، والمرأة تصليها في البيت لأنه خير لها، ولا يجوز له ولا لها التأخير عن الوقت، فالفجر تصلى قبل طلوع الشمس، والظهر بعد الزوال وقبل وقت العصر، والعصر في وقتها قبل أن تصفر الشمس، والمغرب في وقتها قبل أن يذهب الشفق، والعشاء في وقتها قبل أن ينتصف الليل، عليهما جميعًأ فعلها في الوقت.\nوعلى الزوج على الرجل أن يصليها في الجماعة في مساجد الله لا في البيت، وصلاتها في البيت من الرجل مشابهة لأعداء الله المنافقين، قال الله تعالى: إِنَّ الْمُنَافِقِينَ يُخَادِعُونَ اللَّهَ وَهُوَ خَادِعُهُمْ وَإِذَا قَامُوا إِلَى الصَّلاةِ قَامُوا كُسَالَى [النساء:142].\nفلا يجوز للمسلم أن يتشبه بأعداء الله المنافقين، لا بالكسل في الصلاة والتثاقل عنها ولا بفعلها في البيت، بل يجب أن يسابق إليها وأن يؤديها مع الجماعة في مساجد الله في وقتها مع الجماعة، وعلى المرأة كذلك أن تؤديها في وقتها وأن تحذر التكاسل والتثاقل؛ لأن هذا من صفات أهل النفاق.\nولا يجوز تأخير الفجر إلى طلوع الشمس بل يجب أن تصلى في الوقت، وما يفعله بعض الناس من تأخيرها حتى يقوم إلى العمل هذا منكر عظيم، وقد ذهب بعض أهل العلم إلى كفر من فعل ذلك وتعمده نسأل الله العافية.\nفالواجب الحذر وأن يصليها في الوقت، وأن يحرص على أدائها في الجماعة، وأن لا يطيع الشيطان في ذلك، وعلى زوجته أن تعينه على ذلك بالإيقاظ والوعظ والتذكير، وأن يتخذا ساعة منبهة تعينهما على ذلك، إلا إذا كان عندهما من يوقظهما.\nفالمقصود: أن الواجب أن تؤدى الصلوات الخمس في أوقاتها جميعها، يجب أن تؤدى كلها في أوقاتها، وأمر مع ذلك على الرجل أن يؤديها في الجماعة في مساجد الله، لقوله ﷺ: من سمع النداء فلم يأت فلا صلاة له إلا من عذر، وقد ثبت عنه في الصحيحين عليه الصلاة والسلام أنه هم أن يحرق على المتخلفين عن الصلاة في الجماعة بيوتهم لعظم جريمتهم، ولأنهم متشبهون في ذلك بالمنافقين.\nفعلى المؤمن أن يحذر ذلك وأن يتقي الله، وعلى الزوجة والمرأة عليها أن تتقي الله وأن تؤدي الواجب، فالصلاة تؤدى في وقتها، وهكذا بقية الواجبات عليها أن تحرص عليها، وعلى الرجل أن يحرص على أداء جميع ما أوجب الله عليه، فالصلاة في وقتها والزكاة في وقتها، والصيام في وقته، وهكذا على كل منهما أن يعتني بما أوجب الله عليه وأن يحذر ما حرم الله عليه؛ لأن هذه الدار دار العمل وكلاهما مخلوق للعبادة، يقول الله سبحانه: وَمَا خَلَقْتُ الْجِنَّ وَالإِنسَ إِلَّا لِيَعْبُدُونِ [الذاريات:56] لم يخلقا للأكل والشرب والعمل فيما يحصل الدنيا لا، خلقا لعبادة الله، خلقا ليعبدا الله، الرجل خلق ليعبد ربه والمرأة كذلك، فالجن والإنس جميعًأ خلقوا ليعبدوا الله، كلهم خلقوا ليعبدوا الله.\nوعبادة الله: هي طاعته بفعل أوامره وترك نواهيه عن إخلاص له سبحانه وتعظيم له، وصدق في ذلك، وعن متابعة نبيه عليه الصلاة والسلام، وعن رغبة فيما عند الله ورهبة فيما عنده ، هكذا يجب على الرجال والنساء من الجن الإنس.\nرزق الله الجميع التوفيق والهداية.\nالمقدم: اللهم آمين، جزاكم الله خيرًأ.","link":"https://binbaz.org.sa/fatwas/8523/حكم-تاخير-صلاة-الفجر-ساعة-بعد-الاذان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_338/33809.mp3","categories":["وقت الصلاة"]},{"id":10555,"question":"يقول: بعض المصلين يتأخر عن تأدية صلاة المغرب إلى حين أعتقد أن الوقت قد خرج بم تنصحونني وتنصحون المستمعين حيال صلاة المغرب بالذات جزاكم الله خيراً؟","title":"وقت صلاة المغرب","answer":"الجواب: صلاة المغرب وقتها معلوم بينه النبي ﷺ وهو ما بين غروب الشمس إلى غروب الشفق وهو الحمرة التي في جهة الغرب، هذا وقت المغرب وهو وقت لا بأس به طويل ما بين غروب الشمس إلى غروب الشفق الأحمر، في جهة الغرب.\nوالأفضل أن تصلى في أول الوقت هذا هو الأفضل كان النبي يصليها في أول الوقت عليه الصلاة والسلام، كان إذا أذن صلى الناس ركعتين ثم أمر بالإقامة عليه الصلاة والسلام، فليس بين الإقامة في المغرب وبين الأذان إلا شيء قليل، وهو ما يفعله المسلمون من صلاة الركعتين.\nوفي الحديث الصحيح قال: صلوا قبل المغرب، صلوا قبل المغرب -يعني: قبل الصلاة، يعني قبل الفريضة- ثم قال في الثالثة: لمن شاء فدل على أنه يصلى بين الأذان والإقامة، ولكن الأفضل عدم التطويل بل يقيم بعد مدة يسيرة بعد الأذان بمدة يسيرة عشر دقائق ثمان دقائق أو ما يشابه ذلك، ولو أخر نصف ساعة أو أكثر قبل غروب الشفق فلا حرج الصلاة صحيحة كله وقت، لكن الأفضل الصلاة في المساجد والمسلمون في البيوت المريض والنساء الأفضل كلهم التبكير اقتداءً بالنبي عليه الصلاة والسلام. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8724/وقت-صلاة-المغرب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_321/32104.mp3","categories":["وقت الصلاة"]},{"id":10616,"question":"هل ينتهي وقت صلاة العشاء بحلول منتصف الليل؟","title":"متى ينتهي وقت صلاة العشاء","answer":"الجواب: نعم، إذا انتصف الليل انتهى وقت العشاء بنص النبي عليه الصلاة والسلام، يبقى الضرورة، يبقى وقت الضرورة، كما بعد اصفرار الشمس في العصر، لو صلاها بعد نصف الليل تكون في الوقت، لكن مع الإثم، مع الإثم إذا أخرها عامدا،ً أما إذا كان ناسياً فلا شيء عليه.\nالمقدم: جزاكم الله خيراً، ووقت الضرورة يمتد إلى متى سماحة الشيخ؟\nالشيخ: إلى طلوع الفجر.\nالمقدم: إلى طلوع الفجر.\nالشيخ: نعم.\nالمقدم: إذاً من صلى في الواحدة ليلاً، أو في الثانية ليلاً يكون صلى في وقت الضرورة؟\nالشيخ: نعم كل ما كان بعد نصف الليل فهو وقت ضرورة، وليس له التأخير، لا يجوز له التأخير؛ لأن النبي عليه السلام قال: ووقت العشاء إلى نصف الليل ﷺ.\nالمقدم: جزاكم الله خيراً، ونفع بعلمكم.","link":"https://binbaz.org.sa/fatwas/8795/متى-ينتهي-وقت-صلاة-العشاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_327/32707.mp3","categories":["وقت الصلاة"]},{"id":10912,"question":"رسالة وصلت إلى البرنامج من إحدى الأخوات المستمعات تقول: أختكم في الله: سعاد أحمد، الأخت سعاد بعثت بما يقرب من أحد عشر سؤالًا في أحد أسئلتها تقول فيه: هل صحيح أنه لا تجوز الصلاة إلا بعد نصف ساعة من الأذان؟","title":"حكم الصلاة بعد الأذان مباشرة","answer":"الجواب:  ليس بصحيح، متى دخل الوقت جازت الصلاة ولو بعد دقائق قليلة، متى علم دخول الوقت زالت الشمس للظهر، صار ظل كل شيء مثله بعد فيء الزوال، ودخل العصر، غربت الشمس يصلي المغرب، غاب الشفق الأحمر من جهة المغرب يصلي العشاء، طلع الفجر يصلي الفجر، أما تحديد نصف ساعة، أو ثلث ساعة، أو ربع ساعة هذا لا دليل عليه، ولكن كونه يتأنى بعد الوقت قليلًا حتى يطمئن، ويتوثق من دخول الوقت، وإن كان إمامًا تأخر حتى يجتمع الناس، ويتلاحق الناس لا يعجل، يتأخر ربع ساعة، ثلث ساعة حتى يتلاحق الناس في المسجد هذا مشروع مأمور به، حتى لا يفوتهم الصلاة، كان النبي ﷺ يتأنى بعد الأذان، ولا يعجل -عليه الصلاة والسلام- فالسنة للمؤمن أن يلاحظ سنة النبي ﷺ في ذلك في الصلاة وغيرها. والمرأة كذلك لا تعجل لو تأخرت قليلًا حتى تتيقن الوقت؛ لأن بعض المؤذنين قد يبكر، بعض المؤذنين ليس عندهم الضبط المطلوب، قد تكون ساعته أيضًا متقدمة، فالتأخر ربع ساعة، ثلث ساعة بعد الأذان يكون فيه احتياط للرجل والمرأة جميعًا، للرجل الذي يصلي مفردًا كالمريض، وللإمام حتى يحضر الناس المسجد، وحتى يلحقوا الصلاة؛ لأن كثيرًا من الناس لا يقوم إلى الصلاة إلا بعد الأذان يقوم يتوضأ، ثم يأتي. فلا ينبغي للمؤمن أن يعجل، والمفرد الذي في بيته لمرضه لا يعجل، والمرأة كذلك لا تعجل للتأكد من دخول الوقت والحيطة لهذا الأمر، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9082/حكم-الصلاة-بعد-الاذان-مباشرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_360/36009.mp3","categories":["وقت الصلاة"]},{"id":10923,"question":"إذا استيقظ أحد من نومه وهو في حالة نعاس شديد، ووجد أنه لم يصل العشاء، هل يصلي وإن كان في حالة النعاس؟","title":"حكم تأدية صلاة العشاء حال النعاس الشديد","answer":"الجواب:  يلزمه، يلزمه أن يصلي، يعالج الموضوع، يلزمه أن يقوم قبل خروج الوقت، يلزمه أن يجاهد نفسه، يتوضأ، ويعتني بالسواك، ويفعل ما يعينه على محاربة النعاس حتى يصلي فريضته التي أوجب الله عليه، وليس له عذر أن ينام ويقول: أنا مشغول بالنعاس لا، يجب أن يحارب النعاس حتى يصلي الفريضة. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9100/حكم-تادية-صلاة-العشاء-حال-النعاس-الشديد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_361/36110.mp3","categories":["وقت الصلاة"]},{"id":10939,"question":"كم يمتد وقت المغرب بالساعة لو تكرمتم سماحة الشيخ من بعد الأذان؟","title":"وقت ابتداء المغرب وانتهائه","answer":"الجواب:  في الغالب أنها ساعة ونصف تقريبًا، ما بين غروب الشمس إلى غروب الشفق ساعة ونصف تقريبًا، أو نصف إلا خمس، والذي يعتمده الناس الآن واحدة ونصف من باب الاحتياط، واحدة ونصف يكون الشفق الأحمر قد غاب بالكلية، ودخل وقت العشاء، نعم. المقدم: إذًا وقت المغرب من الثانية عشرة حتى الواحدة والنصف إلا خمس دقائق؟ الشيخ: لا حتى الواحدة والنصف تقريبًا يعني، هذا يحتاج إلى العناية بالشفق في الصحراء، الذي يرقب الشفق، وينظره يستطيع أن يحدد بالدقائق، لكن المعتمد الآن على سبيل الاحتياط ساعة ونصف. المقدم: هذا بعد غروب الشفق؟ الجواب: من غروب الشمس إلى غروب الشفق ساعة ونصف، نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/9128/وقت-ابتداء-المغرب-وانتهاىه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_363/36312.mp3","categories":["وقت الصلاة"]},{"id":10952,"question":"يتطلب عملنا السفر في كثير من الأحيان، وفي إحدى المرات وعندما دخل أول وقت صلاة المغرب لم يكن معنا ماء لنتوضأ منه، وأقرب مدينة لنا تبعد مسافة أربعين كيلو مترًا حتى مخرج المدينة، ثم خمسة كيلو مترًا تقريبًا بعد المخرج، أي: أن الزمن الذي تستغرقه المسافة هو ساعة إلا ربع من بعد دخول الوقت، فهل نتيمم ونصلي؟ أم نذهب إلى المدينة ونتوضأ بالماء الذي لا شك في وجوده فيها؟","title":"حكم تأخير الصلاة لعدم وجود الماء","answer":"الجواب:  الأفضل أن تصلوا بالتيمم حتى تصلوا في الوقت والحمد لله، الله يقول سبحانه: فَلَمْ تَجِدُوا مَاءً فَتَيَمَّمُوا صَعِيدًا طَيِّبًا فَامْسَحُوا بِوُجُوهِكُمْ وَأَيْدِيكُمْ مِنْهُ [المائدة:6]، فالأفضل لكم أن تصلوا بالتيمم؛ لأن المسافة بعيدة، وإن أخرتم وصليتم في المدينة بالماء والوقت باق لا خطر في خروجه فلا بأس ... فإذا كان الوقت أول المغرب، وفي إمكانكم أن تدركوا الماء في المدينة قبل مجيء وقت العشاء، قبل غروب الشفق فلا حرج عليكم في التأخير، لكن الأفضل لكم أن لا تخاطروا، وأن تصلوا المغرب بالتيمم، ثم تصلوا العشاء مع الناس في البلد -إن شاء الله- وإن جمعتم فلا حرج أيضًا، أنتم مسافرون، إن جمعتم ما دمتم في السفر، وبقي عليكم من المسافة أربعون كيلو هذه مسافة طويلة، لكم أن تصلوا جمعًا بين المغرب والعشاء، ثم إذا دخلتم أنتم بالخيار، إن صليتم مع الناس العشاء نافلة فلا بأس، وإلا فقد أديتم الفريضة والحمد لله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9127/حكم-تاخير-الصلاة-لعدم-وجود-الماء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_363/36311.mp3","categories":["وقت الصلاة"]},{"id":10954,"question":"يتطلب عملنا السفر في كثير من الأحيان، وفي إحدى المرات وعندما دخل أول وقت صلاة المغرب لم يكن معنا ماء لنتوضأ منه، وأقرب مدينة لنا تبعد مسافة أربعين كيلو مترًا حتى مخرج المدينة، ثم خمسة كيلو مترًا تقريبًا بعد المخرج، أي: أن الزمن الذي تستغرقه المسافة هو ساعة إلا ربع من بعد دخول الوقت، فهل نتيمم ونصلي؟ أم نذهب إلى المدينة ونتوضأ بالماء الذي لا شك في وجوده فيها؟","title":"حكم تأخير الصلاة لعدم وجود الماء","answer":"الجواب:  الأفضل أن تصلوا بالتيمم حتى تصلوا في الوقت والحمد لله، الله يقول سبحانه: فَلَمْ تَجِدُوا مَاءً فَتَيَمَّمُوا صَعِيدًا طَيِّبًا فَامْسَحُوا بِوُجُوهِكُمْ وَأَيْدِيكُمْ مِنْهُ [المائدة:6]، فالأفضل لكم أن تصلوا بالتيمم؛ لأن المسافة بعيدة، وإن أخرتم وصليتم في المدينة بالماء والوقت باق لا خطر في خروجه فلا بأس ... فإذا كان الوقت أول المغرب، وفي إمكانكم أن تدركوا الماء في المدينة قبل مجيء وقت العشاء، قبل غروب الشفق فلا حرج عليكم في التأخير، لكن الأفضل لكم أن لا تخاطروا، وأن تصلوا المغرب بالتيمم، ثم تصلوا العشاء مع الناس في البلد -إن شاء الله- وإن جمعتم فلا حرج أيضًا، أنتم مسافرون، إن جمعتم ما دمتم في السفر، وبقي عليكم من المسافة أربعون كيلو هذه مسافة طويلة، لكم أن تصلوا جمعًا بين المغرب والعشاء، ثم إذا دخلتم أنتم بالخيار، إن صليتم مع الناس العشاء نافلة فلا بأس، وإلا فقد أديتم الفريضة والحمد لله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9127/حكم-تاخير-الصلاة-لعدم-وجود-الماء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_363/36311.mp3","categories":["وقت الصلاة"]},{"id":11135,"question":"يقول: هل يجوز تأخير الصلاة إلى آخر وقتها للخوف، أو للبحث عن الماء، أو لطلب حاجة ضرورية قد تنقضي في آخر الوقت جزاكم الله خيرًا؟","title":"حكم تأخير الصلاة إلى آخر وقتها للضرورة","answer":"الجواب:  يجوز لكن لا يفوتها، يجوز أن يؤخرها إلى آخر الوقت حتى يصلي في آخر الوقت، لطلب الماء، أو لشغل مهم يخشى فوته.  وأما إذا استطاع أن يصليها في أول وقتها فهو الأفضل، وإذا كان هناك جماعة وجب عليه أن يصلي في الجماعة مع المسلمين في بيوت الله  في المساجد، أما إذا كان وحده كالمريض أو في السفر ما عنده أحد وشغل عن ذلك بشيء مهم، فصلاتها في آخر وقتها لا حرج فيه، لكن يجب أن يحذر عن تأخيرها عن الوقت، فهي جائزة في أوله وفي وسطه وفي آخره، لكن فعلها في أول الوقت أفضل إلا في شدة الحر، إذا اشتد الحر شرع تأخير الظهر حتى يبرد، وهكذا العشاء إذا تأخر جماعة شرع للإمام أن يتأخر حتى يجتمعوا كما كان النبي يفعل -عليه الصلاة والسلام- نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9308/حكم-تاخير-الصلاة-الى-اخر-وقتها-للضرورة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_369/36908.mp3","categories":["وقت الصلاة"]},{"id":11222,"question":"نعود مع مطلع هذه الحلقة إلى رسالة وصلت إلى البرنامج من مكة المكرمة، باعثتها إحدى الأخوات المستمعات رمزت إلى اسمها بالحروف (أ. ع. ص) أختنا عرضنا لها قضية في حلقة مضت، وفي هذه الحلقة تسأل سماحتكم وتقول: بالنسبة للمرأة في يوم الجمعة، هل يجوز لها أن تصلي الظهر قبل أن تقام الخطبة في المسجد، وجهوها جزاكم الله خيرًا؟","title":"هل يجوز للمرأة أن تصلي الظهر قبل خطبة الجمعة؟","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه. أما بعد. فإن المرأة عليها أن تصلي الظهر في الوقت بعد الزوال، سواء كان الخطيب قد خطب أم لم يخطب، ليس لها تعلق بالجمعة، عليها أن تتحرى الوقت فإذا زالت الشمس ودخل وقت الظهر تصلي، سواء كان الخطيب خطب للجمعة أم لم يخطب، لكن عليها التثبت وعدم العجلة حتى تعلم أن الوقت دخل، وأن الشمس قد زالت ثم تصلي الظهر بعد ذلك، وإن صلت مع الناس جمعة أجزأتها الجمعة، إن صلت مع الناس الجمعة فالحمد لله، تكفيها الجمعة. نعم. المقدم: جزاكم الله خيرًا وأحسن إليكم، هل تنصحونها بمتابعة التقويم سماحة الشيخ حتى تكون متيقنة من الزوال؟ الشيخ: التقويم ينفع، يعين على ذلك، التقويم، مراجعة التقويم يعين على ذلك، لكن لا تعجل، بعد التقويم بربع ساعة، ثلث ساعة، حتى تحتاط لدينها، نعم. المقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9414/هل-يجوز-للمراة-ان-تصلي-الظهر-قبل-خطبة-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_373/37313.mp3","categories":["صلاة الجمعة","وقت الصلاة"]},{"id":11227,"question":"نعود مع مطلع هذه الحلقة إلى رسالة وصلت إلى البرنامج من مكة المكرمة، باعثتها إحدى الأخوات المستمعات رمزت إلى اسمها بالحروف (أ. ع. ص) أختنا عرضنا لها قضية في حلقة مضت، وفي هذه الحلقة تسأل سماحتكم وتقول: بالنسبة للمرأة في يوم الجمعة، هل يجوز لها أن تصلي الظهر قبل أن تقام الخطبة في المسجد، وجهوها جزاكم الله خيرًا؟","title":"هل يجوز للمرأة أن تصلي الظهر قبل خطبة الجمعة؟","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه. أما بعد. فإن المرأة عليها أن تصلي الظهر في الوقت بعد الزوال، سواء كان الخطيب قد خطب أم لم يخطب، ليس لها تعلق بالجمعة، عليها أن تتحرى الوقت فإذا زالت الشمس ودخل وقت الظهر تصلي، سواء كان الخطيب خطب للجمعة أم لم يخطب، لكن عليها التثبت وعدم العجلة حتى تعلم أن الوقت دخل، وأن الشمس قد زالت ثم تصلي الظهر بعد ذلك، وإن صلت مع الناس جمعة أجزأتها الجمعة، إن صلت مع الناس الجمعة فالحمد لله، تكفيها الجمعة. نعم. المقدم: جزاكم الله خيرًا وأحسن إليكم، هل تنصحونها بمتابعة التقويم سماحة الشيخ حتى تكون متيقنة من الزوال؟ الشيخ: التقويم ينفع، يعين على ذلك، التقويم، مراجعة التقويم يعين على ذلك، لكن لا تعجل، بعد التقويم بربع ساعة، ثلث ساعة، حتى تحتاط لدينها، نعم. المقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9414/هل-يجوز-للمراة-ان-تصلي-الظهر-قبل-خطبة-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_373/37313.mp3","categories":["صلاة الجمعة","وقت الصلاة"]},{"id":11300,"question":"بعد هذا رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين يقول: هل علي إثم في تأخير صلاة العشاء بدون عذر ولكنني أرجو من الله العلي القدير الثواب الأكبر؟ جزاكم الله خيرًا. الشيخ: أعد. المقدم: هل علي إثم في تأخير صلاة العشاء بدون عذر، ولكنني أرجو من الله العلي القدير الثواب الأكبر؟ جزاكم الله خيرًا.","title":"حكم تأخير صلاة العشاء ابتغاء الثواب الجزيل","answer":"الجواب:  إذا كنت صحيحًا فالواجب عليك أن تصلي مع الناس في المسجد، هذا هو الواجب عليك، يقول النبي ﷺ: من سمع النداء فلم يأت فلا صلاة له إلا من عذر فيجب عليك أن تصلي مع الناس ولا يجوز لك التأخير ولا الصلاة في البيت مطلقًا، أما إن كنت معذورًا مريضًا فلك أن تؤخر قبل نصف الليل ، لا تؤخر عن نصف الليل .... الليل أو ما يقارب هذا لا بأس، وهذا أفضل إذا كان عليه مشقة، ولكن ليس لك أن تؤخر بعد نصف الليل هذا إذا كنت مريضًا معذورًا، أما القادر فإنه يصلي مع الناس ولا يجوز له التأخير. نعم. المقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9476/حكم-تاخير-صلاة-العشاء-ابتغاء-الثواب-الجزيل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_376/37608.mp3","categories":["صلاة الجماعة","وقت الصلاة"]},{"id":11334,"question":"السائل يقول في سؤاله الثاني: في مسجد قريتنا يؤذن لصلاة الفجر قبل وقتها بحوالي نصف ساعة تقريبًا بناًء على تقويمات بعض المنجمين كما وصفها بعض المؤلفين في الفقه، وفيما يكون الصبح مقدمًا على وقته بعشرين دقيقة على الأقل، ولا ينتظر الإمام بعد الأذان إلا بضع دقائق فتقام الصلاة قبل دخول وقتها، وهذا مخالف لسنة النبي ﷺ، كما أن هذه التقويمات تذكر سبع أوقات للصلاة لا خمسة كما هو مجمع عليه، وعنوان التقويم مواقيت الصلاة أي: الفريضة وفيها الشروق القبلة الزوال غير معروفة، وهذه الأوقات أيضًا ليست من السنة، ففيها وقتان زائدان، والظهر مسمى بغير اسمه، الفقرات ماذا يفعل المسلم الذي يريد أن يراعي وقت الفجر كما ثبت عن النبي ﷺ، هذه الفقرة الأولى يا سماحة الشيخ؟","title":"مواقيت الصلاة","answer":"الجواب:  الأوقات التي وقتها النبي ﷺ ودل عليها القرآن خمسة، يقول الله -جل وعلا-: أَقِمِ الصَّلاةَ لِدُلُوكِ الشَّمْسِ[الإسراء:78] دلوكها: زوالها، فيه الظهر والعصر إِلَى غَسَقِ اللَّيْلِ [الإسراء:78] فيه المغرب والعشاء وَقُرْآنَ الْفَجْرِ إِنَّ قُرْآنََ الْفَجْرِ كَانَ مَشْهُودًا [الإسراء:78] فيه صلاة الفجر. ثم وقتها النبي ﷺ بالأحاديث الصحيحة، وقت الفجر إذا طلع الفجر، طلع الفجر الصادق إلى أن تطلع الشمس، فإذا طلعت انتهى الوقت، ووقت الظهر حين يزول قائم الظهيرة، حين تزول الشمس عن كبد السماء إلى المغرب، يدخل وقت الظهر إلى أن يصير ظل كل شيء مثله، ثم يدخل وقت العصر إلى أن تصفر الشمس، ثم يبقى وقت ضرورة إلى أن تغيب الشمس، يدخل وقت المغرب إذا غابت الشمس ويستمر إلى أن يغيب الشفق الأحمر في جهة المغرب، فإذا غاب الشفق الأحمر دخل وقت العشاء إلى نصف الليل، ما بعد نصف الليل في الليل هذا وقت ضرورة، وهكذا بعد اصفرار الشمس في العصر وقت ضرورة. فالواجب الأخذ بما بينه النبي ﷺ والتمسك بذلك والسير عليه.","link":"https://binbaz.org.sa/fatwas/9516/مواقيت-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_292/29213.mp3","categories":["وقت الصلاة"]},{"id":11336,"question":"الفقرة الأخيرة يا سماحة الشيخ عبد العزيز يقول: بماذا توجهون أئمة المساجد حول هذه التقاويم وما ينبغي أن يفعلوه؟","title":"نصيحة أئمة المساجد بتحري أوقات الصلوات","answer":"الجواب: الواجب عليهم أن يتحروا الأوقات، وألا يأخذوا من التقاويم إلا ما عرفوا إتقانه وضبطه وأنه موافق للأوقات التي وقتها النبي ﷺ، وإلا فليجتهدوا في معرفتها بما بينه النبي ﷺ، وأما التقاويم التي لا تبالي ولا تعنى بالأوقات الشرعية فلا يلتفت إليها، لابد أن تكون التقاويم منطبقة على ما بينه الرسول ﷺ، فإذا عرف منها أنها قبل الصبح أو عرف أنه وقت الظهر قبل الزوال، أو المغرب قبل غروب الشمس لا يلتفت إليه، الناس ينظرون بأعينهم. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9518/نصيحة-اىمة-المساجد-بتحري-اوقات-الصلوات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_292/29215.mp3","categories":["وقت الصلاة"]},{"id":11383,"question":"بعث هذا المستمع شريف السيد طه رمضان من جمهورية مصر العربية بعث برسالة يسأل فيها ويقول: هل صلاة العشاء بعد الثانية عشرة مساءً للنساء هل هي جائزة، وهل تكره في الحادية عشرة والنصف مثلًا؟ جزاكم الله خيرًا.","title":"هل وقت صلاة العشاء إلى نصف الليل؟","answer":"الجواب:  صلاة العشاء إلى نصف الليل، يقول النبي ﷺ: وقت العشاء إلى نصف الليل فليس للمرأة أن تؤخرها إلى نصف الليل، والليل يختلف يطول ويقصر، فإذا كان الليل تسع ساعات فالنصف يكون الساعة الرابعة والنصف بالتوقيت الغروبي وإذا كان الليل اثنا عشر ساعة بالتوقيت الغروبي صار النصف الساعة السادسة، إذا بلغت السادسة هذا النصف، ليس للمريض ولا المرأة التأخير إلى نصف الليل، أما المعافى من الرجال يصلي مع الناس في المساجد، يلزمه أن يصلي مع الناس في المساجد، لكن لو صلى في البيت لمرضه والمرأة كذلك فإن عليهما أن يصليا قبل النصف صلاة العشاء، نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/9579/هل-وقت-صلاة-العشاء-الى-نصف-الليل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_379/37922.mp3","categories":["وقت الصلاة"]},{"id":11455,"question":"بعد هذا رسالة بعث بها المستمع جابر عبدالفراج يقول: إني أعمل في مزرعة، وأقوم بجميع الصلوات الخمس في مواعيدها إلا المغرب، فبعض الأيام تفوتني صلاة المغرب مع الجماعة بسبب ظرف عملي؛ لأنه لم ينته إلا قبل العشاء بنصف ساعة، يعني: بعدما أنتهي من صلاة المغرب يحين موعد أذان العشاء، فهل علي إثم في ذلك؟ جزاكم الله خيرًا.","title":"حكم تأخير صلاة المغرب بسبب ظروف العمل","answer":"الجواب:  نعم، إذا كنت في قربك جماعة؛ يلزمك أن تصلي مع الجماعة، أما إذا كنت وحدك، ما عندك أحد؛ فلا إثم عليك، لكن فاتك الأفضل، الأفضل أن تؤديها في أول الوقت، الأفضل أن تؤديها في أول الوقت، وإذا أديتها في آخر الوقت قبل غروب الشفق؛ فلا شيء عليك، والحمد لله، أما إذا وجدت الجماعة، مسجد حولك، أو جماعة؛ فإنه يجب عليك أن تصلي معهم، نعم.  المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9636/حكم-تاخير-صلاة-المغرب-بسبب-ظروف-العمل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_381/38110.mp3","categories":["صلاة الجماعة","وقت الصلاة"]},{"id":11493,"question":"رسالة بعث بها المستمع جبريل أحمد حسن من جمهورية مصر العربية يقول: ما الحكم في أناس لا يسمعون الأذان إلا من خلال الإذاعة، أو من خلال مواعيد الصلاة المدونة في النتائج التقويم، هل تقبل صلاتهم، أم لا؟ علمًا بأنهم يصلون على حسب ما يسمعون في الإذاعة، وحسب ما يرون في ورقة التقويم، هل يجوز هذا أو لا؟ وماذا يعملون في صلاة التراويح، في شهر رمضان؟ جزاكم الله خيرًا.","title":"الاعتماد في معرفة أوقات الصلاة على المذياع والتقويم","answer":"الجواب:  عليهم أن يتحروا الوقت إذا كانوا بعيدين عن المساجد، يتحروا الوقت، بالساعات، أو بالرؤية إن كانوا ينظرون طول الفجر، زوال الشمس وهكذا، يتحرون بالأسباب التي تمكنهم من الإذاعة، ومن التقاويم المضبوطة، أو من الرؤية بالبصر، أو سؤال الثقات عن الوقت حتى يؤدوا الصلاة على بصيرة بعد غلبة الظن، لا يعجلوا حتى يغلب الظن بأنه دخل الوقت، أما إن كان عندهم مساجد يسمعون المساجد؛ فعليهم أن يصلوا في المساجد، فعليهم أن يصلوا مع إخوانهم في مساجد الله، أما إذا كانوا بعيدين، في حارات ليس فيها مساجد، أو في البر؛ فإنهم يتحرون الوقت، ويصلون بعد غلبة الظن أنه دخل الوقت إما بالتقويم، أو بمشاهدة الوقت، أو بإخبار الثقات، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9682/الاعتماد-في-معرفة-اوقات-الصلاة-على-المذياع-والتقويم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_383/38315.mp3","categories":["وقت الصلاة"]},{"id":11497,"question":"رسالة بعث بها المستمع جبريل أحمد حسن من جمهورية مصر العربية يقول: ما الحكم في أناس لا يسمعون الأذان إلا من خلال الإذاعة، أو من خلال مواعيد الصلاة المدونة في النتائج التقويم، هل تقبل صلاتهم، أم لا؟ علمًا بأنهم يصلون على حسب ما يسمعون في الإذاعة، وحسب ما يرون في ورقة التقويم، هل يجوز هذا أو لا؟ وماذا يعملون في صلاة التراويح، في شهر رمضان؟ جزاكم الله خيرًا.","title":"الاعتماد في معرفة أوقات الصلاة على المذياع والتقويم","answer":"الجواب:  عليهم أن يتحروا الوقت إذا كانوا بعيدين عن المساجد، يتحروا الوقت، بالساعات، أو بالرؤية إن كانوا ينظرون طول الفجر، زوال الشمس وهكذا، يتحرون بالأسباب التي تمكنهم من الإذاعة، ومن التقاويم المضبوطة، أو من الرؤية بالبصر، أو سؤال الثقات عن الوقت حتى يؤدوا الصلاة على بصيرة بعد غلبة الظن، لا يعجلوا حتى يغلب الظن بأنه دخل الوقت، أما إن كان عندهم مساجد يسمعون المساجد؛ فعليهم أن يصلوا في المساجد، فعليهم أن يصلوا مع إخوانهم في مساجد الله، أما إذا كانوا بعيدين، في حارات ليس فيها مساجد، أو في البر؛ فإنهم يتحرون الوقت، ويصلون بعد غلبة الظن أنه دخل الوقت إما بالتقويم، أو بمشاهدة الوقت، أو بإخبار الثقات، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9682/الاعتماد-في-معرفة-اوقات-الصلاة-على-المذياع-والتقويم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_383/38315.mp3","categories":["وقت الصلاة"]},{"id":11567,"question":"من الجمهورية العربية السورية المستمع محمد علي يقول: أنا أحيانًا أصلي صلاة الفجر قبل طلوع الشمس بخمس أو عشر دقائق، هل صلاتي والحال ما ذكر مقبولة؟","title":"حكم تأدية صلاة الفجر قبل طلوع الشمس بدقائق","answer":"الجواب:  نعم، إذا أديتها قبل طلوع الشمس؛ صحت، ولكن لا يجوز لك التأخير، بل يجب أن تصلي مع الجماعة في المساجد في بيوت الله -جل وعلا- يقول النبي ﷺ: من سمع النداء فلم يأت؛ فلا صلاة له إلا من عذر وقد سأله رجل أعمى فقال: يا رسول الله ليس لي قائد يقودني إلى المسجد، فهل لي من رخصة أن أصلي في بيتي؟ فقال له -عليه الصلاة والسلام-: هل تسمع النداء بالصلاة؟ قال: نعم، قال: فأجب فأمر هذا الأعمى أن يجيب إلى المساجد وهو أعمى، فكيف بالبصير؟! فالواجب عليك أن تستيقظ قبل وقت الصلاة حتى تتأهب، وتصلي مع الجماعة في مساجد الله، وإذا تأخرت، ولم تحضر صلاة الجماعة؛ وجب عليك أن تصلي في الوقت، وأن تبادر بها قبل طلوع الشمس، وأن تبتعد عن الخطر، لا تؤخرها إلى قرب طلوع الشمس؛ لئلا تطلع الشمس عليك، وعليك التوبة إلى الله من تأخيرك، ومن عدم الصلاة في الجماعة، عليك التوبة إلى الله، والندم وعدم العودة إلى ذلك، وأن تجاهد نفسك جهادًا كبيرًا حتى تصلي مع الجماعة في وقت الصلاة، الظهر والعصر والمغرب والعشاء والفجر كلها. الرجل يصلي مع المسلمين في المساجد، ولا يجوز له أن يتشبه بالمنافقين في أدائها في البيت، نسأل الله للجميع التوفيق. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9750/حكم-تادية-صلاة-الفجر-قبل-طلوع-الشمس-بدقاىق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_297/29716.mp3","categories":["وقت الصلاة"]},{"id":11632,"question":"يقول: إنني أنام أحيانًا عن صلاة الفجر، وهذا المستمع محمد مرزوق المصري، يقول: إنني أنام أحيانًا عن صلاة الفجر، ولا أقضيها إلا بعد طلوع الشمس بسبب الإرهاق والتعب مع أنني أضع المنبه على الوقت، وعلى وقت الأذان، ولكني لم أستفد منه، فهل علي إثم؟ أفيدوني جزاكم الله خيرًا.","title":"حكم تأخير صلاة الفجر إلى بعد الشروق بسبب الإرهاق","answer":"الجواب:  إذا كنت مغلوبًا على أمرك، عاجزًا؛ فليس عليك شيء؛ لأن الله سبحانه يقول: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] أما إذا كنت متساهلًا تصيف في الليل، فوضع الساعة ما يكفي؛لأنك إذا سقطت مجهودًا ضعيفًا ما تسمع. فالواجب عليك اتخاذ الأسباب التي تعينك على القيام بالتبكير بالنوم، ووضع الساعة على وقت الفجر، أو تكليف من يوقظك إن كان عندك أهل يوقظونك، يجب عليك الأخذ بالأسباب، أما إذا فعلت الأسباب الممكنة، واجتهدت وغلبت فلا حرج لا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا وُسْعَهَا [البقرة:286] أما إذا تأخرت، ولا نمت إلا في آخر الليل؛ هذا غلط منك، أنت آثم بهذا، نسأل الله العافية نعم.  المقدم: اللهم آمين، جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9824/حكم-تاخير-صلاة-الفجر-الى-بعد-الشروق-بسبب-الارهاق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_389/38911.mp3","categories":["وقت الصلاة"]},{"id":11650,"question":"ما حكم صلاة العشاء الأخير قبل الفجر بساعة، أو ساعتين؟","title":"حكم تأخير صلاة العشاء إلى قبيل الفجر","answer":"الجواب:  العشاء نهاية وقتها النصف، ما يجوز تأخيرها إلى نصف الليل، يقول النبي ﷺ: وقت العشاء إلى نصف الليل فليس للناس أن يؤخروها بعد النصف، فإذا أخرها أثم، وهي في الوقت ما لم يطلع الفجر، وقت ضرورة، مثل لو أخر العصر إلى أن تصفر الشمس؛ حرم عليه، ولكنها في الوقت إذا صلاها بعد الاصفرار هي في الوقت حتى تغرب الشمس، لكن لا يجوز أن تؤخر العصر إلى أن تصفر الشمس، ولا يجوز أن تؤخر العشاء إلى نصف الليل، نعم. \nالمقدم: جزاكم الله خيراً وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9821/حكم-تاخير-صلاة-العشاء-الى-قبيل-الفجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_389/38908.mp3","categories":["وقت الصلاة"]},{"id":11834,"question":"من الرياض بعث بها المستمع (فهد . ف) يسأل ويقول: من وضع الساعة المنبهة لصلاة الفجر، وأوصى أهله فلم يُصلِّ إلا متأخرًا؛ لأن النوم غلب عليه، فما حكم ذلك، وما حكمه إذا تكرر ذلك منه بكثرة؟","title":"حكم من لا يصلي الفجر إلا متأخراً","answer":"الجواب: إذا كان ذلك قهرًا عليه، ولم يتسبب في ذلك؛ فلا حرج عليه، لقول الله سبحانه: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] لا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا وُسْعَهَا [البقرة:286]، أما إذا كان هو المتسبب، يصيف، ما يصير إلا مصيفًا، ولو وضع الساعة، ولو كلفهم؛ فهو غير معذور؛ لأنه هو المتسبب، أما إذا سار من المسجد بعد صلاة العشاء، ولم يستطع القيام لأسباب منعته، مرض، أو ثقل نوم مع وجود الأسباب من الساعة والموقظين، والله يعلم أنه صادق في ذلك؛ فلا حرج عليه، أما التحيل فلا يجوز، كونه يضع الساعة، ويوصيهم، ويتأخر، ولا ينام إلا مصيفًا، ما يستطيع يقوم، فهذه حيلة لا تجوز ولا تنفعه. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10010/حكم-من-لا-يصلي-الفجر-الا-متاخرا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_395/39513.mp3","categories":["وقت الصلاة"]},{"id":11857,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من المملكة الأردنية الهاشمية الكرك، باعثة الرسالة إحدى الأخوات تقول: أختكم في الله أمل، أختنا لها جمع من الأسئلة في أحدها تقول: هل يجوز تأخير الصلاة عند الشعور بالتعب الشديد حتى أرتاح لأتمكن من إتقان الصلاة، وهل يجوز إعادة الصلاة عند السرحان الكثير فيها، وعدم التركيز؟ جزاكم الله خيرًا.","title":"حكم تأخير الصلاة عند المشقة والطمأنينة فيها","answer":"الجواب:  بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد: فالمشروع للمؤمن أن يأتي الصلاة بقلب حاضر خاشع، وأن يقبل عليها حتى يؤديها في غاية العناية، والإقبال عليها والإخلاص لله، والخشوع فيها، كما قال الله سبحانه: قَدْ أَفْلَحَ الْمُؤْمِنُونَ ۝ الَّذِينَ هُمْ فِي صَلاتِهِمْ خَاشِعُونَ [المؤمنون:1-2]، وفي الحديث الصحيح يقول النبي ﷺ: أسوأ الناس سرقة الذي يسرق صلاته، قيل: يا رسول الله! كيف يسرق صلاته؟ قال: لا يتم ركوعها، ولا سجودها. فالواجب على المؤمن والمؤمنة العناية بالصلاة، وأن يكملها، ويتم ركوعها وسجودها. لكن إذا كان في أول الوقت عنده تعب؛ فإنه لا بأس أن يستريح، بل الأفضل له أن يستريح، ولو صلاها في أثناء الوقت، لأنه إذا صلاها في أثناء الوقت، ولو في آخره مع الراحة والطمأنينة والخشوع؛ كان أفضل من صلاتها في غير خشوع ولا طمأنينة، لكن لا يؤجلها إلى خروج الوقت، لابد أن تفعل في الوقت، فالتأخير إلى نصف الوقت، أو آخر الوقت للحاجة الشرعية من التعب، أو شدة المرض، أو نحو ذلك لا بأس بذلك، والحمد لله. لكن يعتني بإكمالها وإتمامها والطمأنينة فيها في أي وقت فعلها، لابد من الطمأنينة، الطمأنينة ركن فيها لابد. أما كمال الخشوع، كمال العناية هذا أفضل، ولكن الطمأنينة حيث يركع مطمئنًا يسجد مطمئنًا، يجلس بين السجدتين مطمئنًا، يعتدل بعد الركوع مطمئنًا؛ هذا لابد منه، كما أمر النبي ﷺ المسيء في صلاته أن يعيد لما أخل بهذه الطمأنينة. وسمى النبي ﷺ من أخل بهذا سارقًا، قال: أسوأ الناس سرقة الذي يسرق صلاته قيل: يا رسول الله! كيف يسرق صلاته؟ قال: لا يتم ركوعها ولا سجودها. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10038/حكم-تاخير-الصلاة-عند-المشقة-والطمانينة-فيها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_397/39701.mp3","categories":["وقت الصلاة"]},{"id":11926,"question":"رسالة بعثت بها إحدى الأخوات المستمعات تقول: يقول البعض: إن تأخير صلاة العشاء أفضل، فهل هذا القول صحيح؟ جزاكم الله خيرًا.","title":"حكم تأخير صلاة العشاء إلى آخر وقتها","answer":"الجواب:  نعم تأخير صلاة العشاء أفضل إلى ثلث الليل إذا تيسر ذلك، فإن لم يتيسر لخوف النوم، أو مشاغل تحدث؛ لم يؤخرها، بل صلاها في أول الوقت، وهكذا الرجال كان النبي ﷺ إذا رآهم اجتمعوا في العشاء؛ عجلها، وإذا رآهم تأخروا؛ أخرها -عليه الصلاة والسلام- وصلاها ذات يوم، وقد مضى ثلث الليل فقال: إنه لوقتها لولا أن أشق على أمتي عليه الصلاة والسلام. فالأفضل مراعاة حال المأمومين في حق الرجال، فإذا اجتمعوا؛ صلى بهم، ولو كان أول الوقت، وإذا تأخروا؛ أخر، أما المرأة والمريض الذي في البيت؛ فإن الأفضل له التأخير، الأفضل تأخير صلاة العشاء إلا إذا كان يخشى أن ينام، أو يخشى من مشاغل أخرى؛ فإنه يقدمها، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10110/حكم-تاخير-صلاة-العشاء-الى-اخر-وقتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_427/42703.mp3","categories":["وقت الصلاة"]},{"id":12113,"question":"أيضاً تقول سماحة الشيخ: إنني في بعض الأيام أكون متعبة كثيرًا، فأنام، ولا أقوم لصلاة العشاء إلا بعد منتصف الليل، كيف توجهونني؟ جزاكم الله خيرًا.","title":"حكم تأخير المرأة صلاة العشاء حتى بعد منتصف الليل","answer":"الجواب:  الواجب عليك، وعلى غيرك أداء الصلاة قبل نصف الليل، وإذا كنت متعبة بادري بها في أول وقتها، إذا غاب الشفق، يعني: إذا أذن العشاء؛ بكري بالصلاة، ونامي، والحمد لله، أما التأخير حتى يفوت الوقت؛ فلا يجوز لا للمريض، ولا للصحيح، الواجب أن تصلى في الوقت، ووقتها إلى نصف الليل، فإذا كان الليل عشر ساعات، إذا مضى خمس من الليل؛ انتهى الوقت، لا يجوز التأخير بعد الخمس، وإذا كان الليل اثنا عشر ينتهي الوقت في الساعة السادسة، بعد غروب الشمس. فالمقصود: أنه لا يجوز للرجل ولا للمرأة تأخير الصلاة صلاة العشاء إلى بعد نصف الليل، ولو كان مريضًا، يلزم أن يقدمها قبل نصف الليل لقوله ﷺ: وقت العشاء إلى نصف الليل عليه الصلاة والسلام، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10298/حكم-تاخير-المراة-صلاة-العشاء-حتى-بعد-منتصف-الليل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_437/43716.mp3","categories":["وقت الصلاة"]},{"id":12153,"question":"تسأل سماحتكم عن والدها، فتقول: إنه يصلي قبل الأذان، فما هو توجيهكم؟","title":"حكم الصلاة قبل الأذان","answer":"الجواب: إذا كان يعلم أن المؤذن تأخر عن الأذان، وأن الوقت دخل، وهو معذور مريض، ما يستطيع أن يذهب إلى المسجد له أن يصلي، أما أن يصلي هكذا من دون نظر لا ما يجوز إلا بعد الأذان. لكن لو كان إنسان في محل المؤذن يصيف، ويعرف أنه تأخر عن الوقت، وصلى قبل الأذان؛ لا بأس؛ لأن الإنسان يجب عليه أن يعرف الأوقات، ويتأمل، لا يعجل، فإذا كان يعرف الأوقات وصاحب الأذان تأخر في بعض القضايا، أو في بعض المساجد تأخر، وصلى قبل أذانه؛ لأنه عرف أن الوقت دخل، أو لأن المؤذن قد أذن سواه.  فالحاصل: أنه إذا عرف الوقت، وأن المؤذن تأخر، وصلى هو؛ لأنه مريض، أو لأنها امرأة تعرف الوقت؛ فلا بأس، لكن الواجب الصبر، وعدم العجلة؛ حتى يعرف الوقت، أو حتى يؤذن المؤذنون؛ لأنهم في الغالب على الوقت، يؤذنون في أول الوقت، فلا حاجة إلى العجلة، يصبر حتى يؤذن المؤذن، لكن لو فرضنا أن إنسانًا في محلٍ تأخر المؤذن، والوقت معروف أنه دخل، وصلى قبل الأذان؛ فلا بأس. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10338/حكم-الصلاة-قبل-الاذان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_441/44103.mp3","categories":["وقت الصلاة"]},{"id":12201,"question":"وننتقل إلى رسالة أخرى من المستمع: ناظم ظاهر عيال من العراق، أخونا ناظم يقول: إني طالب في المرحلة الثانوية، والدوام المدرسي يكون كالآتي: الأيام الثلاثة الأولى من الأسبوع في الساعة الثانية عشرة والنصف ظهرًا، أما الأيام الثلاثة الأخرى فيكون في الساعة الثامنة صباحًا، لذلك أجد صعوبة في أداء صلاة العصر، فإذا جمعتها مع صلاة الظهر فإنني أتأخر عن الدوام، وإذا تأخرت لا يسمح لي بالدخول، علمًا أن وصولي للبيت يكون في الساعة الخامسة عصرًا، فهل يجوز إقامة صلاة العصر في هذا الوقت، أي: في الساعة الخامسة، وهل يجوز جمعها مع صلاة المغرب؟","title":"حكم تقديم أو تأخير الصلاة عن وقتها بسبب الدراسة","answer":"الجواب:  الواجب عليك أن تصلي الصلاة في وقتها ولو في الدوام، وليس لك أن تؤخرها عن وقتها، فتصلي الظهر في وقتها وأنت في العمل مع إخوانك إن كان معك إخوان طيبين تصلي أنت وإياهم، وهكذا العصر تصليها في وقتها، وليس لك أن تؤخرها. فإذا كان من معك يمنعونك من الصلاة؛ فتصليها بعد انتهاء العمل إذا كان الوقت باقيًا، إن كان الوقت باقيًا لم تصفر الشمس؛ فلك أن تؤخر. أما إذا كان لا، لا تخرج إلا بعد أن تصفر الشمس؛ فليس لك أن تؤخر، وعليك أن تصلي في الوقت، وليس لك طاعتهم في ذلك، ليس لك أن تطيع رؤساءك في ذلك، ولو بطلت العمل، ولو تركت الدراسة، عليك أن تصلي الصلاة في وقتها الظهر والعصر جميعًا ولو أفضى ذلك إلى ترك الدراسة بالكلية، أما إذا كان في الإمكان أن تصلي الظهر قبل الدخول، قبل الدوام في وقتها، ثم تصلي العصر في وقتها بعد الدوام؛ لأنك تخرج منه، والوقت واسع؛ فلا بأس بذلك، ولا حرج، لكن ليس لك أن تؤخرها يعني: العصر إلى أن تصفر الشمس، وليس لك أن تقدم الظهر قبل وقتها، وليس لك أن تجمع بينهما، بل كل صلاة في وقتها؛ لأن هذا ما هو محل جمع، ليس بمرض، ولا سفر، وإنما شغل عارض، وهو الدراسة؛ فلا ينبغي أن يكون عذرًا في الجمع، ولكن تصلي كل صلاة في وقتها، فإذا لم تقدر على ذلك، ومنعوك؛ فلا حاجة إلى هذا العمل، يلزمك ترك هذا العمل؛ حفظًا لدينك، وحرصًا على سلامة دينك، والله المستعان، نعم. المقدم: الله المستعان. سماحة الشيخ، هل من دعوة كريمة هينة لينة إلى إخواننا في العالم الإسلامي كيما يهتموا بأوقات الصلوات، ولاسيما للطلبة والطالبات؟ الشيخ: نعم نعم نوصي جميع المسلمين في كل مكان أن يتقوا الله في المسلمين، وأن يتقوا الله في العمال، وأن يتقوا الله في الطلبة والطالبات؛ حتى لا يضيعوا عليهم أوقات صلواتهم، بل يجب عليهم أن يمكنوهم من الصلاة، العامل يمكن، والطالب يمكن، والطالبة كذلك، الواجب على جميع المسلمين في كل مكان أن يتقوا الله  وأن يمكنوا عمالهم وطلبتهم وطالباتهم، أن يمكنوهم من الصلاة في وقتها ظهرًا وعصرًا، وهكذا لو كان الدرس في الليل في المغرب والعشاء. الواجب على الجميع أن يعينوا على الخير والله يقول سبحانه: وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَى [المائدة:2] ويقول -جل وعلا-: وَالْعَصْرِ ۝ إِنَّ الإِنسَانَ لَفِي خُسْرٍ ۝ إِلَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ وَتَوَاصَوْا بِالْحَقِّ وَتَوَاصَوْا بِالصَّبْرِ [العصر:1-3]. ولا يجوز للمسلمين أن يساعدوا على ترك الصلاة، أو على إضاعتها في أوقاتها، هذا حرام على الجميع، على الرؤساء والمرؤوسين جميعًا، بل يجب على الرؤساء والمرؤوسين من مديرين ووكلاء ومدرسين يجب عليهم جميعًا أن يتعاونوا على تسهيل أداء العمال والطلبة والطالبات الصلاة في وقتها جماعة في حق الرجال، وأما النساء فلا حاجة إلى الجماعة، تصلي كل واحدة في وقتها، وفي محلها، والحمد لله، لا تجب عليهن الجماعة، أما الرجال فالواجب أن يسهل لهم أمر الصلاة، وأن تكون جماعةً، هذا هو الواجب على الجميع، نسأل الله للجميع الهداية والتوفيق. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10387/حكم-تقديم-او-تاخير-الصلاة-عن-وقتها-بسبب-الدراسة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_444/44408.mp3","categories":["وقت الصلاة"]},{"id":12272,"question":"سؤال آخر يقول: ما حكم من يؤخر صلاة الفجر ليصليها مع صلاة الظهر، علمًا بأنه يستيقظ عند أذان الفجر، هل صلاته مقبولة؟ أفيدونا جزاكم الله خيرًا.","title":"حكم تأخير صلاة الفجر إلى وقت الظهر","answer":"الجواب:  هذا منكر لا يجوز، الله يقول -جل وعلا-: إِنَّ الصَّلاةَ كَانَتْ عَلَى الْمُؤْمِنِينَ كِتَابًا مَوْقُوتًا [النساء:103] ويقول سبحانه: حَافِظُوا عَلَى الصَّلَوَاتِ وَالصَّلاةِ الْوُسْطَى [البقرة:238] يعني: في أوقاتها، والنبي ﷺ وقت الصلوات الخمس: الظهر والعصر والمغرب والعشاء والفجر في أوقاتها، فلا يجوز للمسلم أن يؤخرها عن وقتها، لا الفجر، ولا غيرها، يجب عليه أن يبادر بالصلاة في وقتها مع المسلمين في الجماعة في المساجد، والمرأة تصليها في البيت في وقتها، ولا يجوز تأخيرها إلى طلوع الشمس، فكيف بتأخيرها إلى الظهر؟! هذا منكر عظيم، وبعض أهل العلم يراه كافرًا بذلك، نسأل الله العافية. فالواجب التوبة إلى الله، والحذر، وأن يصليها في وقتها، ولا يؤخرها عن وقتها، نعم.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10472/حكم-تاخير-صلاة-الفجر-الى-وقت-الظهر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_450/45009.mp3","categories":["وقت الصلاة"]},{"id":12693,"question":"المستمع: أحمد بن يحيى القحطاني الناصري بعث يسأل ويقول: إن والدتي -يحفظها الله- كثيرًا ما تؤخر صلاة العشاء إلى ما بعد التاسعة والنصف، فإذا ناقشتها في ذلك قالت: إن وقت العشاء طويل، وهو لا يفوت -إن شاء الله- فما هو توجيه سماحتكم، جزاكم الله خيرًا؟","title":"حكم تأخير المرأة صلاة العشاء إلى آخر وقتها","answer":"الجواب:  لا حرج في تأخير صلاة العشاء إلى آخر وقتها في حق النساء، في حق المعذورين، كالمرضى الذين لا يحضرون الجماعة، بل تأخيرها أفضل، إلى ثلث الليل، وإلى ما يقارب نصف الليل؛ لأنه ﷺ: صلى بأصحابه ذات ليلة، وقد مضى ثلث الليل، ثم قال: إنه لوقتها لولا أن أشق على أمتي وكان -عليه الصلاة والسلام- في صلاة العشاء إذا رأى الناس اجتمعوا؛ عجل، وإذا رآهم أبطؤوا؛ أخرها. فالأفضل تأخيرها في حق النساء، والمرضى الذين لا يحضرون الجماعة، ومن أشبههم ممن له عذر في عدم حضور الجماعة، أما أهل المساجد فإنهم يصلون متى اجتمعوا، وإذا أخرها الإمام لانتظارهم حتى يجتمعوا؛ فذلك أفضل لفعله -عليه الصلاة والسلام- ومتى اجتمعوا؛ فإنه يعجلها، ولا يشق عليهم. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10903/حكم-تاخير-المراة-صلاة-العشاء-الى-اخر-وقتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_418/41803.mp3","categories":["وقت الصلاة"]},{"id":12699,"question":"من المستمع محمد صادق محمد عبدالراضي رسالة ضمنها سؤالًا واحدًا يقول: أنا أبعد عن المسجد، ولا أسمع الأذان، وأصلي بدون أن أسمع الأذان، هل ما أفعله صحيح؟","title":"وجوب تحري الوقت في الصلاة","answer":"الجواب:  لابد من التأكد من دخول الوقت، لابد أن تعرف الوقت، تتسمع بسماع الأذان، وإلا بالساعات، وإلا بالطرق الأخرى، تعرف بها الوقت، إذا كان المسجد بعيدًا عنك لا تسمعون الأذان، وأما إن كان المسجد قريبًا، يعني: تسمع الأذان؛ وجب عليك الصلاة في المسجد، لقول النبي ﷺ: من سمع النداء، فلم يأت؛ فلا صلاة له إلا من عذر قيل لابن عباس: ما هو العذر؟ قال: خوف، أو مرض. فالواجب على المؤمن أن يتحرى الأوقات، وأن يصلي في المساجد مع المسلمين، إلا إذا بعدت عنه، بحيث لا يسمع النداء بالصوت المعتاد؛ فإنه يجوز له أن يصلي في مكانه، وإن تجشم المشقة، وصبر، وصلى في المساجد؛ كان أفضل، وأعظم أجرًا. والاعتبار بالصوت المعتاد، بدون مكبر؛ لأن المكبر يبلغ مدًا طويلًا، ولكن من لا يعلم الوقت لأنه لا يسمع الأذان، لابد من التحري، وعدم العجلة؛ حتى يغلب على ظنه دخول الوقت بأي طريق تأكد بها ذلك، أو غلب على ظنه ذلك. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10909/وجوب-تحري-الوقت-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_459/45904.mp3","categories":["وقت الصلاة"]},{"id":12800,"question":"المستمع خضر محمود علي بعث برسالة ضمنها جمعًا من الأسئلة يقول: إذا صليت أحد الفروض قبل موعد الصلاة بما يقرب من عشر دقائق، وكان ذلك سهوًا مني، هل تسقط عني تلكم الصلاة، أم ما زالت في ذمتي؟","title":"حكم تأدية الصلاة قبل دخول الوقت","answer":"الجواب:  إذا صليتها قبل الوقت فهي باطلة، ولا تسقط عن ذمتك، فإذا صليت الظهر قبل الزوال، أو المغرب قبل غروب الشمس، أو الفجر قبل طلوع الفجر؛ فالصلاة باطلة، عليك أن تعيدها، ولا تبرأ الذمة إلا بإعادتها، ولا يجوز لك أن تصلي قبل الوقت أبدًا، بل أنت آثم، وعليك التوبة من ذلك، والله المستعان. نعم. المقدم: الله المستعان جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11014/حكم-تادية-الصلاة-قبل-دخول-الوقت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_462/46205.mp3","categories":["وقت الصلاة"]},{"id":12938,"question":"السائلة (ن. هـ. س. الشمري) حائل تقول: سمعت من بعض الناس أنهم يقولون: بأن صلاة العشاء تؤخر إلى الساعة العاشرة فقط، وينتهي وقت الصلاة، فهل هذا صحيح؟","title":"تحديد وقت انتهاء صلاة العشاء","answer":"الجواب:  صلاة العشاء وقتها إلى نصف الليل، والليل يختلف، يطول ويقصر الليل، فالواجب أن تقدم الصلاة قبل هذا -قبل النصف- لأن الرسول ﷺ يقول: وقت العشاء إلى نصف الليل فالواجب على الرجال والنساء أن يقدموا الصلاة قبل النصف، فالرجل يصلي في الجماعة في المساجد، والمرأة تلاحظ هذا حتى تصلي قبل النصف، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11154/تحديد-وقت-انتهاء-صلاة-العشاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_501/50113.mp3","categories":["وقت الصلاة"]},{"id":12987,"question":"من المستمع حماد عقاب المطيري من الأرطاوية رسالة وضمنها سؤالين. السؤال الأول: ما حكم تأخير صلاة العشاء عن وقتها، وهل ورد عن النبي ﷺ في تأخيرها حديث؟","title":"حكم تأخير صلاة العشاء عن أول وقتها","answer":"الجواب:  نعم، صلاها مرة متأخرًا وقال ﷺ: إنه لوقتها لولا أن أشق على أمتي وكان يستحب أن يؤخر العشاء بعض الشيء -عليه الصلاة والسلام- فوقتها إلى نصف الليل، فإذا اتفق أهل القرية، أو أهل المسجد على التأخير؛ فلا بأس إلى ثلث الليل، قبل نصف الليل، إذا اتفقوا؛ فلا بأس فهو أفضل، وإلا فالسنة أن يبكر بها حتى لا يشق على الناس، يؤخر بعض الشيء، ولكن لا يطول حتى لا يشق على الناس، كما كان النبي يفعل -عليه الصلاة والسلام- كان -عليه الصلاة والسلام- إذا رآهم اجتمعوا؛ عجل، وإذا رآهم أبطؤوا؛ أخرها، وأخرها في بعض الأوقات فقال : إنه لوقتها لولا أن أشق على أمتي وكان أخرها إلى ثلث الليل، وفي بعض الأحاديث إلى قرب شطر الليل. فالحاصل: أن الإمام لا يشق على الناس، بل يصلي بهم كالعادة، يبكر، لكن إذا كانوا يستحبون التأخير، واتفقوا معه على التأخير إلى ثلث الليل قبل نصف الليل؛ فلا بأس، فمهما تأخروا؛ فهو أفضل إذا تراضوا عليه، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11204/حكم-تاخير-صلاة-العشاء-عن-اول-وقتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_470/47013.mp3","categories":["وقت الصلاة"]},{"id":13135,"question":"الأخت سعاد (م. م) مدينة إب بعثت برسالة وضمنتها أربعة أسئلة، في أحد أسئلتها تقول: هل يجوز للمرأة التي تصلي في بيتها أن تصلي قبل إقامة الصلاة في الجامع، وأنا أصلي قبل الإقامة؛ وذلك لأن أكثر صلوات الفجر لم أصلها إلا قضاء، وسبب ذلك أني أسمع الأذان وأقوم، ولكن كثيرًا ما يغلبني النعاس، وأنام ولا أصحو إلا بعد زوال وقت الصلاة، وذلك لأني أنتظر مدة طويلة حتى يقيم الإمام، ولكني فضلت أن أسأل فأعمل بما أسمع منكم، جزاكم الله خيرًا؟","title":"هل تنتظر المرأة إقامة الصلاة من المسجد حتى تصلي؟","answer":"الجواب:  عليك أن تصلي إذا دخل الوقت، وليس عليك أن تنتظري الإمام، هذا لا أصل له، صلاة المرأة مستقلة، تصلي قبل الإمام، أو بعد الإمام، ليس لها تعلق بالإمام، فإذا دخل الوقت؛ فصلي ولا تنتظري الإمام، هذا شيء لا أصل له، صلاة المرأة مستقلة، غير مربوطة بإمام الرجال، فلا تنتظريه، بل صلي والحمد لله. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11379/هل-تنتظر-المراة-اقامة-الصلاة-من-المسجد-حتى-تصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_474/47413.mp3","categories":["وقت الصلاة"]},{"id":13158,"question":"من جمهورية مصر العربية جامعة القاهرة، رسالة وصلت إلى البرنامج من المستمع نسيم الظواهري، يقول في أحد أسئلته: كيف نحدد وقت الفجر، وكم بين الفجر والشروق حيث عندنا في مصر الوقت بين الفجر والشروق ما يقرب من ساعة ونصف، وقد قرأت في كتب الصحيح والتفسير: أن الفجر هو بياض النهار، وانتشار النور في الطرقات، أرجو أن تفيدوني حول هذه القضية، جزاكم الله خيرًا.","title":"بيان وقت صلاة الفجر","answer":"الجواب:  الفجر مثل ما أشرتم إليه هو: انشقاق الصبح، النبي ﷺ بين الفجر وأنه حين ينشق الفجر، ويعترض في الجو الشرقي هذا هو الفجر الصادق. وهناك فجر كاذب كالعمود، ثم يزول، ويأتي بعده الظلمة، هذا لا عبرة به، أما الفجر الصادق فهو الذي ينفسح جنوبًا وشمالًا في جهة الشرق، ويزداد نوره، هذا هو الصبح متى طلع هذا الفجر؛ فهذا هو الذي يفصل بين الخيط الأبيض من الخيط الأسود، هذا هو الخيط الأبيض الصبح. وهو ينتشر ويتسع ويزداد نوره حتى يتم ضوؤه، ويزول آثار الليل، وتزول آثار الليل، ويستمر إلى طلوع الشمس، والغالب -مثلما ذكرتم- أن ما بينهما ساعة ونصف تقريبًا حسب ما ذكر أهل الخبرة. وقد تنقص عن النصف قليلًا حسب ما ذكره بعض أهل الخبرة، فالأمر في هذا لا يتعلق به، يتعلق بطلوع الشمس، متى طلعت الشمس، وارتفعت؛ أبيحت الصلاة، وما دامت الشمس لم تطلع هو وقت الفجر، فلو صلاها قبل طلوع الشمس فهو في وقتها، لكن ليس له التأخير حتى يخاطر بها، ولكن يبادر بها، ويصليها بغلس، وإذا كان قادرًا؛ صلاها مع المسلمين في المساجد، والمرأة تصليها في البيت في أول الوقت، هذا هو الأفضل. فلو أخر حتى اتضح النهار، وزالت الظلمة؛ فلا حرج، لكن ليس له أن يؤخر إلى طلوع الشمس، إنما يؤخر إلى الإسفار كثيرًا لا حرج، ولكن الأفضل أن يصليها بغلس، هذا هو الأفضل أن يصليها بغلس من بعد اتضاح الفجر، وانتشاره، وبيانه، وعدم الشبهة. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11413/بيان-وقت-صلاة-الفجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_475/47502.mp3","categories":["وقت الصلاة"]},{"id":13359,"question":"فضيلة الشيخ! هذا السائل عبدالعزيز من الرياض يقول: كثير من الناس هداهم الله يذهبون في رمضان للمساجد البعيدة عن بيوتهم لأداء صلاة التراويح؛ طلبًا لحسن الصوت لبعض الأئمة، ولكن المشكلة يا سماحة الشيخ بأنهم يذهبون متأخرين جدًا، فنراهم قد تفوتهم صلاة العشاء، فيقضون جماعات في آخر المسجد، هل من كلمة لهؤلاء يا سماحة الشيخ؟","title":"توجيه لمن يقصد مسجدًا بعيدًا لأجل التراويح وتفوته العشاء","answer":"الجواب: نعم، نصيحتي للجميع أن يتقوا الله، وأن يحرصوا على أداء الفريضة، وإذا ذهب بعد الفريضة، أو مبكرًا حتى يدرك الفريضة إلى شخص آخر، يرى أن صوته أحسن، وأنه يخشع لقراءته، ويستفيد؛ فلا بأس، ولو كان بعيدًا عن بيته، لكن يحرص على أداء الفريضة، لا تفوته الفريضة، إما يصليها في المساجد القريبة، وإلا أن يبكر حتى يصلي مع ذاك الإمام الفريضة، ولا يعرض نفسه أن تفوته الفريضة؛ لأن الفريضة فرض عليه، والتراويح مستحبة، فلا يضيع الفرض من أجل المستحب. يجب أن يعتني بالفريضة حتى يؤديها مع إخوانه المسلمين، وإذا أحب أن يصلي مع شخص آخر؛ فليبكر، يذهب قبل العشاء حتى يدرك الفريضة معه، أو بعد العشاء إذا صلى الفريضة، ولا بأس. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11644/توجيه-لمن-يقصد-مسجدا-بعيدا-لاجل-التراويح-وتفوته-العشاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_524/52402.mp3","categories":["الآداب والأخلاق","نصائح وتوجيهات","وقت الصلاة"]},{"id":13529,"question":"يقول هذا السائل: أنا أعمل في مدرسة كمشرف، والدوام يستمر حتى انتهاء صلاة الظهر، ولا أستطيع الخروج من المدرسة لأداء الصلاة في الجماعة الأولى، فهل يجوز لي تأخير الصلاة إلى بعد انتهاء الدوام؟","title":"هل يجوز تأخير صلاة الظهر إلى نهاية الدوام؟","answer":"الجواب: الواجب عليك أن تصلي مع الجماعة في المسجد، أو في محلكم، إن كان أمكنك الخروج إلى المسجد؛ وجب عليكم جميعًا أن تصلوا في المسجد إذا كان المسجد قريبًا، تسمعون الأذان، وجب عليكم أن تصلوا في المسجد، فإن كان المسجد بعيدًا؛ وجب أن تصلوا جماعة في محل العمل، وليس لأحد منكم أن يصلي وحده؛ لأن الرسول ﷺ أمر بالجماعة، وقال: من سمع النداء فلم يأت؛ فلا صلاة له إلا من عذر قال له رجل أعمى: يا رسول الله! ليس لي قائد يقودني إلى المسجد، فهل لي من رخصة أن أصلي في بيتي؟ فقال: هل تسمع النداء بالصلاة؟ قال: نعم، قال: فأجب. فالواجب على المؤمن أن يصلي مع الجماعة إن أمكن في المسجد صلى في المسجد، وإن كان المسجد بعيدًا صلوا جماعة في محل عملهم، وليس لأحدهم أن يتخلف. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11860/هل-يجوز-تاخير-صلاة-الظهر-الى-نهاية-الدوام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_532/53205.mp3","categories":["وقت الصلاة"]},{"id":13954,"question":"من جدة الأخت أم محمد هضيان بعثت تسأل مجموعة من الأسئلة فتقول: أنا طالبة في المدرسة فهل يجوز تأخير صلاة الظهر إلى حين الرجوع إلى المنزل؟ علمًا بأن الساعة قد تكون الواحدة والنصف.","title":"حكم تأخير الصلاة لأجل وقت الدراسة","answer":"الجواب: لا حرج في ذلك إذا اشتغلت بالدراسة ولم يتيسر لها أداء الصلاة في أول الوقت لا حرج؛ لأن وقت الظهر بحمد الله متسع، فإذا كانت تصل إلى بيتها قبل انتهاء الوقت فلا بأس بذلك، وإن صلتها في أول الوقت فهو أفضل إذا تيسر ذلك. نعم.","link":"https://binbaz.org.sa/fatwas/12364/حكم-تاخير-الصلاة-لاجل-وقت-الدراسة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_604/60412.mp3","categories":["وقت الصلاة"]},{"id":14089,"question":"يقول: ألاحظ أن كثيرًا من الناس يحرص على وضع القرآن في السيارة، فهل توجهونهم بشيء؟","title":"توجيه لمن يضع المصحف في السيارة","answer":"الجواب: نعم، إذا كان وضع القرآن في السيارة للقراءة حتى يقرأ إذا تيسر له القراءة أو يقرأ من معه من الركاب، فهو مشكور يعينهم على طاعة الله وعلى قراءة كتاب الله، أما إذا كان عن اعتقاد أنه حرز وأنه ... القرآن حرز للسيارة من الانقلاب ومن الصدام هذا منكر لا يجوز ليس بحرز، ولكن إذا أراد بذلك أن يعين من ركب معه على القراءة، أو هو يقرأ إذا وقف للحاجة فلا بأس.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12518/توجيه-لمن-يضع-المصحف-في-السيارة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_484/48411.mp3","categories":["وقت الصلاة","نصائح وتوجيهات"]},{"id":14110,"question":"من سوريا هذه رسالة بعث بها مستمع من هناك يقول محمد سعيد أحمد من سوريا، يسأل في سؤالين:سؤاله الأول يقول: يؤذن الفجر عندنا قبل طلوع الشمس بساعة وأربعين دقيقة، ونصلي صلاة الفجر بعد الأذان بعشرين دقيقة تقريبًا، يعني قبل طلوع الشمس بساعة وعشرين دقيقة، هل صلاتنا موافقة للسنة؟","title":"حكم صلاة الفجر قبل طلوع الشمس بساعة وعشرين دقيقة","answer":"الجواب: نعم. الصلاة صحيحة إن شاء الله؛ لأن الغالب أن بين طلوع الشمس وبين طلوع الفجر نحو ساعة ونصف تقريبًا، لكن لو أخرتم وصليتم قبل الشمس بساعة أو ساعة وخمس دقائق يكون أحوط وأحسن، والأذان قبل طلوع الشمس بساعة وأربعين دقيقة فيه تبكير وأذان قبل الوقت، فلو أخر وأذن قبل الشمس بساعة ونصف تقريبًا يكون هذا أحوط لدخول الوقت، والمقصود أن المشروع للمؤمن أن يتأكد من الوقت وألا يعجل في صلاته حتى يتأكد من الوقت، فإذا كانت الصلاة قبل الوقت وقبل طلوع الشمس بساعة ونحوها كان هذا أحوط، ساعة وخمس ساعة وعشر تقريبًا يكون هذا أحوط لأداء الصلاة في وقتها؛ لأن الغالب أن بين طلوع الشمس وبين طلوع الفجر نحو ساعة ونصف أو ساعة ونصف إلا خمس دقائق أو ما يقارب هذا، فالمؤمن يحتاط لهذا الأمر ولا يعجل لا في الأذان ولا في الصلاة، فالتأخير أحوط. نعم، في مثل هذا. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12549/حكم-صلاة-الفجر-قبل-طلوع-الشمس-بساعة-وعشرين-دقيقة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_614/61412.mp3","categories":["وقت الصلاة"]},{"id":14237,"question":"أختنا تقول: أنا طالبة في الكلية ودائمًا لا نخرج منها إلا بعد الساعة الثانية وأكون منهكة وأحاول الصبر إلى أن تحين صلاة العصر، ثم المغرب وبعد ذلك أنام ولا أستيقظ إلا في الحادية عشرة ليلًا ثم أصلي العشاء، فهل علي إثم في تأخير صلاة العشاء إلى الحادي عشرة؟","title":"حكم النوم بعد المغرب وتأخير صلاة العشاء","answer":"الجواب: النوم بين المغرب والعشاء مكروه، كان النبي ﷺ يكره النوم قبلها والحديث بعدها، فينبغي الصبر حتى تصلي العشاء إذا غاب الشفق، ولكن لو أخرت العشاء وصليتيها قبل نصف الليل فلا بأس، فالمعول عليه نصف الليل لا بد أن تصليها قبل نصف الليل والليل يختلف، فلا بد أن تصلي العشاء قبل نصف الليل ولكن يكره لك النوم بين المغرب والعشاء إذا استطعت ذلك، وإذا استرحت بين العصر وبين المغرب، بين صلاة العصر وبين المغرب كان أولى من النوم بعد المغرب؛ لأن النوم بعد المغرب مكروه «كان النبي ﷺ يكره النوم قبلها والحديث بعدها» يعني بعد العشاء لكن لو استرحت ونمت بعد العصر، بعد صلاة العصر وقبل المغرب كان هذا أولى من النوم بعد المغرب حتى تصلي المغرب والعشاء في أوقاتهما. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12696/حكم-النوم-بعد-المغرب-وتاخير-صلاة-العشاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_617/61706.mp3","categories":["نصائح وتوجيهات","وقت الصلاة"]},{"id":14240,"question":"أختنا تقول: أنا طالبة في الكلية ودائمًا لا نخرج منها إلا بعد الساعة الثانية وأكون منهكة وأحاول الصبر إلى أن تحين صلاة العصر، ثم المغرب وبعد ذلك أنام ولا أستيقظ إلا في الحادية عشرة ليلًا ثم أصلي العشاء، فهل علي إثم في تأخير صلاة العشاء إلى الحادي عشرة؟","title":"حكم النوم بعد المغرب وتأخير صلاة العشاء","answer":"الجواب: النوم بين المغرب والعشاء مكروه، كان النبي ﷺ يكره النوم قبلها والحديث بعدها، فينبغي الصبر حتى تصلي العشاء إذا غاب الشفق، ولكن لو أخرت العشاء وصليتيها قبل نصف الليل فلا بأس، فالمعول عليه نصف الليل لا بد أن تصليها قبل نصف الليل والليل يختلف، فلا بد أن تصلي العشاء قبل نصف الليل ولكن يكره لك النوم بين المغرب والعشاء إذا استطعت ذلك، وإذا استرحت بين العصر وبين المغرب، بين صلاة العصر وبين المغرب كان أولى من النوم بعد المغرب؛ لأن النوم بعد المغرب مكروه «كان النبي ﷺ يكره النوم قبلها والحديث بعدها» يعني بعد العشاء لكن لو استرحت ونمت بعد العصر، بعد صلاة العصر وقبل المغرب كان هذا أولى من النوم بعد المغرب حتى تصلي المغرب والعشاء في أوقاتهما. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12696/حكم-النوم-بعد-المغرب-وتاخير-صلاة-العشاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_617/61706.mp3","categories":["نصائح وتوجيهات","وقت الصلاة"]},{"id":14467,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من تبوك، وباعثها المستمع مصطفى ياسين أحمد خليفة، سوداني مقيم في تبوك كما يقول في رسالته: له في هذه الرسالة سؤالان: السؤال الأول يقول: إذا صلى الإنسان مع المذياع إذا توافق الزمن بين المصلي والمكان الذي تنقل منه الصلاة، علمًا بأن المصلي في مكان بعيد، لا يوجد فيه ناس، فهل صلاته والحال ما ذكر تعتبر صحيحة؟","title":"حكم الصلاة بعد إعلان المذياع دخول الوقت","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد: فالواجب على كل مؤمن وعلى كل مؤمنة أن يتحرى الوقت، وأن يأخذ بالأسباب، فإذا تيقن الوقت، أو غلب على ظنه دخول الوقت بالأسباب التي يعتقدها صلى، سواء كان من طريق المذياع، أو غير المذياع، فإذا سمع الأذان من المذياع وهو في محل بعيد، والوقت واحد لا يتغير، والمذياع قد جرب عليه الصدق، وأنه يذيع الحقيقة، فهذا يغلب على الظن، ولا بأس أن يصلي، فإن كان يشك في ذلك، وليس عنده ما يغلب ظنه صدق المذياع، فإنه يأخذ بالطرق الأخرى، ينظر في الوقت يسأل أهل الخبرة إن كان الزوال هل زالت الشمس؟ إن كان العصر هل صار ظل كل شيء مثله؟ حتى يكون دخل الوقت، إن كان المغرب هل غابت الشمس؟ وإن كان العشاء هل غاب الشفق الأحمر؟ إن كان الفجر قد طلع الفجر ينظر، ويسأل أهل الثقة حتى يصلي على بصيرة، إما بيقين وإلا بغلبة ظن مبنية على أسس وعلى علامات. أما المذياع وحده فلا يكفي إذا كان ليس في ظنه ما يبرره، فإن المذياع قد يكون من أناس لا يوثق بهم، فإذا كان المذياع قد جرب عليه الصدق، وأنه يتحرى الوقت، وأنه يذيع الحقيقة، أو يذيع عن إنسان يتحرى الوقت، تسمع صوته أن هذا أذان الظهر، أو أذان المغرب، أو أذان العشاء، وهو موثوق تعرفه فلا بأس بذلك. الحاصل: أن المدار على الثقة، إما يقينًا وإما غلبة ظن، بالمذياع أو غيره، حتى لا تصلي إلا على بصيرة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12953/حكم-الصلاة-بعد-اعلان-المذياع-دخول-الوقت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_488/48809.mp3","categories":["وقت الصلاة"]},{"id":14533,"question":"رسالة وصلت إلى البرنامج من المستمع: عبدالرحمن محمد عباس، يقول: أنا طالب جامعي، وفي بعض الأحيان تفوتني صلاة الظهر بما فيها سنة رسول الله ﷺ، فهل يجوز أن أؤدي صلاة الظهر مع صلاة العصر وبدون السنة، أم أصلي صلاة الظهر بما فيها السنة مع صلاة العصر جمعًا؟","title":"حكم تأخير الظهر إلى العصر بعذر الدراسة","answer":"الجواب: لا يجوز لك الجمع، بل يجب عليك أن تصلي الظهر في وقتها، وليس لك تأخيرها إلى العصر، وليست الدراسة عذرًا في ذلك، بل يجب عليك أن تصلي الظهر في وقتها، ويشرع لك فعل السنة، وهي أربع قبل الظهر، وثنتين بعدها، كما كان النبي يفعل -عليه الصلاة والسلام- يصلي أربعًا قبل الظهر، وثنتين بعدها، وهذه نافلة، والمهم الفريضة. فالواجب عليك أن تصلي الفريضة في وقتها، وهي أربع في حق المقيم، وركعتين في حق المسافر، كما هو معلوم، وليس لك أن تؤخرها إلى العصر وأنت مقيم.  أما المسافر فلا بأس له التأخير والمريض كذلك، أما الاحتجاج بالدراسة فلا، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13028/حكم-تاخير-الظهر-الى-العصر-بعذر-الدراسة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_634/nour_63410.mp3","categories":["نصائح وتوجيهات","وقت الصلاة"]},{"id":14598,"question":"هذه رسالة وردتنا من المرسلة المواطنة: (ش. محمد. ش) من المجمعة، تقول في رسالتها:لقد أذن المغرب، واعتقدت أنه أذان العشاء الآخرة، فصليت المغرب أربعًا على هذه النية؛ ولما جلست أنا وبقية العائلة وأولادي وأذن للعشاء استنكرت ذلك، فأخبروني أن العشاء لم يؤذن له إلا الآن، هل أعيد صلاة المغرب أم لا؟وفقكم الله.","title":"أُذن للمغرب فظنته العشاء فصلت أربعًا هل تعيد المغرب؟","answer":"الجواب: المغرب ثلاث، ما هي بأربع، المغرب ثلاث، ما هي بأربع، فإذا كانت قد صلت المغرب ثلاثًا بنية المغرب، ثم سمعت الأذان فصلت العشاء تحسبه أذان العشاء، وكانت قد أخرت المغرب تحسب صلاة العشاء، هذا عليها أن تعيد العشاء فقط.  أما إذا كانت ما صلت المغرب، وصلت العشاء قبل أن تصلي المغرب تحسبه أن الأذان أذان العشاء، ونسيت المغرب ما صلت المغرب فإنها تعيد، تأتي تصلي المغرب، ثم تعيد العشاء؛ لأنها صلت العشاء في غير وقتها، وصلتها قبل المغرب.  والواجب أن تصلى بعد المغرب لا قبل المغرب، فإذا كانت قد صلت المغرب بعد غروب الشمس أجزأت المغرب، وأما العشاء فتعيدها؛ لأنها صلتها قبل وقتها، إذا كان العشاء قد أذن في أول الوقت، وإذا كان الأذان الذي سمعته أذان المغرب وصلت تحسبه العشاء فإنها تعيد العشاء؛ تعيد العشاء لأنها فعلت في غير وقتها، والصلاة في غير وقتها لا تصح، لكن إذا كانت ما صلت المغرب، لا بد تؤدي المغرب، تؤدي المغرب، ثم تصلي العشاء، نعم.\nالمقدم: هي حسب رسالتها صلت العشاء وقت المغرب، ثم لما أذن العشاء صلت العشاء، لكنها صلت المغرب بنية العشاء؟\nالشيخ: لا ما يصلح، ما يصلح، عليها أن تصلي المغرب ثلاثًا، وصلاة المغرب بنية العشاء أربعًا، هذا غلط، المسلم يعرف المغرب والعشاء، المغرب ثلاث والعشاء أربع، في حق المقيم أربع. فالحاصل: أن هذه إن كانت صلت المغرب في وقتها، فالحمد لله، فعليها أن تعيد العشاء؛ لأنها صلتها في غير وقتها، وإن كان ما صلت المغرب، وإنما صلت العشاء بنية المغرب أربعًا، فهذا غلط وباطل، فعليها أن تصلي المغرب أولًا: تقضي هذا المغرب، ثم تصلي العشاء الذي فعلته في غير الوقت، نعم.","link":"https://binbaz.org.sa/fatwas/13095/اذن-للمغرب-فظنته-العشاء-فصلت-اربعا-هل-تعيد-المغرب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_558/55805.mp3","categories":["وقت الصلاة"]},{"id":14720,"question":"يقول: نحن نعمل في مزرعة، ولا يوجد بها مسجد، وأنا أصلي الصلاة بعد الأذان بحوالي نصف ساعة، فهل هذا يكون في وقت الصلاة أم لا؟ وإذا لم يكن في وقتها فما هي المدة المحددة بين الأذان والإقامة؟","title":"ما حكم الصلاة بعد الأذان بنصف ساعة؟","answer":"الجواب: الأمر في هذا واسع، الحمد لله، عندك التقويم، تعرف التقويم، تعمل بالتقويم المعروف، التقويم هذا معروف ومستقيم التقويم لا بأس بالتقويم، تقويم أم القرى، يكون عندك إذا كان في مزرعتك حتى تعرف الأوقات، إذا كان ما تسمع الأذان، ما عندك مساجد، ما حولك مساجد، يكون عندك التقويم، وتعمل به، بعد التوقيت ربع ساعة، ثلث ساعة تصلي، نصف ساعة لا بأس، في الظهر والعصر والمغرب والعشاء والفجر، ولكن المغرب يكون أفضل لا تتأخر بعد عشر دقائق، ربع ساعة، تبادر بالمغرب؛ لأن الرسول كان يبادر بها -عليه الصلاة والسلام-. المقصود: يكون عندك نسخة من التقويم، حتى تعرف الأوقات إذا كانت المساجد بعيدة عنك لا تسمع الأذان، نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/13203/ما-حكم-الصلاة-بعد-الاذان-بنصف-ساعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_560/56025.mp3","categories":["وقت الصلاة"]},{"id":14831,"question":"يسأل أخونا سؤال آخر يقول: رجل يحافظ على الصلوات إلا أنه يتأخر عن صلاة الفجر بأوقات متفاوتة فبم تنصحونه؟جزاكم الله خيرًا.","title":"حكم التأخر عن صلاة الفجر","answer":"الجواب: ننصحه بالحذر من مشابهة أهل النفاق، فإن المنافقين يتأخروا عن صلاة العشاء والفجر، ويكسلون عنهما، فالواجب الحذر، والصلاة ثقيلة على المنافقين كلها ثقيلة على المنافقين، كما قال ﷺ: أثقل الصلاة على المنافقين صلاة العشاء وصلاة الفجر، ولو يعلمون ما فيهما لأتوهما ولو حبوًا يعني: لو يعلمون ما فيهما من الأجر العظيم لأتوهما ولو حبوًا. فالواجب على المؤمن أن يحذر صفات المنافقين، وأن يبتعد عنها، وأن يحافظ على الصلوات الخمس كلها في الجماعة، الفجر والظهر والعصر والمغرب والعشاء، ولا يجوز له التأخر عن صلاة الفجر أبدًا، بل يجب أن يعتني بها وأن يصليها مع إخوانه، كما يفعل مع الصلوات الأخرى، وإذا كان لا يستيقظ يستعين بالله، ثم ببعض أهله يعينونه على اليقظة، أو بوضع الساعة عند رأسه يركدها على قرب الفجر، ثم إذا ضربت قام، الله يسر هذه الساعات نعمة من الله، يجعلها عند رأسه يوكدها على الساعة التي يريد قبل الفجر، أو عند الفجر فإذا ضربت سمع الصوت، وقام. ومن الأسباب أيضًا: أن ينام مبكر، لا يسهر، عليه أن ينام مبكرًا إذا كان كثير النوم، وربما شق عليه النوم عليه أن يبكر، عليه أن لا يسهر؛ حتى يقوم عند الفجر نشيطًا ليس به مانع. ولا يجوز له التساهل في هذا الأمر أبدًا، بل يجب العناية بهذا الأمر لأمور: منها التبكير في النوم لا يسهر، ومنها وضع ساعة تعينه على ذلك يركدها على قرب الفجر، أو تكليف بعض أهله الذين يستيقظون أن يوقظوه، مع سؤال الله الإعانة على هذا الخير، والتوبة إليه مما سلف، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13314/حكم-التاخر-عن-صلاة-الفجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_491/49102.mp3","categories":["وقت الصلاة"]},{"id":14856,"question":"رسالة وصلت إلى البرنامج من الإخوة: مزهر حسن صالح، وحسين سعيد مقلم -فيما يبدو- ومحمد أحمد عصفور من اليمن الجنوبي، الإخوان يسألون هذه الأسئلة، يقولون في سؤالهم الأول:نحن طلبة في مدرسة ثانوية، تبعد عن قريتنا بحوالي ثلاثة عشر كيلو متر، نتحرك من المدرسة في الساعة الواحدة ظهرًا، ولا نصل إلى القرية إلا في حوالي الساعة الثانية بعد الظهر، فهل يجوز لنا أن نصلي الظهر بعد وصولنا مباشرة، أم نقضيها مع صلاة العصر؟","title":"من رجع قبل العصر، فهل يصلي الظهر أم يقضيها مع العصر؟","answer":"الجواب: الواجب عليكم صلاة الظهر في محلكم قبل الرحيل، أو بعد الرحيل، أو في أثناء الطريق، ولا تؤجل إلى العصر، لا بد من فعلها في الوقت.  وإذا صليتم قبل ذلك وأنتم في محلكم في المدرسة في أول الوقت كان أفضل وأولى من صلاتها في الطريق، ومن صلاتها في بلدكم؛ لأن الصلاة في أول وقتها أفضل، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13342/من-رجع-قبل-العصر-فهل-يصلي-الظهر-ام-يقضيها-مع-العصر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_638/nour_63821.mp3","categories":["وقت الصلاة"]},{"id":15047,"question":"يقول: إذا كنت أصلي، وسمعت الأذان، هل أكمل صلاتي أم أعيدها أم أقف حتى انتهاء الأذان؟","title":"ماذا يفعل من أذن المؤذن وهو يصلي الفرض؟","answer":"الجواب: المصلي يستمر في صلاته، ولا يجيب المؤذن، المصلي مشغول بالصلاة، فإذا أذن المؤذن وأنت في الصلاة؛ تكمل الصلاة، ولا تجيب المؤذن، نعم. المقدم: ولكن لو كانت هذه فرضًا مثلًا، والأذان على أول الوقت؟ الشيخ: هذا شيء آخر، إذا كان في الفريضة، لا يصليها إلا بعد التحقق من دخول الوقت، إذا كان مريضًا في البيت مثلًا، أو له مانع من الصلاة مع المسلمين في المساجد؛ لخوف، أو مرض؛ فإنه يصلي بعد دخول الوقت، ولو ما بعد أذن؛ لأن بعض المؤذنين قد يؤخر، قد يؤخر الأذان، ويفوت بعض الوقت، فإذا تحقق أن الوقت دخل؛ ساغ له أن يصلي فريضته، وإن كان لم يسمع أذانًا، كالمريض في بيتٍ بعيد عن المؤذنين، أو الخائف، أو المسافر الذي لا يسمع الأذان، متى تحقق الوقت؛ صلى، لكن المسافر السنة له أن يؤذن قبل الصلاة، إذا تحقق الوقت يؤذن، ثم يقيم ويصلي، لكن من كان في البلد ليس له أن يصلي إلا بعد دخول الوقت، وإذا دخل الوقت وعلمه؛ جاز له أن يصلي، وإن لم يسمع الأذان، نعم.","link":"https://binbaz.org.sa/fatwas/13559/ماذا-يفعل-من-اذن-الموذن-وهو-يصلي-الفرض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_654/nour_65404.mp3","categories":["وقت الصلاة","الأذان والإقامة"]},{"id":15050,"question":"يقول: إذا كنت أصلي، وسمعت الأذان، هل أكمل صلاتي أم أعيدها أم أقف حتى انتهاء الأذان؟","title":"ماذا يفعل من أذن المؤذن وهو يصلي الفرض؟","answer":"الجواب: المصلي يستمر في صلاته، ولا يجيب المؤذن، المصلي مشغول بالصلاة، فإذا أذن المؤذن وأنت في الصلاة؛ تكمل الصلاة، ولا تجيب المؤذن، نعم. المقدم: ولكن لو كانت هذه فرضًا مثلًا، والأذان على أول الوقت؟ الشيخ: هذا شيء آخر، إذا كان في الفريضة، لا يصليها إلا بعد التحقق من دخول الوقت، إذا كان مريضًا في البيت مثلًا، أو له مانع من الصلاة مع المسلمين في المساجد؛ لخوف، أو مرض؛ فإنه يصلي بعد دخول الوقت، ولو ما بعد أذن؛ لأن بعض المؤذنين قد يؤخر، قد يؤخر الأذان، ويفوت بعض الوقت، فإذا تحقق أن الوقت دخل؛ ساغ له أن يصلي فريضته، وإن كان لم يسمع أذانًا، كالمريض في بيتٍ بعيد عن المؤذنين، أو الخائف، أو المسافر الذي لا يسمع الأذان، متى تحقق الوقت؛ صلى، لكن المسافر السنة له أن يؤذن قبل الصلاة، إذا تحقق الوقت يؤذن، ثم يقيم ويصلي، لكن من كان في البلد ليس له أن يصلي إلا بعد دخول الوقت، وإذا دخل الوقت وعلمه؛ جاز له أن يصلي، وإن لم يسمع الأذان، نعم.","link":"https://binbaz.org.sa/fatwas/13559/ماذا-يفعل-من-اذن-الموذن-وهو-يصلي-الفرض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_654/nour_65404.mp3","categories":["وقت الصلاة","الأذان والإقامة"]},{"id":15058,"question":"السؤال الرابع يقول: ما حكم من أخر صلاة الفريضة حتى يخرج وقتها؟ وأيضًا داوم على هذا العمل؟نرجو الإجابة، وفقكم الله.","title":"ما حكم تأخير الصلاة عن وقتها؟","answer":"الجواب: هذا منكر وحرام عليه، لا يجوز له ذلك، بل الواجب أن يصلي الصلاة في وقتها، هذا هو الواجب، كما قال الله سبحانه: إِنَّ الصَّلاةَ كَانَتْ عَلَى الْمُؤْمِنِينَ كِتَابًا مَوْقُوتًا[النساء:103] فهي موقوتة على المؤمنين، يعني: مفروضة في أوقاتها.  فالواجب على المؤمن أن يصليها في الوقت، وليس له تأخيرها إلى ما بعد الوقت، لا الرجل ولا المرأة، يجب عليهما جميعًا أن تفعل الصلاة في الوقت، فالظهر في وقتها، والعصر في وقتها، والمغرب في وقتها، والعشاء في وقتها، والفجر في وقتها، وليس لأحد أن يؤخر الفجر إلى بعد طلوع الشمس، وليس لأحد أن يؤخر المغرب إلى غروب الشفق، وهكذا ليس له أن يؤخر الظهر إلى وقت العصر، ولا أن يؤخر العصر إلى أن تصفر الشمس، كل هذا لا يجوز، وعلى من فعل ذلك التوبة إلى الله، والرجوع إليه . وقد قال بعض أهل العلم: إنه يكفر بذلك، ذهب بعض أهل العلم إلى أنه يكفر بذلك؛ لأنه أخرجها عن وقتها الشرعي. فالحاصل: أن هذا منكر عظيم، يجب الحذر منه، وأن يجتهد المؤمن والمؤمنة في فعل الصلاة في وقتها بكل عناية، هذا هو الواجب، نعم.","link":"https://binbaz.org.sa/fatwas/13564/ما-حكم-تاخير-الصلاة-عن-وقتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_663/nour_66304.mp3","categories":["وقت الصلاة"]},{"id":15151,"question":"هذه أيضًا تقول في رسالتها: طبيب يعمل بالعمليات الطارئة، مما يؤدي أحيانًا إلى انشغاله عن الصلاة حتى خروج الوقت، ماذا يصنع؟ قيل له: إنه في تلك الحالة عليه أن يؤدي الصلاة بأية طريقة، فما هي هذه الطريقة؟وفقكم الله.","title":"حكم تأخير الصلاة عن وقتها للضرورة","answer":"الجواب: الواجب على المسلم أن يصلي الصلاة في وقتها، وأن لا يشغل عنها بشيء، اللهم إلا يكون شيء من الضرورات التي لا حيلة فيها، مثل إنقاذ غريق، وإنقاذ حريق، وصد هجوم عدو يخشى منه، فهذا لا بأس أن تؤخر الصلاة، ولو خرج وقتها. أما الأمور العادية التي لا خطر فيها؛ فلا يجوز تأخير الصلاة من أجلها، قد ثبت عن النبي ﷺ \"لما حاصر أهل مكة المدينة يوم الأحزاب أخر صلاة الظهر والعصر إلى بعد المغرب\" وفي رواية: \"أخر صلاة العصر إلى بعد المغرب\" من شغله بالقتال، وثبت أنه الصحابة لما حاصروا تستر وانفلق الفجر والقتال قائم والناس على الأسوار وعلى الأبواب؛ أجلوا صلاة الفجر حتى فتح لهم، ثم صلوها ضحى؛ لئلا يفوت الفتح؛ ولئلا يتراجع الكفار، فإذا كان مثل هذا؛ جاز التأخير؛ لأنه شيء ضروري. ومثل إنقاذ حريق وقع في البيت، أو غريق في نهر أو شبهه؛ فبادر بإنقاذه، أو بإنقاذ أهل البيت من الحريق؛ فإنه يجوز ذلك، ولو قدر أنه تفوته الصلاة في وقتها بهذا السبب؛ لأن إنقاذ النفوس المسلمة والمعصومة له أهمية عظيمة؛ ولأن هذا الخطر قد لا يستدرك لو قدم الصلاة؛ فتفوت المصلحة فجاز التأخير؛ لأنه شيء لا يفوت الصلاة كما يؤخر الإنسان في الجمع للمرض ونحوه فهذا أعظم من ذلك، إذا جاز تأخير الظهر إلى العصر والمغرب إلى العشاء؛ للمرض والسفر، فجواز تأخيرها عن وقتها، أو تأخير العصر عن وقتها، أو الفجر عن وقتها لإنقاذ غريق، أو حريق، ونحو ذلك أسهل وأولى، نعم.","link":"https://binbaz.org.sa/fatwas/13646/حكم-تاخير-الصلاة-عن-وقتها-للضرورة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_658/nour_65803.mp3","categories":["وقت الصلاة"]},{"id":15334,"question":"السائل يقول من اليمن: ما الحكم في أن بعض النساء يؤخرن صلاة الظهر يوم الجمعة إلى بعد صلاة الجمعة بوقت طويل؟فأفيدونا بذلك.","title":"حكم تأخير المرأة صلاة الظهر يوم الجمعة","answer":"الجواب: ليس لهذا أصل، إنما هو جهل منهن، فإذا أذن المؤذن، وزالت الشمس المرأة تصلي في بيتها الظهر أربع ركعات، وليس لها شأن في الجمعة، تصلي في بيتها أربع ركعات بعد الزوال، ولو صاحب الجمعة تأخر، ليس عليها أن تنتظر الجمعة، تصلي في بيتها الظهر أربعًا يوم الجمعة، وليس لها شأن في الجمعة.  لكن لو شهدت الجمعة مع الناس في المسجد كفاها صلت معهم ركعتين كفاها عن الظهر، لو أنها حضرت الجمعة وصلت مع الناس الجمعة سدتها عن الظهر، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/13826/حكم-تاخير-المراة-صلاة-الظهر-يوم-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_566/56611.mp3","categories":["وقت الصلاة"]},{"id":15350,"question":"من جمهورية مصر العربية، أسوان، مستمعة للبرنامج تقول: سماحة الشيخ، عندما تحين صلاة المغرب، أو أي صلاة أخرى، يكون وقت البرامج النافعة كهذا البرنامج، أو أي برنامج مفيد شرعي، فأنا أقدم سماع البرنامج على الصلاة حتى ينتهي البرنامج، هل عملي صحيح؟","title":"حكم تأخير الصلاة من أجل سماع برنامج شرعي","answer":"الجواب: لا بأس، تقديم سماع البرنامج، أو حلقة العلم، أو درس العلماء، ما دام الوقت واسع، لا بأس؛ لأن هذا البرنامج يفوت، والصلاة وقتها واسع، والحمد لله، فإذا أخر الصلاة لأجل سماع هذا البرنامج، أو سماع موعظة، أو ما أشبه ذلك فلا بأس، نعم.","link":"https://binbaz.org.sa/fatwas/13853/حكم-تاخير-الصلاة-من-اجل-سماع-برنامج-شرعي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_566/56623.mp3","categories":["وقت الصلاة"]},{"id":15605,"question":"سماحة الشيخ، هذا سائل للبرنامج يقول: السلام عليكم ورحمة الله وبركاته، وسؤالي -يا سماحة الشيخ- يذكر بأنه مقصر في صلاة الفجر، وينام عنها، ولا ينهض إلا عند طلوع الشمس في الساعة التاسعة، ويعمل جميع الوسائل، ولكن بدون فائدة، وأشعر بعد ذلك بالحزن والضيق. فأرجو من سماحتكم توجيهي إلى ما فيه الخير.","title":"حكم صلاة الفجر بعد طلوع الشمس لشدة النوم","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه. الواجب على المؤمن أن يجاهد نفسه، حتى يؤدي الصلاة في وقتها مع الجماعة، وأنت -أيها السائل- يجب عليك أن تعتني بهذا الأمر، إن كنت تسهر اترك السهر، وبكر في النوم، حتى يعينك ذلك -إن شاء الله- على القيام في وقت الصلاة، وإن كان هناك أسباب أخرى، اتركها حتى تنام، وحتى تستيقظ في وقت الصلاة، لا بد من الجهاد، الله يقول -جل وعلا-: وَالَّذِينَ جَاهَدُوا فِينَا لَنَهْدِيَنَّهُمْ سُبُلَنَا وَإِنَّ اللَّهَ لَمَعَ الْمُحْسِنِينَ [العنكبوت:69] ويقول سبحانه: حَافِظُوا عَلَى الصَّلَوَاتِ وَالصَّلاةِ الْوُسْطَى [البقرة:238] فلا بد من جهاد، ولا بد من صبر، فعالج الأمر بالشيء الذي تستطيعه، ادرس الأسباب التي تسبب لك هذا الكسل، وهذا الضعف حتى تعرف الأسباب، وابتعد عنها سواء كانت أسباب تتعلق بالسهر، أو بأشياء أخرى، حتى تنام مستريح، وتقوم على الوقت، توكد الساعة على الوقت الذي يناسب، سواء وقت الأذان أو قبله بقليل حتى يتيسر لك الوضوء أو الغسل إن كان عليك غسل بسهولة. المقصود: لا بد من علاج، وسؤال الله التوفيق والإعانة، ولا تضعف في هذا الأمر، بل يجب أن تعالج بالتبكير بالنوم، وبتعاطي أسباب اليقظة في وقت الصلاة، نعم. المقدم: سماحة الشيخ، أيضًا هل له أن يوصي الجيران والإخوان الحريصين على صلاة الفجر لإيقاظه في ذلك؟\nالشيخ: نعم، طيب هذا من باب التعاون على البر والتقوى، من باب التعاون إذا كان قد ينام، وقد لا يسمع الساعة لشدته، لا بد يوصي أهله الذين عنده في البيت أمه وأخواته يجاهدون معه، يوقظونه، عليهم التعاون معه، الله -جل وعلا- يقول: وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَى [المائدة:2] فعلى أمه وعلى أخته وعلى من في البيت أن يساعدوه في هذا؛ لأنه قد لا يسمع الساعة لشدة نومه. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/14143/حكم-صلاة-الفجر-بعد-طلوع-الشمس-لشدة-النوم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_570/57019.mp3","categories":["وقت الصلاة"]},{"id":15732,"question":"هذا السائل من سلطنة عمان يقول -سماحة الشيخ-: معظم المسنين في مرحلة معينة تقدم بهم العمر لا يستطيعون التمييز بين أوقات الصلاة، فتجد البعض منهم في بعض الأحيان قائم يصلي صلاة العصر في حوالي الساعة الثانية والنصف، لم يدخل الوقت في مثل هذه الحالة، وأحيانًا في الثالثة بالرغم من إقناعهم أن وقت الصلاة لم يحن بعد، ولكنهم لا يقتنعون بسهولة؛ فهل يقبل منهم، وهم على هذه الحالة، كبر السن والتقدم في العمر، وأحيانًا يكونون على غير وضوء بسبب تقدمهم كما ذكرت في السن؟","title":"حكم صلاة كبير السن قبل دخول الوقت","answer":"الجواب: يعلمون ويوجهون إذا كانوا يعقلون يعلمون، لا تجوز لهم الصلاة إلا بعد دخول الوقت، إذا سمعوا الأذان يصلون إذا كانوا لا يستطيعون الذهاب إلى المساجد، يقال لهم: لا يجوز؛ الصلاة باطلة إلا إذا كان مريضًا له أن يجمع، إذا كان كبيرًا في السن عاجزًا يصلي الظهر والعصر، لا بأس في وقتهما، في وقت إحداهما، تصح، أو المغرب والعشاء في وقت إحداهما تصح؛ لأنه عاجز عن الصلاة كل صلاة في وقتها، فإذا صلى الظهر في وقت العصر، أو العصر في وقت الظهر، وجمع بينهما فلا بأس، أو المغرب والعشاء كذلك؛ لكبر سنه وعجزه. أما إذا كان شعوره قد زال، ولا يعقل، ذهب عنه العقل، فلا شيء عليه، ليس عليه صلاة؛ صلاته باطلة، ولا يشتغل به، إذا كان عقله قد تغير واختل، أما إذا كان عقله معه مضبوط يعلم، يجب عليه أن يصلي الظهر والعصر في وقتها، والمغرب والعشاء في وقتها، ولا بأس بالجمع إذا كان يشق عليه أن يصلي كل صلاة في وقتها، وإذا كان يستطيع الصلاة مع الناس يلزمه الخروج حتى يصلي مع الناس في المساجد، والله المستعان.\nالمقدم: الله المستعان، الأولاد والبنات إذا قاموا على والدهم الكبير في السن، هل لهم أجر إذا قاموا بتعليمه، وفي تأدية الصلاة؟ الشيخ: نعم مأجورون، بل يجب عليهم إذا كان يجهل يجب عليهم أن يعلموه، لكن بالرفق بالكلام الطيب، والرفق لا بالشدة؛ حتى يقبل منهم، وهكذا مع غيره -من كبار السن أو من غيرهم- يتحرى المعلم الرفق؛ لأن هذا أقرب إلى القبول، كما قال ﷺ: من يحرم الرفق يحرم الخير كله فالولد مع والده، ومع أخيه الكبير، ومع جده، ومع أمه يرفق كثيرًا؛ لعله يقبل منه، وهكذا مع غيرهم؛ فإن الشدة قد تسبب الحرمان، وعدم الفائدة، لكن يرفق، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/14302/حكم-صلاة-كبير-السن-قبل-دخول-الوقت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_574/57416.mp3","categories":["وقت الصلاة"]},{"id":15903,"question":"إذا تأخر الإنسان عن الصلاة بسبب السهو أو النوم فهل يكون آثمًا؟","title":"حكم التأخر عن الصلاة بسبب السهو أو النوم","answer":"الجواب: إذا كان لم يتعمد أسباب ذلك فلا شيء عليه، يقول النبي ﷺ: ليس في النوم تفريط، إنما التفريط في اليقظة أن يؤخر الرجل الصلاة إلى أن يخرج وقتها أو إلى وقت التي بعدها، والله يقول سبحانه: رَبَّنَا لا تُؤَاخِذْنَا إِنْ نَسِينَا أَوْ أَخْطَأْنَا[البقرة:286] فقال الله: قد فعلت فإذا نام الإنسان النوم المعتاد، وغلبه النوم أو شغل له شاغل، ونسي فلا شيء عليه، فقد نسي النبي ﷺ وقد نسي الصحابة، وقد نام النبي ﷺ حتى ضربته الشمس مع الصحابة كل ذلك وقع، وابن آدم محل نسيان، ومحل جهل، كما قال ﷺ: إنما أنا بشر أنسى كما تنسون. فالحاصل: أن الإنسان يبتعد عن أسباب النوم فيبكر بالنوم حتى يقوم الفجر، يبكر ولا يسهر ويضع الساعة التي تعينه على ذلك على وقت مناسب للصلاة، أو كان عنده أهل عندهم انتباه يأمرهم بأن يوقظوه، يفعل الأسباب حتى لا ينام عن فريضة الله -جل وعلا-، أما النسيان فقد يغلبه، وليس باختياره، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14494/حكم-التاخر-عن-الصلاة-بسبب-السهو-او-النوم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_746/nour_74603.mp3","categories":["وقت الصلاة"]},{"id":15942,"question":"يقول: رجاءً توجيه كلمة لمن يسهر، ويضيع وقت صلاة الصبح، وبالمناسبة هل نقول: صلاة الفجر أم صلاة الصبح؟","title":"توجيه لمن يسهر ويضيع صلاة الفجر","answer":"الجواب: يقال: صلاة الصبح، وصلاة الفجر، لا بأس بهذا، يقال لها: صلاة الفجر، ويقال لها: صلاة الصبح.  ووصيتي لكل مؤمن ومؤمنة الحذر من السهر الذي يضر الساهر قبل غيره، السنة البدار بالنوم، وعدم السهر، والنبي -عليه الصلاة والسلام- \"كره النوم قبلها، والحديث بعدها\" يعني: العشاء، وكره السمر بعدها. فالسنة للمؤمن والمؤمنة البدار بالنوم في أول الليل؛ حتى ينشط على صلاة آخر الليل، وحتى ينشط على أعماله في النهار، وربما سهر فضيع صلاة الفجر، أو ضيع قيام الليل، وهذا خطر عظيم، إذا ضيع صلاة الفجر أتى جريمة عظيمة، فالواجب الحذر من ذلك، وأن يحافظ على صلاة الفجر في الجماعة إن كان رجلًا، وفي الوقت إن كانت امرأة، إلا إذا كان السهر من مصلحة عارضة مع الضيف، أو في الأمر بالمعروف والنهي عن المنكر، أو مع أهله لمصلحة؛ لكن سهر لا يضر، ولا يضيع التهجد بالليل، ولا يضيع صلاة الفجر. فالسهر الذي له حاجة لا بأس به كان النبي ﷺ يسهر مع الضيف، يعني: ويسهر في مصالح المسلمين بعض الوقت -عليه الصلاة والسلام-، مع الصديق ومع عمر، فلا بأس بهذا كون الإنسان يسهر بعض الوقت مع أهله في معاشرتهم أو في مسائل تدعو الحاجة إلى ذلك، أو مع الضيف، أو في طلب العلم ودراسة العلم، كما كان أبو هريرة يفعل، فإن كان لحاجة أو مصلحة بشرط أن لا يضيع صلاة الفجر وبشرط أن لا يمنعه عن أعماله النهارية التي يلزمه أداؤها.  فالحاصل: أن السهر للمصلحة الشرعية التي لا يترتب عليه فوات مصالح أخرى، ولا يترتب عليه فوات صلاة الفجر أمر لا بأس به، والسنة في الجملة العناية بالنوم مبكرًا لما فيه من المصالح العظيمة، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14547/توجيه-لمن-يسهر-ويضيع-صلاة-الفجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_710/nour_71004.mp3","categories":["وقت الصلاة"]},{"id":16059,"question":"من المستمع سلام علي محمد من العراق يقول: إنني طالب، ودراستي تبدأ بعد صلاة الظهر، وتنتهي بعد صلاة المغرب، وبذلك فإن صلاة العصر تفوتني؛ فأضطر أن أصليها قضاءً بعد عودتي، علمًا بأن هذه الظاهرة تتكرر يوميًا، فهل ما أفعله صحيح؟","title":"حكم تأخير الصلاة لأجل الدراسة","answer":"الجواب: ليس لك ذلك، بل يجب عليك أن تصلي الصلاة في وقتها، عليك أن تصلي صلاة العصر في وقتها في محل الدراسة، وليس لك أن تؤخرها إلى المغرب، أو إلى أن تصفر الشمس، بل عليك أن تصلي الصلاة في وقتها، وتدع العمل، سواءً كان العمل دراسةً، أو غير دراسة، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14685/حكم-تاخير-الصلاة-لاجل-الدراسة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_748/nour_74814.mp3","categories":["وقت الصلاة"]},{"id":16545,"question":"من المستمع: إدريس محمد حامد سوداني، رسالة يقول فيها: إنني أؤخر صلاة العشاء في أكثر الأوقات، ويقول: هل علي إثم؟ علمًا بأني أصليها داخل الوقت؟","title":"ما حكم تأخير الصلاة عن أول وقتها؟","answer":"الجواب: الواجب عليك يا أخي أن تصلي مع الجماعة، مع المسلمين في بيوت الله، في المساجد، وليس لك أن تصلي في البيت. بل عليك، بل الواجب عليك أن تخرج إلى المسجد كما فعل المسلمون مع نبيهم ﷺ وقد قال -عليه الصلاة والسلام- في الحديث الصحيح: من سمع النداء فلم يأت؛ فلا صلاة له إلا من عذر قيل لابن عباس، ما هو العذر؟ قال: خوف، أو مرض. وجاءه ﷺ رجل أعمى، فقال: يا رسول الله، ليس لي قائد يقودني إلى المسجد، فهل لي من رخصة أن أصلي في بيتي؟ فقال له ﷺ: هل تسمع النداء بالصلاة؟ قال: نعم، قال: فأجب فلم يرخص له، وهو أعمى ليس له قائد يقوده، فكيف بالبصير، بالقوي؟! يكون الأمر عليه أعظم. وقد ثبت عنه ﷺ أنه قال: لقد هممت أن آمر بالصلاة، فتقام، ثم آمر رجلًا، فيؤم الناس، ثم أنطلق برجال معهم حزم من حطب إلى قوم لا يشهدون الصلاة، فأحرق عليهم بيوتهم هذا وعيد عظيم، يدل على أن الحضور في المساجد، والصلاة مع الناس أمر لازم، قال ابن مسعود  في الحديث الصحيح: \"لقد رأيتنا، وما يتخلف عنها إلا منافق معلوم النفاق -يعني: الجماعة- ولقد كان الرجل يؤتى به يهادى بين الرجلين، حتى يقام في الصف\". لكن لو فاتتك مع الجماعة صل في الوقت، لا يجوز لك التأخير عن الوقت، أو كنت مريضًا فعليك أن تصلي في الوقت، أو سجينًا عليك أن تصلي في الوقت، العشاء، وغير العشاء، يجب أن تصلي في الوقت، ليس لك أن تقدمها، وليس لك أن تؤخرها، بل يجب وجوبًا أن تصليها في الوقت، وفي أوله أفضل، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15277/ما-حكم-تاخير-الصلاة-عن-اول-وقتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_815/nour_81508.mp3","categories":["صلاة الجماعة","وقت الصلاة"]},{"id":16841,"question":"من المستمع (ع. س. ج) رسالة ضمنها بعض الأسئلة يقول في أحدها: ما حكم صلاة المغرب جماعة قبل أذان العشاء بعشر دقائق؟","title":"حكم صلاة المغرب جماعة قبل أذان العشاء","answer":"الجواب: الصلاة صحيحة إذا كانوا صلوها قبل غروب الشفق، لكن تركوا الأفضل، الأفضل أن يصلوا في أول الوقت، لكن لو أخروا صلاة المغرب، وصلوها قبل غروب الشفق الأحمر بعشر دقائق، أو ربع ساعة؛ لا حرج، لكن لا ينبغي لهم ذلك، السنة أن تقدم، وأن يبادر بها في أول وقتها، نعم.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15608/حكم-صلاة-المغرب-جماعة-قبل-اذان-العشاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_824/nour_82406.mp3","categories":["وقت الصلاة"]},{"id":16857,"question":"هذه أخت سائلة (ح. م. أ) من المملكة تقول: سماحة الشيخ فتاة في أيام الامتحانات تذاكر، وجاء وقت صلاة العشاء، ولم تصل، وتعلم بخروج الوقت إلى أن أصبحت الساعة الثانية عشرة ليلًا، وبعدما انتهت من المذاكرة؛ صلت العشاء، فما الحكم؟ وهي نادمة على ذلك، هل عليها كفارة؟","title":"ما حكم تأخير العشاء إلى منتصف الليل؟","answer":"الجواب: الواجب عليها التوبة إلى الله إذا خرج الوقت؛ لأن الوقت ينتهي بنصف الليل، عليها أن تصلي العشاء قبل نصف الليل، فإذا تساهلت؛ فعليها التوبة والاستغفار، تصلي ولو بعد نصف الليل، لكن تستغفر ربها، ولا تعود، النبي ﷺ قال: وقت العشاء إلى نصف الليل يبتدئ حساب الليل من غروب الشمس بالساعة. فالمقصود: أن السنة لها، بل الواجب عليها، وعلى غيرها أن تكون صلاة العشاء قبل نصف الليل، ولا بأس بتأخيرها بعد الثلث الأول قبل نصف الليل، لا بأس، لكن التأخير إلى بعد نصف الليل لا يجوز.","link":"https://binbaz.org.sa/fatwas/15597/ما-حكم-تاخير-العشاء-الى-منتصف-الليل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_586/58605.mp3","categories":["صلاة الجمعة","وقت الصلاة","قضايا المرأة"]},{"id":16868,"question":"سؤالها الأخير تقول فيه: إلى أي وقت بعد الأذان يعتبر الإنسان مؤخرًا للصلاة؟ أرجو التحديد بالساعة إذا أمكن، جزاكم الله خيرًا.","title":"بداية ونهاية أوقات الصلاة","answer":"الجواب: عليك أن تراعي التقويمات التي تصدر من وزارة الأوقاف حتى تعلمي أول الوقت، وآخره، فيه تقويم يصدر إذا كنت في المملكة، راعي التقويم، واعملي به؛ حتى تعرفي أول الوقت، وآخره، كله موضح في التقويم بالساعة، فأنت لاحظي ذلك، والحمد لله. أما بالتوقيت الذي وضحه النبي ﷺ: فالظهر يدخل من زوال الشمس إذا زالت الشمس، ويستمر إلى أن يصير ظل كل شيء مثله، بعد فيء الزوال، كل هذا من الظهر، والأفضل أن تصلي في الوقت، الأفضل أن تؤدى الصلاة في أول الوقت، هذا هو الأفضل، إلا في شدة الحر، فالأفضل التأخير في الظهر حتى ينكسر الحر. والعصر يبدأ إذا صار ظل كل شيء مثله، إذا صار ظل كل شيء مثله بعد فيء الزوال؛ دخل وقت العصر إلى أن تصفر الشمس، والأفضل أن تؤدى الصلاة في أول الوقت، والشمس مرتفعة بيضاء نقية، هذا هو الأفضل. والمغرب يبدأ بغروب الشمس، إذا غابت، ويستمر إلى غروب الشفق، وهو الحمرة التي في جهة المغرب يقال لها: الشفق الأحمر؛ إذا غاب الشفق الأحمر؛ دخل وقت العشاء، ويستمر إلى نصف الليل، كله وقت العشاء، فلا يجوز التأخير إلى بعد نصف الليل. والفجر يبدأ بطلوع الفجر الصادق الذي ينتشر في الجو في الجهة الشرقية ينتشر، يقال له: الفجر الصادق الذي ينبسط في الجهة الشرقية، ويستمر إلى طلوع الشمس، إذا طلعت الشمس خرج وقت الفجر، هذا التوقيت الشرعي، وبالساعات ينظر في التقويم، نعم.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15630/بداية-ونهاية-اوقات-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_764/nour_76414.mp3","categories":["وقت الصلاة"]},{"id":16882,"question":"يسأل سؤالًا آخر فيقول: سمعت من أحد الأشخاص قولًا، وهو: يجوز للمسلم أن يصلي صلاة العشاء قبل الوقت المحدد لها في التقويم، فهل هذا صحيح، وإن كان صحيحًا فما هو الدليل على ذلك؟ أفيدونا بارك الله فيكم.","title":"حكم الصلاة قبل الوقت المحدد في التقويم","answer":"الجواب:  ليس لأحد أن يصلي الصلوات الخمس قبل التقويم، قبل الوقت، بل عليه أن يتقيد بالتقويم الموضوع؛ حتى لا يوقع الصلاة في غير وقتها، إلا إذا علم أن التوقيت مخالف للوقت الشرعي، كالذي في الصحراء مثلًا، ورأى الصبح قد طلع -الصبح الصادق- قبل التقويم يصلي، أو رأى الشمس غربت قبل التقويم، وهو في الصحراء يصلي إذا غربت الشمس، ولا عليه من التقويم. أما إذا كان ما عنده علم؛ يتقيد بالتقويم؛ لأن التقويم قد اجتهدت به لجنة، واعتنت به لمصلحة المسلمين، ولراحتهم، فالواجب التقيد به في جميع الأوقات، إلا في حق من علم أن الوقت قد دخل قبل التقويم، كما مثلنا، كالذي -مثلًا- في الصحراء، في السفر، ومعه التقويم؛ لكن رأى الصبح قد بان واتضح قبل التقويم، أو رأى التقويم مبكرًا، والصبح ما بعد خرج؛ فلا يعتمد التقويم، بل يعتمد الصبح، فإذا كان التقويم قد بكر وهو في الصحراء يشوف الصبح، لا يصلي حتى يتضح الصبح، وإذا كان التقويم قد تأخر، ورأى الصبح خالف التقويم، وطلع ضوء بينٌ، الصبح الصادق يعتمد ما رآه، ولا يهمه التقويم، كذلك في الغروب، والظهر، والعصر إذا رأى أن الشمس قد زالت قبل التقويم؛ اعتمد ذلك، أو رآها قد غربت قبل التقويم، يراها بعينه؛ اعتمد ذلك، لا بأس، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15636/حكم-الصلاة-قبل-الوقت-المحدد-في-التقويم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_825/nour_82502.mp3","categories":["وقت الصلاة"]},{"id":17086,"question":"من الجمهورية العربية اليمنية السائل: محمد أحمد بعث يسأل ويقول: الناس قبل شهر رمضان كانوا يؤذنون لصلاة العشاء في السابعة تقريبًا، وعندما دخل هذا الشهر الكريم صاروا يؤذنون لصلاة العشاء في الحادية عشرة، ما حكم هذا العمل؟","title":"حكم تأخير صلاة العشاء في رمضان وغيره","answer":"الجواب: النبي ﷺ أوضح المواقيت، وبينها -عليه الصلاة والسلام- فوقت العشاء يدخل حين يغيب الشفق الأحمر في جهة الغرب، فإذا غاب الشفق الأحمر دخل وقت العشاء إلى نصف الليل، فللمسلمين أن يؤذنوا في أول الوقت، وهو أفضل، ولهم التأخير إذا رأوا المصلحة في ذلك فلا بأس، والنبي ﷺ رغب في التأخير في العشاء، وقال: لولا أن أشق على أمتي لأمرتكم بالصلاة هذه الساعة لما أخرها إلى ثلث الليل، عليه الصلاة والسلام. فإذا صارت المصلحة أن يؤخروها، اتفق أهل بلد، أو أهل مسجد على أن يؤخروها في آخر الوقت، يعني: العشاء، في رمضان، أو في غيره فلا بأس، لكن لا يؤخرونها عن الوقت، لا بد يكون في الوقت حتى يصلوا قبل خروج الوقت، فهم مخيرون بين أوله وآخره، وخصوصًا العشاء. أما بقية الأوقات فالأفضل في أول الوقت، يقدمون الصلاة في أول وقتها، يؤذن في أول الوقت، ثم يتأخر الإمام حتى يتجمع الناس ربع ساعة.. ثلث ساعة، ثم يصلي، هذا هو الأفضل، إلا في الظهر عند شدة الحر فالأفضل التأخير أيضًا، في الظهر لشدة الحر. أما العشاء فالأفضل فيها التأخير إلا إذا رأوا الجماعة أهل المسجد، أو القرية التقديم فلا بأس، وإذا كانوا في رمضان يصلونها مؤخرة في آخر وقتها فلا حرج في ذلك إذا اتفقوا على هذا، ورأوا المصلحة في ذلك لا بأس، أو في غير رمضان أيضًا. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15959/حكم-تاخير-صلاة-العشاء-في-رمضان-وغيره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_831/nour_83118.mp3","categories":["وقت الصلاة"]},{"id":17148,"question":"يقول هذا السائل سماحة الشيخ: إذا طهرت المرأة من الحيض وقت الظهر، فماذا عليها أن تصلي، وإن طهرت وقت العصر، أو المغرب، أو العشاء، أو الفجر، ماذا عليها من قضاءٍ وصلاة؟","title":"إذا طهرت المرأة في العصر هل يجب عليها أن تصلي الظهر؟","answer":"الجواب: إذا طهرت في الظهر، أو العصر تصلي الظهر والعصر، وإذا طهرت في الليل تصلي المغرب والعشاء، هذا هو الواجب عليها كما أفتى بذلك جمع من الصحابة -رضي الله عنهم وأرضاهم- فإذا طهرت العصر فإن الواجب عليها أن تصلي الظهر والعصر جميعًا، وإذا طهرت بعد المغرب، أو بعد العشاء أو في وسط الليل، أو قبل الفجر تصلي المغرب، والعشاء. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/15966/اذا-طهرت-المراة-في-العصر-هل-يجب-عليها-ان-تصلي-الظهر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_589/58928.mp3","categories":["الحيض والنفاس","وقت الصلاة","قضايا المرأة"]},{"id":17171,"question":"بعد انتهاء المصلين من الصلاة، وخروجهم من المسجد هل يعني هذا أن وقت الصلاة قد انتهى فعلًا بخروجهم؟","title":"متى نهاية أوقات الصلاة؟","answer":"الجواب: وقت الصلاة لا، وقت الصلاة محدود، له حدود، فالمغرب ينتهي وقتها بغروب الشفق الأحمر من جهة المغرب، والعشاء وقتها إلى نصف الليل الأوسط، والفجر إلى طلوع الشمس، والظهر إلى أن يصير ظل كل شيء مثله بعد فيء الزوال، والعصر إلى أن تصفر الشمس، فالأوقات لها حدود، لا يخرج الوقت بخروج الناس من المسجد، وإنما يخرج الوقت ... الذي حدده الرسول ﷺ وبينه الله في كتابه العظيم . نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/15990/متى-نهاية-اوقات-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_722/nour_72219.mp3","categories":["وقت الصلاة"]},{"id":17172,"question":"ما حكم تأخير صلاة العشاء عن وقتها؛ لأن بعض الناس يقولون: إن تأخيرها عن وقتها للنساء أفضل؟","title":"وقت صلاة العشاء للرجال والنساء","answer":"الجواب: السنة في العشاء في حق الرجال، إذا رآهم الإمام اجتمعوا؛ عجل، وإذا رآهم أبطؤوا؛ أخَّر بعض الشيء حتى يجتمعوا، هكذا كان النبي يفعل -عليه الصلاة والسلام- في صلاة العشاء، إذا رآهم اجتمعوا، وتواصلوا؛ صلى، وإذا رآهم تأخروا؛ لم يعجل -عليه الصلاة والسلام- حتى يتلاحقوا. أما المرأة تصلي في بيتها متى تيسر لها ذلك، إذا غاب وقت المغرب، غاب الشفق الأحمر، وأذن العشاء تصلي، سواءً في أول الوقت، أو في آخره، فوقت العشاء ينتهي إلى نصف الليل الأوسط، تصلي قبل نصف الليل، والحمد لله، متى يسر الله لها ذلك، بين غروب الشفق، وبين نصف الليل، والأذان علامة على دخول الوقت، إن دخل وقت العشاء، فإذا صلت بعد الأذان حصل المقصود، أو تأخرت بعض الوقت لا بأس، لكن يكون قبل نصف الليل. نعم.","link":"https://binbaz.org.sa/fatwas/15991/وقت-صلاة-العشاء-للرجال-والنساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_722/nour_72220.mp3","categories":["وقت الصلاة"]},{"id":17250,"question":"سماحة الشيخ تقول السائلة: سمعت بأنه يجوز أن يؤخر الإنسان صلاة العشاء إلى ما بعد منتصف الليل.. فهل هذا صحيح في بعض الأحيان؟","title":"حكم تأخير صلاة العشاء إلى بعد منتصف الليل","answer":"الجواب: لا، لا يجوز التأخير إلى نصف الليل، النبي وقت إلى نصف الليل، أما بعد نصف الليل فلا، يقول ﷺ: وقت العشاء إلى نصف الليل ... فالصلاة تصلى قبل نصف الليل. نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/16082/حكم-تاخير-صلاة-العشاء-الى-بعد-منتصف-الليل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_592/59204.mp3","categories":["وقت الصلاة"]},{"id":17338,"question":"المستمعة من اليمن تقول: إذا تأخرت عن صلاة الفجر -أي: بعد طلوع الشمس- فهل أصلي السنة ثم الفرض، أم الفرض دون السنة؟","title":"كيفية ترتيب الفجر مع سنتها عند الاستيقاظ متأخرا","answer":"الجواب: قد ينام الإنسان عن صلاة الفجر، يصلي النافلة قبل ركعتين، ثم الفريضة، النبي ﷺ في بعض أسفاره أخذهم النوم، فلم يستيقظوا إلا بحر الشمس، فلما استيقظوا صلاها كما كان يصليها في وقتها، أمر بالأذان، ثم صلى الراتبة، ثم صلى الفريضة، عليه الصلاة والسلام. فالمرأة، أو الرجل إذا غلب عليهم النوم، ولم يستيقظوا إلا بعد طلوع الشمس، يصليها كما كان يصليها في وقتها، يصلي الراتبة، ثم يصلي الفريضة، لكن لا يجوز التساهل في هذا، بل يجب على الرجل والمرأة فعل الأسباب: من ضبط الساعة على وقت الصلاة، أو تنبيه أهل البيت يوقظوهم، ولا يتساهلون في هذا، يجب على المؤمن أن يعتني بالصلاة في وقتها؛ سواء كان بإيجاد ساعة يأقتها على الوقت، أو بتنبيه أهل البيت يوقظونه، ويوقظون المرأة كذلك، الصلاة في وقتها أمر لازم، وفريضة، ولا يجوز التساهل في هذا، التساهل في هذا من صفات المنافقين، نسأل الله العافية. المقدم: أحسن الله إليكم، وبارك فيكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16170/كيفية-ترتيب-الفجر-مع-سنتها-عند-الاستيقاظ-متاخرا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_593/59318.mp3","categories":["وقت الصلاة"]},{"id":17376,"question":"نعم يا سماحة الشيخ، تقول الأخت: ما السر في كون الحائض إذا طهرت قبل المغرب تقضي صلاة الظهر، مع أن وقتها قد خرج؟","title":"الحكمة من قضاء الحائض الظهر إذا طهرت قبل المغرب","answer":"الجواب: لأن العصر يستمر وقتها إلى غروب الشمس، يقول النبي ﷺ: من أدرك ركعةً من العصر قبل أن تغرب الشمس فقد أدرك العصر، ومن أدرك ركعة من الصبح قبل أن تطلع الشمس فقد أدرك الصبح فإذا طهرت في آخر النهار أفتى بعض الصحابة بذلك أنها تصلي الظهر، والعصر جميعًا؛ لأنها أدركت بعض الوقت، فأشبهت المريض، تصلي الظهر، والعصر جميعًا، إذا كان طهرها قبل العصر، قبل غروب الشمس بركعة فأكثر، وهكذا إذا طهرت قبل الشمس بقليل بركعة تصلي الفجر، لو طهرت قبل طلوع الفجر في آخر الليل تصلي المغرب والعشاء. نعم. المقدم: أحسن إليك يا شيخ.","link":"https://binbaz.org.sa/fatwas/16225/الحكمة-من-قضاء-الحاىض-الظهر-اذا-طهرت-قبل-المغرب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_594/59401.mp3","categories":["الحيض والنفاس","وقت الصلاة","قضايا المرأة"]},{"id":17561,"question":"من اليمن السائلة (هـ. ن. أ) تقول: هل يجوز للمرأة أن تصلي صلاة الفجر بعد الأذان الأول مباشرة قبل الإقامة وقبل الأذان الثاني بحيث إنني سمعت أن المرأة ليس لها إقامة؟","title":"حكم صلاة المرأة للفجر بعد الأذان الأول","answer":"الجواب: الواجب على الرجال والنساء ألا يصلوا الفجر إلا بعد طلوع الفجر الصادق، بعد طلوع الفجر الصادق، وبعد الأذان الذي أذان الفجر، أما الأذان الأول الذي يؤذن به في آخر الليل لتنبيه الناس هذا ما يدخل به وقت الصلاة، ولا تصلى الفريضة بعده، ولكن إذا أذن المؤذن الذي يؤذن على طلوع الفجر الصادق على الصبح فيصلي الرجال والنساء، أما الأذان الأول اللي قبل طلوع الفجر فهذا للإعلام فقط أن الفجر قريب حتى يعلم الناس أنه قريب، اللي يوتر يوتر، واللي يقوم يتوضأ. وأما الفريضة فلا تصلى إلا بعد طلوع الفجر الصادق للرجل والمرأة جميعًا، وليس للمرأة إقامة ولا أذان، لكن متى طلع الفجر وأذن المؤذن، وسمعت الأذان؛ تتأخر بعض الشيء ثم تصلي، لا تعجل حتى يمضي وقت من باب الاحتياط، فإذا مضى وقت ربع ساعة ثلث ساعة صلت أو نصف ساعة صلت الفجر، ولا يلزمها التقيد بالمساجد وأن تسمع الإقامة، لا، صلاتها مستقلة تصلي سواء سمعت الإقامة أو ما سمعت الإقامة، متى أذن ومضى وقت بعد الأذان ربع ساعة ثلث ساعة للاحتياط صلت الفريضة، وهكذا الظهر، والعصر، والمغرب، والعشاء. نعم.\nالمقدم: جزاكم الله خيرًا، بعض النساء يا سماحة الشيخ ينتظرن حتى يخرج الرجال من المساجد؟\nالشيخ: هذا لا أصل له، صلاة المرأة ما هي مربوطة بالرجال، تصلي في بيتها متى دخل الوقت وأذن المؤذن والحمد لله، الرجال لهم صلاتهم، وهي لها صلاتها في بيتها، غير مربوطة بالرجال. نعم.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/16484/حكم-صلاة-المراة-للفجر-بعد-الاذان-الاول","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_775/nour_77521.mp3","categories":["صلاة الجمعة","وقت الصلاة","قضايا المرأة"]},{"id":17633,"question":"رسالة أيضًا مطولة وصلت إلى البرنامج من البحرين صاحبها كتب في نهايتها: ابنك من البحرين خالد حسن خليفة ملخص ما في هذه الرسالة: أنه يعمل في البحر ووظيفته حساسة إلى أبعد الحدود كما يصورها ويقول: إنه لا يستطيع أن يصلي كثيرًا من الصلوات في أوقاتها كما أنه لا يصلي الجمعة إلا مرتين في الشهر نظرًا لعدم تمكنه من ذلك، ويرجو من سماحتكم التوجيه جزاكم الله خيرًا.","title":"حكم تأخير الصلاة بعذر العمل","answer":"الجواب: الواجب على كل مسلم أن يصلي الصلاة في وقتها، وليس له تأخيرها عن وقتها، بل يجب على المؤمن أن يصليها على حسب حاله؛ إن كان مريضًا صلاها قاعدًا، عاجزًا صلاها على جنبه أو مستلقيًا على حسب طاقته، وليس له التأخير لكن لا مانع من أن يجمع بين الظهر والعصر أو المغرب والعشاء إذا كان مسافرًا أو كان مريضًا أو كان في حالة مطر وشق عليه الخروج للمساجد.\nفالمقصود: أنه لابد من عذر شرعي، وكونه في البحر لا يمنع من كونه يصلي الصلاة في وقتها، فإذا أراد أن يغوص في البحر ينظر الوقت المناسب فيغوص في الأوقات المناسبة التي لا تمنع أداء الصلاة في وقتها، وإذا كان له أعمال في البحر أخرى لابد أن يراعي أوقات الصلوات حتى لا يخل بها، تكون أعماله متفقة مع الأوقات حتى لا يخل بالصلاة، وليس له عذر أن يقدم أعماله الدنيوية والتجارية على الصلاة في وقتها، هذا ليس بعذر لا في البحر ولا في البر ولا في الجو.  أما إذا عرض له عارض من مرض أو نوم ليس باختياره هذا شيء عفا الله عنه، المريض يجمع بين الصلاتين الظهر والعصر والمغرب والعشاء، النائم غلبه النوم من غير تعمد منه إذا استيقظ يصلي لكن التعمد لا، لا يتعمد تأخيرها عن وقتها ولا تقديمها على وقتها. نعم.\nالمقدم: جزاكم الله خيرًا، هو ليس من الغواصين سماحة الشيخ وإنما عمله على ظهر السفينة؟\nالشيخ: هذا أشد في وجوب الملاحظة؛ لأن لا عذر له يجب عليه أن ... بالصلاة في وقتها. نعم.\nالمقدم: مهما كانت الأحوال؟\nالشيخ: مهما كانت الحال. نعم، أمر الله مقدم، حق الله مقدم. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16569/حكم-تاخير-الصلاة-بعذر-العمل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_844/nour_84409.mp3","categories":["وقت الصلاة"]},{"id":17637,"question":"متى يعذر الشخص -سماحة الشيخ- بتأخير الصلاة عن وقتها؟","title":"متى يعذر المسلم بتأخير الصلاة عن وقتها؟","answer":"الجواب: هذا يعذر في الحروب .... الحروب التي تغلبه مثلما أخر النبي ﷺ في يوم الأحزاب صلاة الظهر والعصر حتى صلاها بعد المغرب بسبب الحرب لم يتمكن من فعلها على الصحيح، الجمهور يقولون: لا يؤخر حتى في الحرب يصلي على حسب حاله حتى في الحرب، لكن الصواب أنه إذا غلبه الأمر وغلبه القتال جاز أن يؤخر كما فعل النبي ﷺ يوم الأحزاب، وكما فعل الصحابة في قتال الفرس يوم تستر أخروا الفجر حتى صلوها ضحى؛ لأنها صادفت وقت الحرب، وقت نزول الناس البلد وبعضهم على أبواب البلد وبعضهم على الأسوار لم يتمكنوا من فعل صلاة الفجر حتى فتحوا البلد وصلوها ضحى.\nفالمقصود: أن تأخير الصلاة عن وقتها لا يجوز إلا في العذر الشرعي في الجمع بين الصلاتين كالمريض والمسافر يجمع بين صلاتي الظهر والعصر، والمغرب والعشاء هذا جمع، أما أن نؤخر الصبح حتى طلوع الشمس أو العصر إلى الليل أو المغرب إلى بعد العشاء أو العشاء إلى بعد نصف الليل أو بعد الفجر هذا ما يجوز، بل يجب عليه أن يصلي في الوقت ولو جمعًا إذا كان معذورًا. نعم.\nالمقدم: جزاكم الله خيرًا، كيف تنصحون الناس إذا كانوا مجموعة، هل تنصحونهم بالتناوب بأن يقوم شخص بالعمل وآخر يؤدي الفريضة مثلاً سماحة الشيخ؟\nالشيخ: بالإمكان أن يتناوبوا إذا كان هناك عمل ضروري يتناوبون حتى يصلي كلهم في الوقت هذا يصلي في الوقت مثلما في صلاة الخوف طائفة يصلون مع الإمام ثم يذهبون يحرسون، ثم تأتي الطائفة الأخرى تصلي معه والحمد لله، فكذلك إذا كان في البحر أو في أي مكان والحاجة ماسة إلى أن يبقى بعض الناس في العمل لابد من البقاء فيه يصلي جماعة ثم إذا فرغوا صلت الجماعة الأخرى. نعم.\nالمقدم: جزاكم الله خيرًا، إذًا التناوب في مثل هذه الأحوال الضرورية وارد؟\nالشيخ: نعم. نعم.\nالمقدم: جزاكم الله خيرًا، وفقكم الله.","link":"https://binbaz.org.sa/fatwas/16570/متى-يعذر-المسلم-بتاخير-الصلاة-عن-وقتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_844/nour_84410.mp3","categories":["وقت الصلاة"]},{"id":17656,"question":"في ختام أسئلة هذا السائل يقول: يا سماحة الشيخ أرجو من سماحتكم أن تبينوا لي كيفية صلاة الخوف في القتال وعند اشتداد القتال؟","title":"كيفية صلاة الخوف عند اشتداد القتال","answer":"الجواب: راجعها في بلوغ المرام وعمدة الحديث موضحة في كتب الحديث والمنتقى، المنتقى وبلوغ المرام وعمدة الحديث بين ذكر فيها أحاديث صلاة الخوف، وهي أنواع إذا راجعتها عرفتها إن شاء الله.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16585/كيفية-صلاة-الخوف-عند-اشتداد-القتال","audio":"","categories":["صلاة الخوف","وقت الصلاة"]},{"id":17681,"question":"هذا سائل للبرنامج أرسل بمجموعة من الأسئلة يقول في هذا السؤال يا سماحة الشيخ فهد مبارك: ما حكم صلاة الفجر بعد الساعة العاشرة صباحًا؟","title":"ما حكم صلاة الفجر بعد طلوع الشمس؟","answer":"الجواب: لا يجوز له التأخير، الواجب على المسلم أن يصليها في الوقت، ويجعل من يوقظه: أما ساعة وإلا غيرها يستعين بالأسباب الأخرى من ساعة أو من أهله من يوقظه وينام مبكرًا لا يصيف لا يسهر حتى يصليها في الوقت مع المسلمين، لكن لو نام عنها يصليها الضحى، يقضيها، لكن لا يجوز له تعمد هذا أو التساهل في هذا. نعم.\nالمقدم: جزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/16614/ما-حكم-صلاة-الفجر-بعد-طلوع-الشمس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_595/59510.mp3","categories":["وقت الصلاة"]},{"id":18036,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من بريدة حي السالمية باعثتها إحدى الأخوات من هناك تقول (ع. م. ع) سؤالها يقول: سمعت أنه يستحب تأخير وقت صلاة العشاء للرجال، فهل يجوز ذلك للنساء؟","title":"استحباب تأخير وقت صلاة العشاء","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فنعم يستحب للرجال والنساء تأخير صلاة العشاء؛ لأنه عليه الصلاة والسلام لما أخرها ذات ليلة إلى نحو ثلث في الليل قال: إنه لوقتها لولا أن شق على أمتي عليه الصلاة والسلام، فإذا تيسر تأخيرها من دون مشقة فهو أفضل، فلو كان أهل قرية أو جماعة في السفر أخروها؛ لأنه أرفق بهم إلى ثلث الليل فلا بأس بذلك، بل هو أفضل، لكن لا يجوز تأخيرها بعد نصف الليل النهائي نصف الليل؛ لأن وقت العشاء يتحدد آخره بنصف الليل، يعني الاختياري نصف الليل، كما في حديث عبد الله بن عمرو عن النبي ﷺ أنه قال: وقت العشاء إلى نصف الليل أما إذا كان تأخيرها قد يشق على بعض الناس؛ فإن المشروع تعجيلها؛ ولهذا قال جابر : «كان النبي ﷺ في العشاء إذا رآهم اجتمعوا عجل، وإذا رآهم أبطئوا أخرها»، وقال أبو برزة : «كان النبي يستحب أن يؤخر من العشاء» عليه الصلاة والسلام. فالخلاصة: أن تأخيرها أفضل إذا تيسر ذلك بدون مشقة، ولكن لا يجوز تأخيرها بعد نصف الليل، بل النهاية نصف الليل. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17066/استحباب-تاخير-وقت-صلاة-العشاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_600/60001.mp3","categories":["وقت الصلاة"]},{"id":18273,"question":"من ليبيا منطقة واد العين رسالة بعث بها أحد الإخوة من هناك يقول: إدريس فرج الشاعري، أخونا له جمع من الأسئلة يسأل ويقول: نعلم أن تأخير الصلاة عن وقتها جرم وذنب وأي ذنب، ولكن هناك ظروف قد تؤدي بي إلى تأخير الصلاة عن وقتها، كأن أكون راعيًا للماشية، وأسمع الأذان، ولكن أخاف أن تتلف الضأن المزروعات سواء كانت لنا أو لجيراننا فتفوتنا الصلاة، حتى ولو كنت منفردًا أو يفوتنا وقت الظهر كما في المحاضرات أو العمل فما هي نصيحتكم؟","title":"حكم تأخير الصلاة لأجل الرعي وسماع المحاضرات","answer":"الجواب: الواجب على المؤمن أن يعتني بالصلاة في وقتها، وإذا كان حول المزارع التي يخشى عليها فليبدأ بإبعاد الماشية عن المزارع قبل الوقت حتى يتمكن من الصلاة في وقتها، أو الصلاة في الجماعة إذا كان حوله جماعة أو مسجد، ولا يتساهل في هذا الأمر حتى يضيق الوقت، الواجب عليه أن يتقي الله، وأن يشرع في أسباب حفظ الصلاة قبل وقتها حتى لا يقع في مشابهة أهل النفاق في إضاعة الصلوات: إِنَّ الْمُنَافِقِينَ يُخَادِعُونَ اللَّهَ وَهُوَ خَادِعُهُمْ وَإِذَا قَامُوا إِلَى الصَّلاةِ قَامُوا كُسَالَى [النساء:142]. فالواجب على المؤمن أن يعتني بهذا الأمر. وإن كان في محاضرات أو دراسة فإنه يقطع المحاضرة ويقطع الدراسة ويقوم للصلاة ويصلي مع المسلمين في مساجدهم. أما إذا كان في محل ليس حوله مساجد، إنما يؤدون المحاضرة أو الندوة ثم يصلون جميعًا في محلهم، كمحل بعيد عن المساجد، ليس بقربه مساجد أو في الصحراء أو في السفر، فكل هذا لا بأس به، إذا فرغوا صلوا في الوقت، لا يؤخرونها عن وقتها، بل يصلونها في الوقت، لكن من كان في عموم المساجد وفي القرية، أو في البلد فليس له أن يؤخر الصلاة بسبب المحاضرة، أو بسبب ندوة أو بسبب غنم، أو إبل أو غير ذلك. الواجب عليه أن يعتني بما يعينه على أداء الصلاة في جماعة، ولو كان بدؤه بإبعاد الغنم أو الإبل عن المزارع قبل دخول الوقت؛ حتى يتمكن من الصلاة في وقتها مع المسلمين، وليس له التساهل في هذا الأمر؛ لأنه يأثم بذلك. نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/17322/حكم-تاخير-الصلاة-لاجل-الرعي-وسماع-المحاضرات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_910/nour_91009.mp3","categories":["وقت الصلاة"]},{"id":18384,"question":"تقول السائلة: هل صلاة الصبح فرض أم نفل؟ ومتى وقتها؟ أرجو الإيضاح في ذلك جزاكم الله خيرًا.","title":"حكم صلاة الفجر ووقتها","answer":"الجواب: صلاة الفجر أحد الفرائض الخمس، إحدى الفرائض الخمس بإجماع المسلمين، يجب على كل مكلف وعلى كل مكلفة أداء الصلوات الخمس: الفجر ثنتين، والظهر أربع ركعات، والعصر أربع ركعات، والمغرب ثلاث ركعات، والعشاء أربع ركعات، يجب على جميع المكلفين من الرجال والنساء المسلمين، يجب عليهم أن يصلوا هذه الصلوات الخمس بطمأنينة وإخلاص لله. يصلي الفجر ركعتين، يقرأ الفاتحة وما تيسر معها في الأولى ثم يركع ويطمئن، ثم يرفع ويعتدل ويطمئن، ثم يسجد سجدتين، ويطمئن فيهما، ويقول فيها: سبحان ربي الأعلى، ويقول في الركوع: سبحان ربي العظيم، ويجلس بين السجدتين ويطمئن ويقول: رب اغفر لي.. رب اغفر لي، ويطمئن ويعتدل بعد الركوع وهو واقف مطمئن بعد الركوع قبل أن يسجد، ثم الركعة الثانية كذلك في الفجر، ثم يجلس ويقرأ التحيات المعروفة، ثم بعد قراءة التحيات والصلاة على النبي ﷺ، يتعوذ بالله من عذاب جهنم، ومن عذاب القبر، ومن فتنة المحيا والممات، ومن فتنة المسيح الدجال ، ويدعو بما تيسر من الدعاء، ومن ذلك اللهم أعني على ذكرك، وشكرك وحسن عبادتك، ثم يسلم تسليمتين: السلام عليكم ورحمة الله عن يمينه، السلام عليكم ورحمة الله عن يساره. وفي الظهر أربع ركعات، يصلي ركعتين بالفاتحة، وما تيسر معها، ثم يجلس للتشهد الأول يقرأ التحيات إلى الشهادتين، وإذا صلى على النبي ﷺ يكون أفضل، ثم يقوم يأتي بالركعة الثالثة والرابعة. والعصر كذلك، والعشاء كذلك أربع ركعات، أما المغرب فثلاث، يصلي ركعتين ويجلس في التشهد الأول، ثم يقوم ويأتي بركعة ثالثة، ويجلس للتشهد الأخير بعد الصلاة على النبي والدعاء يسلم المغرب هكذا. إلا المسافر فإنه يصلي الظهر ركعتين، والعصر ركعتين، والعشاء ركعتين قصرًا، إذا كان مسافرًا، فإنه يصلي الظهر ركعتين يقصرها، والعصر ركعتين، والعشاء ركعتين، أما الفجر فعلى حالها في السفر والحضر، وهكذا المغرب على حالها في السفر والحضر. والواجب على كل مكلف أن يتعلم ويتفقه في الدين، هذا هو الواجب؛ لأنهم خلقوا لعبادة الله، الله يقول سبحانه: وَمَا خَلَقْتُ الْجِنَّ وَالإِنسَ إِلَّا لِيَعْبُدُونِ[الذاريات:56] والصلوات من هذه العبادة الذي أنت مخلوق لها، فيجب أن تتعلم ويجب على المرأة أن تتعلم، وتسأل أهل العلم حتى تفقه دين الله، وحتى تكون على بينة، وهكذا الرجل يقول النبي ﷺ: من يرد الله به خيرًا يفقهه في الدين ويقول ﷺ: من دل على خير فله مثل أجر فاعله ويقول عليه الصلاة والسلام: من سلك طريقًا يلتمس فيه علمًا سهل الله له به طريقًا إلى الجنة. وأنا أنصح بسماع إذاعة القرآن فيها علم، إذاعة القرآن فيها نور على الدرب للعلماء، فيها محاضرات وندوات علمية مفيدة، أنصح جميع إخواني وأخواتي في الله أن يستمعوا لإذاعة القرآن، ويستفيدوا منها، وأن يسألوا أهل العلم عما أشكل عليهم من طريق الهاتف .. التلفون، أو من طريق المكاتبة، لا بد من التفقه في الدين، لا بد من السؤال، وفق الله الجميع. نعم. المقدم: اللهم آمين، جزاكم الله خيرًا على هذا التوجيه المبارك سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17464/حكم-صلاة-الفجر-ووقتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_784/nour_78408.mp3","categories":["حكم الصلاة وأهميتها","وقت الصلاة"]},{"id":18474,"question":"أختنا تسأل أيضًا وتقول: عندما يؤذن المؤذن، هل يصح للمرأة أن تصلي أم تتأخر وقتًا قليلًا حتى تقام الصلاة، وبعد ذلك تصلي لنفسها؟","title":"هل تصلي المرأة بعد الأذان أم تنتظر الإقامة من المساجد؟","answer":"الجواب: ليس لها ارتباط بالرجال، بل متى دخل الوقت؛ فإنها تصلي سواء كان ذلك قبل صلاة الرجال أو بعد صلاة الرجال، وليس لها ارتباط بإقامة الصلاة في المساجد، بل متى أذن ومضى بعض الوقت؛ فإنها تصلي ولا تبادر من حين الأذان؛ لأنه قد يكون الأذان مبكرًا، فإذا تركت قليلًا وتمهلت قليلًا، ثم تصلي فهو أحسن، احتياطًا من دخول الوقت. نعم.","link":"https://binbaz.org.sa/fatwas/17564/هل-تصلي-المراة-بعد-الاذان-ام-تنتظر-الاقامة-من-المساجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_866/nour_86605.mp3","categories":["صلاة الجمعة","وقت الصلاة","قضايا المرأة"]},{"id":18526,"question":"السؤال الثاني: ما حكم من أخر صلاة فرض ولو دقائق معدودة بعد أن سمع الأذان، وذلك بدون عذر قوي؟","title":"ما حكم من أخر صلاة فرض ولو دقائق معدودة؟","answer":"الجواب: السنة أن يتأخر بعد الأذان قليلًا، وألا يبادر بعد الأذان في الحال؛ لأنه قد يبكر في الأذان، قد يكون أذن قبل الوقت، فالاحتياط أن يكون فعل الصلاة بعد الأذان بدقائق كربع ساعة، ثلث ساعة، نصف ساعة، كل هذا لا بأس به، لكن المغرب الأولى فيها التبكير أكثر من غيرها؛ لأن وقتها أقصر من غيرها، فالأفضل التبكير فيها كما كان النبي يبكر فيها -عليه الصلاة والسلام- وإذا صلاها بعد الأذان بعشر دقائق، بثمان دقائق، فحسن، وإن أخرها ربع ساعة، ثلث، فلا حرج في ذلك. المقصود: أنه لا حرج أن يصلي الصلاة في أول وقتها، أو في وسط وقتها، أو في آخر وقتها، لكن الأفضل أن تكون في أول وقتها، هذا هو الأفضل إلا إذا اشتد الحر في الظهر، فالأفضل أن يؤخرها حتى ينكسر الحر، وهكذا في العشاء الأفضل فيها التأخير في الأصل إلى الثلث الأول من الليل، إلا إذا اجتمع أهل المسجد، فإن السنة أن يبادر وألا يعطلهم، وهكذا المريض والمرأة في البيت إذا أخرت بعض الوقت في العشاء فهو أفضل، وإن اقتضت المصلحة التبكير بأنها تحتاج إلى النوم مبكرة وهكذا المريض بكر بها. فالخلاصة: أن العشاء يستحب فيها التأخير إلى ثلث الليل، أو ما يقارب ذلك، هذا هو الأفضل إذا لم يكن في هذا مضرة على أحد، وهكذا في صلاة الجماعة في العشاء يستحب للإمام أن يؤخرها إذا لم يجتمعوا، فإن اجتمعوا عجل، وهكذا كان النبي يفعل -عليه الصلاة والسلام- إذا رآهم اجتمعوا عجل، وإذا رآهم أبطئوا أخرها -عليه الصلاة والسلام- والظهر كذلك لشدة الحر، إذا اشتد الحر كان ﷺ يبرد بالظهر، ويأمر بالإبراد، هذا هو السنة، نعم.","link":"https://binbaz.org.sa/fatwas/17619/ما-حكم-من-اخر-صلاة-فرض-ولو-دقاىق-معدودة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_869/nour_86903.mp3","categories":["وقت الصلاة"]},{"id":18535,"question":"السؤال الثاني: ما حكم من أخر صلاة فرض ولو دقائق معدودة بعد أن سمع الأذان، وذلك بدون عذر قوي؟","title":"ما حكم من أخر صلاة فرض ولو دقائق معدودة؟","answer":"الجواب: السنة أن يتأخر بعد الأذان قليلًا، وألا يبادر بعد الأذان في الحال؛ لأنه قد يبكر في الأذان، قد يكون أذن قبل الوقت، فالاحتياط أن يكون فعل الصلاة بعد الأذان بدقائق كربع ساعة، ثلث ساعة، نصف ساعة، كل هذا لا بأس به، لكن المغرب الأولى فيها التبكير أكثر من غيرها؛ لأن وقتها أقصر من غيرها، فالأفضل التبكير فيها كما كان النبي يبكر فيها -عليه الصلاة والسلام- وإذا صلاها بعد الأذان بعشر دقائق، بثمان دقائق، فحسن، وإن أخرها ربع ساعة، ثلث، فلا حرج في ذلك. المقصود: أنه لا حرج أن يصلي الصلاة في أول وقتها، أو في وسط وقتها، أو في آخر وقتها، لكن الأفضل أن تكون في أول وقتها، هذا هو الأفضل إلا إذا اشتد الحر في الظهر، فالأفضل أن يؤخرها حتى ينكسر الحر، وهكذا في العشاء الأفضل فيها التأخير في الأصل إلى الثلث الأول من الليل، إلا إذا اجتمع أهل المسجد، فإن السنة أن يبادر وألا يعطلهم، وهكذا المريض والمرأة في البيت إذا أخرت بعض الوقت في العشاء فهو أفضل، وإن اقتضت المصلحة التبكير بأنها تحتاج إلى النوم مبكرة وهكذا المريض بكر بها. فالخلاصة: أن العشاء يستحب فيها التأخير إلى ثلث الليل، أو ما يقارب ذلك، هذا هو الأفضل إذا لم يكن في هذا مضرة على أحد، وهكذا في صلاة الجماعة في العشاء يستحب للإمام أن يؤخرها إذا لم يجتمعوا، فإن اجتمعوا عجل، وهكذا كان النبي يفعل -عليه الصلاة والسلام- إذا رآهم اجتمعوا عجل، وإذا رآهم أبطئوا أخرها -عليه الصلاة والسلام- والظهر كذلك لشدة الحر، إذا اشتد الحر كان ﷺ يبرد بالظهر، ويأمر بالإبراد، هذا هو السنة، نعم.","link":"https://binbaz.org.sa/fatwas/17619/ما-حكم-من-اخر-صلاة-فرض-ولو-دقاىق-معدودة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_869/nour_86903.mp3","categories":["وقت الصلاة"]},{"id":18781,"question":"نعود مع مطلع هذه الحلقة إلى رسالة وصلت إلى البرنامج من الإمارات العربية المتحدة، باعثتها إحدى الأخوات المستمعات من هناك تقول: المرسلة (ص. ع) أختنا عرضنا لها قضيتين في حلقة مضت، وفي هذه الحلقة لها قضية تقول فيها:وجهونا حول امرأة متزوجة من رجل يعيش وسط أسرة كبيرة، وتتأخر عن أداء صلاة الظهر إلى الثانية والنصف ظهرًا، وإذا نصحتها قالت: إن أهل زوجها إذا تأخرت في وضع الغداء تلقى منهم توبيخًا شديدًا، ولو اعتذرت بالصلاة، وجهوها سماحة الشيخ ووجهوا أسرتها، جزاكم الله خيرًا.","title":"حكم تأخير المرأة الصلاة بسبب أعمال البيت","answer":"الجواب: بسم الله الرحمن الرحيم  الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد:  فتأخير الصلاة إلى آخر الوقت لا حرج فيه، لكن يفوت الفضل؛ فإن أداءها في أول الوقت أفضل وأعظم أجرًا، لكن إذا دعت الحاجة إلى التأخير فلا حرج؛ بشرط أن تصلى في الوقت، وأن تحرص على أن تصليها في الوقت قبل دخول وقت العصر. وهكذا كل صلاة يجب أن تؤدى في الوقت، لكن كونها تؤدى في أول الوقت هذا هو الأفضل، وفي وسطه أفضل من آخره، ولكن إذا أدتها في الآخر فلا حرج، وإذا كان عليها مشقة من أدائها في أول الوقت؛ لأجل ما يقول لها، تقول لها الأسرة التي هي عندهم؛ لا حرج عليها، لكن ينبغي للأسرة أن يشجعوها على أداء الصلاة في أول الوقت، وأن يشكروها على عنايتها بالصلاة، والصلاة وقتها قليل، والحمد لله، ليس فيه مشقة. فالمشروع للجميع العناية بأدائها في أول الوقت، والتعاون في ذلك، وهم يعينونها على ذلك، لكن لو أخرتها حتى صلتها في آخر الوقت فلا حرج، لكن مع العناية التامة بعدم تأخيرها إلى وقت آخر، فتحرص على أن تؤدى في الوقت، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/17907/حكم-تاخير-المراة-الصلاة-بسبب-اعمال-البيت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_736/nour_73601.mp3","categories":["وقت الصلاة"]},{"id":18887,"question":"يقول: قمت من النوم، وكانت الشمس مصفرة تقريبًا، فصليت العصر، هل صلاتي صحيحة؟","title":"حكم تأخير صلاة العصر إلى اصفرار الشمس","answer":"الجواب: صحيحة، وعليك التوبة إلى الله؛ لأنه لا يجوز تأخير العصر إلى أن تصفر الشمس، يجب أن تصلى قبل اصفرار الشمس، وعليك أن تخبر أهلك أن يوقظوك، أو تركد الساعة على وقت تدرك الصلاة فيه مع المسلمين، ما يجوز لك التساهل، يجب أن تصلي مع المسلمين في مساجدهم صلاة العصر وغيرها. ولا يجوز تأخير صلاة العصر إلى أن تصفر الشمس لا للرجل ولا للمرأة، يجب على الرجل والمرأة أداء صلاة العصر قبل أن تصفر الشمس، وعلى الرجل خاصة أن يصليها في الجماعة في مساجد الله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18028/حكم-تاخير-صلاة-العصر-الى-اصفرار-الشمس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_736/nour_73618.mp3","categories":["وقت الصلاة"]},{"id":18898,"question":"لأخينا سؤال آخر يقول فيه: إنه يعمل في إحدى المؤسسات، وليس هناك وقت محدد لأداء الصلوات، ويرجو التوجيه، ويقول: إن المسؤول عن الشركة يعارضه إذا أراد تأدية صلاته.","title":"حكم من يمنعه مسؤوله من تأدية الصلاة وقت العمل","answer":"الجواب: الصلاة لا بد منها، وهي مستثناة من العمل، والذي يقوم على الشركة إذا أبى لا يطاع، يقول النبي ﷺ: إنما الطاعة في المعروف، لا طاعة لمخلوق في معصية الخالق فإذا جاء وقت الصلاة فالواجب عليك وعلى إخوانك المسلمين أن تصلوا جميعًا الصلاة في وقتها ظهرًا أو عصرًا أو مغربًا أو عشاءً أو فجرًا على حسب حالكم في العمل، إذا جاء الوقت صلوا جميعًا، ثم ارجعوا إلى عملكم. وإذا كان المأمور من جهة الشركة يأبى ذلك، فارفعوا أمره إلى من فوقه، وأخبروه أن هذا أمر لا بد منه، وأنه لا يجوز لكم أن تتأخروا عن صلاتكم لأجل قوله أو قول غيره، ولكن لا مانع من تأخيرها عن أول الوقت إذا دعت الحاجة إلى ذلك، وأن تصلوها في وسط الوقت لا حرج في ذلك، نعم.","link":"https://binbaz.org.sa/fatwas/18039/حكم-من-يمنعه-مسووله-من-تادية-الصلاة-وقت-العمل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_923/nour_92306.mp3","categories":["وقت الصلاة"]},{"id":18906,"question":"إذا كان هناك شخص ما، صلى أو ابتدأ الصلاة في وقت متأخر، فهل يجب عليه القضاء، أم يكفي أن يتوب توبة نصوحًا، ولا يترك الصلاة بعدها أبدًا؟ وما دليل ذلك؟","title":"تاب وواظب على الصلاة فهل يجب عليه قضاء ما فات؟","answer":"الجواب: إذا صلى، ثم بان أنه صلى قبل الوقت؛ عليه أن يعيد في الوقت، أما إن صلاها بعد الوقت فقد أساء، وعليه التوبة إلى الله من ذلك، وعدم العودة إلى التأخير، وصلاته صحيحة، وتسمى قضاءً للفريضة، وعليه التوبة إلى الله من ذلك، وكثير من أهل العلم يقولون: إنه إذا تعمد تأخيرها عن وقتها؛ صار بهذا كافرًا، فعليه التوبة إلى الله من ذلك، ولا قضاء عليه؛ لأن ذنبه عظيم، والقضاء إنما يدخل في العمل الذي ليس كبيرًا جدًا، أما إذا عظم الأمر؛ فليس له إلا التوبة، ولهذا القتل العمد ليس فيه كفارة، إنما فيه الدية أو القتل القصاص، والكفارة إنما تكون في القتل الخطأ وشبه العمد. وهكذا إذا نسي الإنسان، فلم يصل أو نام عن الصلاة؛ قضاها بعد ذلك ولا شيء عليه، لكن إذا تعمد بأن أخر الفريضة إلى بعد طلوع الشمس، أو أخر العصر إلى بعد المغرب، فهذا قد فعل منكرًا عظيمًا؛ فعليه التوبة إلى الله من ذلك، وهل يقضي أو ما يقضي؟ على خلاف بين أهل العلم: من كفره قال: لا يقضي، ومن قال: إنه ليس بكافر؛ أمره بالقضاء، لما تركه حتى خرج الوقت، فالواجب على الرجال والنساء الحذر من تأخير الصلاة عن أوقاتها، والتوبة إلى الله من ذلك، وليس على من تركها قضاء، إنما عليه التوبة، هذا هو الأصوب، وهذا هو الصحيح إذا كان تركها عمدًا وتساهلًا، حتى أظهر وقتها الضروري، أما وقتها المختار، فلا يمنع من قضائها، فلو أخر العصر حتى اصفرت الشمس؛ فعليه أن يقضي مع التوبة والاستغفار، أما إذا أخرها حتى غابت الشمس؛ فهذا هو محل الكفر لمن أخرها عمدًا عدوانًا عند بعض أهل العلم. وكثير من أهل العلم يقولون: إنه يقضي، وعليه التوبة إلى الله من ذلك، فينبغي للمؤمن -في مثل هذه الأمور- أن يحذر غاية الحذر من تأخير الصلاة عن وقتها، وأن يكون عنده من العناية التامة بالصلاة في وقتها ما يجعله يحافظ عليها، ويؤديها في الجماعة مع إخوانه في المساجد، في وقتها. وعلى المرأة كذلك أن تعتني بها في وقتها، وأن تؤديها في وقتها في بيتها، وأن تحذر التساهل في ذلك، ولا فرق بين الفجر وغيرها، لكن المجموعة إلى غيرها أسهل من التي لا تجمع، فالظهر مع العصر، والمغرب مع العشاء، أسهل من تأخير الفجر إلى بعد طلوع الشمس، وأسهل من تأخير العصر إلى بعد غروب الشمس، وإن كان الواجب على جميع المسلمين أن يصلي كل صلاة في وقتها، فالظهر في وقتها، والعصر في وقتها، والمغرب في وقتها، والعشاء في وقتها، إلا من له عذر -كالمريض والمسافر- فلا بأس بالجمع بين الصلاتين: الظهر والعصر، والمغرب والعشاء، نسأل الله للجميع الهداية والتوفيق. المقدم: اللهم آمين.","link":"https://binbaz.org.sa/fatwas/18050/تاب-وواظب-على-الصلاة-فهل-يجب-عليه-قضاء-ما-فات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_881/nour_88104.mp3","categories":["وقت الصلاة"]},{"id":18908,"question":"السؤال الثاني: ما حكم من أخر صلاة فرض ولو دقائق معدودة بعد أن سمع الأذان؛ وذلك بدون عذر قوي؟","title":"حكم تأخير الصلاة بعد الأذان بدقائق","answer":"الجواب: السنة أن يتأخر بعد الأذان قليلًا، وألا يبادر بعد الأذان في الحال؛ لأنه قد يبكر في الأذان، قد يكون أذن قبل الوقت، فالاحتياط أن يكون فعل الصلاة بعد الأذان بدقائق: كربع ساعة، ثلث ساعة، نصف ساعة، كل هذا لا بأس به، لكن المغرب الأولى فيها التبكير أكثر من غيرها؛ لأن وقتها أقصر من غيرها، فالأفضل التبكير بها كما كان النبي يبكر بها -عليه الصلاة والسلام- وإذا صلاها بعد الأذان بعشر دقائق، بثمان دقائق فحسن، وإن أخر ربع ساعة، ثلث ساعة؛ فلا حرج في ذلك. المقصود: أنه لا حرج أن يصلي الصلاة في أول وقتها، أو في وسط وقتها، أو في آخر وقتها، لكن الأفضل أن تكون في أول وقتها هذا هو الأفضل، إلا إذا اشتد الحر في الظهر، فالأفضل أن يؤخرها حتى ينكسر الحر، وهكذا في العشاء الأفضل فيها التأخير في الأصل إلى الثلث الأول من الليل، إلا إذا اجتمع أهل المسجد، فإن السنة أن يبادر وألا يعطلهم، وهكذا المريض والمرأة في البيت إذا أخرت بعض الوقت في العشاء فهو أفضل، وإذا اقتضت المصلحة التبكير؛ لأنها تحتاج إلى النوم مبكرة، وهكذا المريض بكر بها. فالخلاصة: أن العشاء يستحب فيها التأخير إلى ثلث الليل، أو ما يقارب ذلك، هذا هو الأفضل، إذا لم يكن في هذا مضرة على أحد، وهكذا في صلاة الجماعة في العشاء، يستحب للإمام أن يؤخرها، إذا لم يجتمعوا، فإن اجتمعوا عجل، وهكذا كان النبي يفعل -عليه الصلاة والسلام- إذا رآهم اجتمعوا عجل، وإذا رآهم أبطئوا أخرها -عليه الصلاة والسلام-.  والظهر كذلك في شدة الحر، إذا اشتد الحر، كان الرسول ﷺ يبرد بالظهر، ويأمر بالإبراد، هذا هو السنة، نعم.","link":"https://binbaz.org.sa/fatwas/18046/حكم-تاخير-الصلاة-بعد-الاذان-بدقاىق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_881/nour_88102.mp3","categories":["وقت الصلاة"]},{"id":19162,"question":"من الطائف رسالة من إحدى الأخوات المستمعات تقول أم علي، أم علي لها سؤالان، في سؤالها الأول تقول: إذا حضرت الصلاة وهي تسمع خطبة أو تسمع القرآن هل تؤخر الصلاة حتى نهاية الخطبة، أو القرآن؟ أو تصلي من حين دخول الوقت؟ جزاكم الله خيرًا.","title":"حكم تأخير الصلاة عن أول وقتها للانشغال بسماع خطبة","answer":"لا مانع من تأجيل الصلاة حتى تسمع الفائدة - الخطبة والموعظة - لا مانع من ذلك، ولكن بشرط ألا يفوت الوقت، أما تأخيرها عن أول الوقت نص ساعة ثلث ساعة فلا بأس بذلك، الأمر واسع، لكن صلاتها في أول الوقت أفضل، وإذا أخرتها لمصلحة عظيمة لسماع موعظة، أو تعليم جاهل، أو أمر بمعروف، أو نهي عن منكر .. أو ما أشبه ذلك مما يدعو إلى تأخيرها بعض الوقت فلا بأس بذلك؛ لأن هذه مصلحة عظيمة والحمد لله. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18367/حكم-تاخير-الصلاة-عن-اول-وقتها-للانشغال-بسماع-خطبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_798/nour_79810.mp3","categories":["وقت الصلاة"]},{"id":19267,"question":"إذا كان الفجر يؤذن في الخامسة وخمس دقائق -مثلًا- وأصلي في السادسة، هل هذا يعتبر من التأخير؟","title":"حكم صلاة الفجر بعد الأذان بأكثر من نصف ساعة","answer":"الجواب: ليس من التأخير، لكن الأفضل البدار، ولو أخرت إلى أن أسفر فلا بأس، لكن البدار بغلس، وهو اختلاط الليل بالنهار، يعني: اختلاط الظلمة بالنور بعد طلوع الفجر بربع ساعة.. ثلث ساعة..نصف ساعة، يكون هذا أفضل، لكن لو أخرت أو أخر الرجل قبل طلوع الشمس فلا حرج في ذلك؛ لكنه ترك للأفضل، السنة أن يصلى بغلس الرجال والنساء، يصلى الفجر بغلس، المرأة في بيتها، والرجل في المسجد، وإن صلت مع الرجال متسترة متحجبة متباعدة عن أسباب الفتنة فلا بأس، والتأخير لا حرج فيه؛ لكنه يفوت الأفضل، ولا يجوز التأخير إلى طلوع الشمس، بل هذا حرام ومنكر، بل يجب أن تفعل قبل طلوع الشمس، تفعل كلها. نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/18465/حكم-صلاة-الفجر-بعد-الاذان-باكثر-من-نصف-ساعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_892/nour_89210.mp3","categories":["وقت الصلاة"]},{"id":19314,"question":"هل من الأفضل تأخير صلاة العشاء، وكم يكون مقدار هذا التأخير؟","title":"هل من الأفضل تأخير العشاء، وكم يكون مقدار هذا التأخير؟","answer":"الجواب: نعم، الأفضل إذا لم يكن هناك حرج التأخير إلى ثلث الليل، ولا بأس أن يؤخر إلى قبيل نصف الليل، ولا يؤخر عن نصف الليل، فإن نهاية الوقت نصف الليل، يقول النبي ﷺ: ووقت العشاء ما لم ينتصف الليل إلى نصف الليل، فإذا أخر إلى ثلث الليل مثل المرأة في بيتها، ومثل جماعة في قرية أو في محل يختارون التأخير ولا مشقة عليهم فلا بأس أن يؤخروا، يقول ﷺ لما أخر ذات ليلة حتى قرب النصف، وفي بعض الروايات: (إلى ثلث الليل) قال: إنه لوقتها لولا أن أشق على أمتي. فالحاصل: أنه إذا اتفق أهل قرية، أو جماعة مسافرون، أو أهل البيت من المرضى والنساء أن يؤخروها، وأن هذا لا مشقة عليهم فيه فهو أفضل، تأخيرها عن أول وقتها إلى وسط وقتها، أو إلى ثلث الليل، أو إلى قبيل النصف هو أفضل، كما قاله النبي عليه الصلاة والسلام. المقدم: لكن مسايرة الجماعة يرى سماحتكم أنه أفضل؟ الشيخ: نعم، أما إذا كان جماعة لا حرج، أمر الجماعة، وعدم المشقة عليهم في المساجد تصلى في أول وقتها، وكان يستحب أن يؤخر العشاء عليه الصلاة والسلام فيؤخر بعض الشيء حتى يتلاحقوا ثم يصلي بهم، ولا يشق عليهم بالتأخير الطويل، متى تجمعوا وكان عليه الصلاة والسلام إذا رآهم اجتمعوا عجل، وإذا رآهم أبطئوا أخر عليه الصلاة والسلام يراعيهم في العشاء؛ لأن الناس قد تكون لهم حاجات بين العشاءين، قد يكون عندهم ضيوف، قد يكون أشياء فينبغي لإمام القرية وإمام المسجد أن يلاحظ أحوال جماعته، فإذا رآهم اجتمعوا عجل ولم يشق عليهم، وإذا رآهم تأخروا أخر مراعاة لأحوالهم عملًا بسنته عليه الصلاة والسلام. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18503/هل-من-الافضل-تاخير-العشاء-وكم-يكون-مقدار-هذا-التاخير ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_894/nour_89405.mp3","categories":["وقت الصلاة"]},{"id":19415,"question":"مستمع بعث برسالة يقول فيها: بلغني أن بعض المرضى، والنساء يبادرون بإقامة صلاة الظهر يوم الجمعة عند سماع النداء الثاني، وحيث إن أكثر خطباء الجوامع يبدؤون بخطبة الجمعة بعد رفع النداء الثاني، وذلك قبل دخول وقت الظهر بعشرين أو خمس عشرة دقيقة، فآمل من سماحتكم توجيه الناس، جزاكم الله خيرًا.","title":"حكم صلاة الظهر عند الأذان الثاني للجمعة لأهل الأعذار","answer":"الجواب: الواجب على النساء والمرضى الذين يصلون في البيوت، أو في المستشفيات ألا يعجلوا؛ حتى يتحققوا دخول الوقت يوم الجمعة، وكذلك بقية الأيام، وعندهم التقاويم التي أصدرتها الأوقاف، في إمكانهم الاستفادة منها، ولا سيما يوم الجمعة؛ فإن بعض الخطباء قد يدخل المسجد، ويبدأ بالخطبة قبل الوقت، وقد يتساهل مع أنه ينبغي للخطباء ألا يبدؤوا إلا بعد الزوال، وألا يؤذن للجمعة إلا بعد الزوال، كما هو قول جمهور أهل العلم. وأكثر العلماء على أن الخطبة تكون بعد الزوال، ولا تصلح قبل الزوال، فينبغي للخطباء أن يحتاطوا لدينهم، وأن يحتاطوا لإخوانهم المسلمين؛ فيكون الدخول والصلاة بعد الأذان - يعني بعد الزوال - يأتي إلى الجمعة بعد الزوال، والساعات موجودة ومتوفرة والحمد لله، حتى يؤذن المؤذن بعد الزوال، وتكون الخطبة والجمعة بعد الزوال فيحتاطوا للمسلمين، ويبتعدوا عما يسبب وقوعهم فيما يخالف الشرع المطهر، ولا سيما المرضى والنساء. وعلى النساء، وعلى المرضى التثبت في الأمور، وألا يصلوا إلا بعد دخول الوقت، والتأكد من دخول الوقت: الظهر، والعصر، والمغرب، والعشاء، والفجر في الجمعة وغيرها. هذا هو الواجب على الجميع.","link":"https://binbaz.org.sa/fatwas/18642/حكم-صلاة-الظهر-عند-الاذان-الثاني-للجمعة-لاهل-الاعذار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_936/nour_93611.mp3","categories":["صلاة الجمعة","وقت الصلاة","قضايا المرأة"]},{"id":19547,"question":"يقول هذا السائل: ما حكم صلاة الفجر بعد الساعة العاشرة صباحًا؟","title":"حكم تأخير صلاة الفجر إلى بعد طلوع الشمس","answer":"الجواب: الواجب أن يصلي مع المسلمين في وقتها بعد الأذان، يصلي في المساجد، وليس له التخلف ولا يجوز تأخيرها إلى طلوع الشمس. المقدم: شكر الله لكم يا سماحة الشيخ، وبارك الله فيكم وفي علمكم، ونفع بكم المسلمين.","link":"https://binbaz.org.sa/fatwas/18801/حكم-تاخير-صلاة-الفجر-الى-بعد-طلوع-الشمس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_946/nour_94629.mp3","categories":["صلاة الجماعة","وقت الصلاة"]},{"id":19634,"question":"يقول هذا السائل من اليمن: ما حكم من كان مقصرًا في أداء صلاة الفجر تهاونًا بها؛ حيث أنه لا يصليها إلا بعد شروق الشمس، وهل يعد من المنافقين؟ أفتونا مأجورين.","title":"حكم التساهل في صلاة الفجر حتى يخرج وقتها","answer":"الجواب: من تعمد ترك الصلاة حتى يخرج وقتها كفر في أصح قولي العلماء؛ لقول النبي ﷺ: بين الرجل وبين الكفر والشرك ترك الصلاة والذين يتعمدون تأخير الفجر حتى تطلع الشمس يكفرون عند جمع من أهل العلم؛ لأن الحديث يعمهم. فالواجب الحذر من ذلك، والواجب أن تصلى في وقتها مع الجماعة في المساجد، وإن صلاها في البيت أجزأت وسلم من الكفر لكنه عاصي؛ لأنه ترك الجماعة ولم يصل مع المسلمين في مساجدهم، والنبي ﷺ أمر بالصلاة في المساجد، وقال عليه الصلاة والسلام في الحديث الصحيح: من سمع النداء فلم يأت فلا صلاة له إلا من عذر قيل لابن عباس: ما هو العذر؟ قال: «خوف أو مرض». وجاءه رجل أعمى، فقال: «يا رسول الله! هل لي من رخصة أن أصلي في بيتي؟ فقال ﷺ: هل تسمع النداء بالصلاة؟ قال: نعم، قال: فأجب أعمى أمره أن يجيب يصلي في الجماعة. وقال عليه الصلاة والسلام: لقد هممت أن آمر بالصلاة فتقام، ثم آمر الرجل فيؤم الناس، ثم أنطلق برجال معهم حزم من حطب إلى قوم لا يشهدون الصلاة فأحرق عليهم بيوتهم. وقال ابن مسعود : \"لقد رأيتنا وما يتخلف عنها -يعني: في الجماعة في المساجد- إلا منافق معلوم النفاق أو مريض\" نسأل الله العافية. فالواجب الحذر والواجب أن تؤدى مع المسلمين في المساجد، ولا يجوز التخلف عنها في البيوت، نسأل الله للجميع الهداية. نعم. المقدم: اللهم آمين، حفظكم الله.","link":"https://binbaz.org.sa/fatwas/18904/حكم-التساهل-في-صلاة-الفجر-حتى-يخرج-وقتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_949/nour_94921.mp3","categories":["وقت الصلاة"]}]
